const debounce = (fn, delay) => {
  let timeoutId;
  let lastArgs;
  const debounced = (...args) => {
    lastArgs = args;
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => {
      timeoutId = undefined;
      fn(...lastArgs);
    }, delay);
  };
  debounced.flush = () => {
    if (timeoutId === undefined) return;
    clearTimeout(timeoutId);
    timeoutId = undefined;
    fn(...(lastArgs || []));
  };
  debounced.cancel = () => {
    clearTimeout(timeoutId);
    timeoutId = undefined;
    lastArgs = undefined;
  };
  return debounced;
};

function parseDueStr(s) {
  if (!s) return null;
  s = s.trim();
  let m = s.match(/^\d{4}-\d{2}-\d{2}$/);
  if (m) return new Date(s + "T12:00:00");
  s = s.replace(/[.]/g, "/").replace(/\s+/g, "");
  const parts = s.split("/");
  if (parts.length === 3) {
    let [mm, dd, yy] = parts;
    if (yy.length === 2) yy = "20" + yy;
    const iso = `${yy}-${mm.padStart(2, "0")}-${dd.padStart(2, "0")}T12:00:00`;
    const d = new Date(iso);
    if (!isNaN(d)) return d;
  }
  const d2 = new Date(s);
  return isNaN(d2) ? null : d2;
}

function dueState(dueStr) {
  const d = parseDueStr(dueStr);
  if (!d) return "ok";
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const dayOfWeek = today.getDay();
  const startOfWeek = new Date(today);
  startOfWeek.setDate(today.getDate() - dayOfWeek);
  const endOfWeek = new Date(startOfWeek);
  endOfWeek.setDate(startOfWeek.getDate() + 6);
  endOfWeek.setHours(23, 59, 59, 999);

  if (d < today) return "overdue";
  if (d >= startOfWeek && d <= endOfWeek) return "dueSoon";
  return "ok";
}

// The date that drives scheduling. The internal date wins; a deliverable that only
// has a hard deadline falls back to it so it still sorts, filters, and shows up in
// the week view instead of silently dropping out of every dated list.
function getEffectiveDueStr(deliverable) {
  const internal = String(deliverable?.due || "").trim();
  return internal || String(deliverable?.hardDue || "").trim();
}

function getHardDueStr(deliverable) {
  return String(deliverable?.hardDue || "").trim();
}

// "critical" | "overdue" | "dueSoon" | "ok" — a missed hard deadline outranks a
// slipped internal target.
function deliverableDueState(deliverable) {
  const hard = parseDueStr(getHardDueStr(deliverable));
  if (hard && !isFinished(deliverable)) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    if (hard < today) return "critical";
  }
  return dueState(getEffectiveDueStr(deliverable));
}

function isDeliverableHardDueMissed(deliverable) {
  return deliverableDueState(deliverable) === "critical";
}

function humanDate(s) {
  const d = parseDueStr(s);
  if (!d) return "";
  return d.toLocaleDateString(undefined, {
    year: "2-digit",
    month: "2-digit",
    day: "2-digit",
  });
}

function formatDueDateShort(date) {
  if (!(date instanceof Date) || isNaN(date)) return "";
  return date.toLocaleDateString(undefined, {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  });
}

// Date validation and formatting functions
function autoFormatDateInput(inputElement) {
  let value = inputElement.value.trim();
  if (!value) return;

  // Remove extra whitespace and normalize separators
  value = value.replace(/\s+/g, '').replace(/[.]/g, '/');

  // Check if it's MM/DD/YY format (2-digit year)
  const parts = value.split('/');
  if (parts.length === 3) {
    let [mm, dd, yy] = parts;

    // If year is 2 digits, expand to 4 digits
    if (yy.length === 2) {
      yy = '20' + yy;
      inputElement.value = `${mm}/${dd}/${yy}`;
    }
  }
}

function validateDueDateInput(inputElement) {
  const value = inputElement.value.trim();
  const validationMsg = inputElement.parentElement.querySelector('.date-validation-msg');

  // Clear previous validation
  inputElement.classList.remove('input-error', 'input-warning');
  if (validationMsg) validationMsg.textContent = '';

  // Empty is valid (optional field)
  if (!value) {
    return true;
  }

  // Check for incomplete date (missing year)
  const parts = value.replace(/[.\s]/g, '/').split('/');
  if (parts.length < 3) {
    inputElement.classList.add('input-error');
    if (validationMsg) {
      validationMsg.textContent = 'Incomplete date. Use MM/DD/YYYY';
      validationMsg.className = 'date-validation-msg error';
    }
    return false;
  }

  // Check if year is present and valid (at least 2 digits)
  const yearPart = parts[2];
  if (!yearPart || yearPart.length < 2) {
    inputElement.classList.add('input-error');
    if (validationMsg) {
      validationMsg.textContent = 'Year required. Use MM/DD/YYYY';
      validationMsg.className = 'date-validation-msg error';
    }
    return false;
  }

  // Try to parse
  const parsed = parseDueStr(value);

  // Invalid format
  if (!parsed) {
    inputElement.classList.add('input-error');
    if (validationMsg) {
      validationMsg.textContent = 'Invalid date format. Use MM/DD/YYYY';
      validationMsg.className = 'date-validation-msg error';
    }
    return false;
  }

  // Valid but in the past
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  if (parsed < today) {
    inputElement.classList.add('input-warning');
    if (validationMsg) {
      validationMsg.textContent = 'Warning: This date is in the past';
      validationMsg.className = 'date-validation-msg warning';
    }
    return true; // Warning, not blocking
  }

  // Valid and future
  return true;
}

// Non-blocking nudge when the internal target sits after the hard deadline —
// still a legal state, just almost certainly a mistake.
function validateDeliverableDateOrder(card) {
  if (!card) return true;
  const dueInput = card.querySelector('.d-due');
  const hardDueInput = card.querySelector('.d-hard-due');
  if (!dueInput || !hardDueInput) return true;

  const due = parseDueStr(dueInput.value.trim());
  const hardDue = parseDueStr(hardDueInput.value.trim());
  if (!due || !hardDue || due <= hardDue) return true;

  // Leave hard errors from validateDueDateInput in place.
  if (dueInput.classList.contains('input-error')) return true;

  dueInput.classList.add('input-warning');
  const validationMsg = dueInput.parentElement.querySelector('.date-validation-msg');
  if (validationMsg) {
    validationMsg.textContent = 'Warning: Internal date is after the hard deadline';
    validationMsg.className = 'date-validation-msg warning';
  }
  return true;
}

function validateAllDueDates() {
  const inputs = document.querySelectorAll('.d-due, .d-hard-due');
  let allValid = true;

  inputs.forEach(input => {
    if (!validateDueDateInput(input)) {
      allValid = false;
    }
  });

  return allValid;
}

// Calendar utility functions
function getDaysInMonth(year, month) {
  return new Date(year, month + 1, 0).getDate();
}

function getFirstDayOfMonth(year, month) {
  return new Date(year, month, 1).getDay();
}

function isSameDay(date1, date2) {
  return date1.getFullYear() === date2.getFullYear() &&
    date1.getMonth() === date2.getMonth() &&
    date1.getDate() === date2.getDate();
}

function createCalendarGrid(year, month, onDateSelect) {
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const daysInMonth = getDaysInMonth(year, month);
  const firstDay = getFirstDayOfMonth(year, month);
  const prevMonth = month === 0 ? 11 : month - 1;
  const prevYear = month === 0 ? year - 1 : year;
  const daysInPrevMonth = getDaysInMonth(prevYear, prevMonth);

  const grid = el('div', { className: 'calendar-grid' });

  // Previous month days
  for (let i = firstDay - 1; i >= 0; i--) {
    const day = daysInPrevMonth - i;
    const btn = el('button', {
      className: 'calendar-day other-month',
      textContent: day,
      type: 'button'
    });
    btn.onclick = () => {
      const date = new Date(prevYear, prevMonth, day);
      onDateSelect(date);
    };
    grid.appendChild(btn);
  }

  // Current month days
  for (let day = 1; day <= daysInMonth; day++) {
    const date = new Date(year, month, day);
    const isToday = isSameDay(date, today);
    const classes = ['calendar-day'];
    if (isToday) classes.push('today');

    const btn = el('button', {
      className: classes.join(' '),
      textContent: day,
      type: 'button'
    });
    btn.onclick = () => onDateSelect(date);
    grid.appendChild(btn);
  }

  // Next month days to fill grid
  const totalCells = grid.children.length;
  const remainingCells = totalCells % 7 === 0 ? 0 : 7 - (totalCells % 7);
  const nextMonth = month === 11 ? 0 : month + 1;
  const nextYear = month === 11 ? year + 1 : year;

  for (let day = 1; day <= remainingCells; day++) {
    const btn = el('button', {
      className: 'calendar-day other-month',
      textContent: day,
      type: 'button'
    });
    btn.onclick = () => {
      const date = new Date(nextYear, nextMonth, day);
      onDateSelect(date);
    };
    grid.appendChild(btn);
  }

  return grid;
}

// Inline calendar picker for input fields
function positionInlineCalendarPopup(anchorElement, calendarContainer, anchorParent) {
  const gap = 6;
  const rect = anchorElement.getBoundingClientRect();
  const isBodyParent = anchorParent === document.body;
  const scrollTop = isBodyParent
    ? (window.scrollY || document.documentElement.scrollTop || 0)
    : anchorParent.scrollTop;
  const scrollLeft = isBodyParent
    ? (window.scrollX || document.documentElement.scrollLeft || 0)
    : anchorParent.scrollLeft;
  const viewHeight = isBodyParent ? window.innerHeight : anchorParent.clientHeight;
  const viewWidth = isBodyParent ? window.innerWidth : anchorParent.clientWidth;

  calendarContainer.style.position = "absolute";
  calendarContainer.style.zIndex = "999999";
  calendarContainer.style.top = "0px";
  calendarContainer.style.left = "0px";
  calendarContainer.style.visibility = "hidden";

  const popupHeight = calendarContainer.offsetHeight;
  const popupWidth = calendarContainer.offsetWidth;
  let anchorTop;
  let anchorBottom;
  let anchorLeft;
  let viewTop;
  let viewBottom;
  let viewLeft;
  let viewRight;

  if (isBodyParent) {
    // Body coordinates are page-based; using parentRect here would double-count scroll.
    anchorTop = rect.top + scrollTop;
    anchorBottom = rect.bottom + scrollTop;
    anchorLeft = rect.left + scrollLeft;
    viewTop = scrollTop;
    viewBottom = scrollTop + viewHeight;
    viewLeft = scrollLeft;
    viewRight = scrollLeft + viewWidth;
  } else {
    const parentRect = anchorParent.getBoundingClientRect();
    anchorTop = rect.top - parentRect.top + scrollTop;
    anchorBottom = rect.bottom - parentRect.top + scrollTop;
    anchorLeft = rect.left - parentRect.left + scrollLeft;
    viewTop = scrollTop;
    viewBottom = scrollTop + viewHeight;
    viewLeft = scrollLeft;
    viewRight = scrollLeft + viewWidth;
  }

  const availableAbove = anchorTop - viewTop;
  const availableBelow = viewBottom - anchorBottom;

  let top;
  if (availableBelow >= popupHeight + gap) {
    top = anchorBottom + gap;
  } else if (availableAbove >= popupHeight + gap) {
    top = anchorTop - popupHeight - gap;
  } else if (availableBelow >= availableAbove) {
    top = Math.max(viewTop + gap, viewBottom - popupHeight - gap);
  } else {
    top = Math.max(viewTop + gap, anchorTop - popupHeight - gap);
  }

  let left = anchorLeft;
  const maxLeft = Math.max(viewLeft + gap, viewRight - popupWidth - gap);
  left = Math.min(Math.max(left, viewLeft + gap), maxLeft);

  calendarContainer.style.top = `${top}px`;
  calendarContainer.style.left = `${left}px`;
  calendarContainer.style.visibility = "";
}

function showCalendarForInput(inputElement, onSelectCallback) {
  // Remove any existing calendar
  const existingCalendar = document.getElementById('inlineCalendarPicker');
  if (existingCalendar) existingCalendar.remove();

  // Always open to the current month/day.
  const openDate = new Date();

  // Create calendar container
  const calendarContainer = el('div', {
    className: 'inline-calendar-picker',
    id: 'inlineCalendarPicker'
  });

  // Render calendar
  const calendar = renderInlineCalendar(
    openDate.getFullYear(),
    openDate.getMonth(),
    (selectedDate) => {
      // On date selection
      inputElement.value = formatDueDateShort(selectedDate);
      // Trigger validation
      validateDueDateInput(inputElement);
      // Callback
      if (onSelectCallback) onSelectCallback(selectedDate);
      // Remove calendar
      calendarContainer.remove();
    },
    () => {
      // On cancel
      calendarContainer.remove();
    }
  );

  calendarContainer.appendChild(calendar);

  // Append inside the closest dialog (top layer) so it's not hidden behind it.
  // Fall back to document.body if not inside a dialog.
  const parentDialog = inputElement.closest('dialog');
  const anchorParent = parentDialog || document.body;
  anchorParent.appendChild(calendarContainer);
  positionInlineCalendarPopup(inputElement, calendarContainer, anchorParent);

  // Close on outside click
  setTimeout(() => {
    const closeOnOutsideClick = (e) => {
      if (!calendarContainer.contains(e.target) && e.target !== inputElement) {
        calendarContainer.remove();
        document.removeEventListener('click', closeOnOutsideClick);
      }
    };
    document.addEventListener('click', closeOnOutsideClick);
  }, 100);
}

function showCalendarForDeliverableBadge(
  anchorElement,
  deliverable,
  project,
  field = "due"
) {
  if (!anchorElement || !deliverable) return;

  // Remove any existing calendar
  const existingCalendar = document.getElementById('inlineCalendarPicker');
  if (existingCalendar) existingCalendar.remove();

  // Always open to the current month/day.
  const openDate = new Date();

  // Create calendar container
  const calendarContainer = el('div', {
    className: 'inline-calendar-picker',
    id: 'inlineCalendarPicker'
  });

  // Render calendar
  const calendar = renderInlineCalendar(
    openDate.getFullYear(),
    openDate.getMonth(),
    async (selectedDate) => {
      deliverable[field] = formatDueDateShort(selectedDate);
      await save();
      render();
      calendarContainer.remove();
    },
    () => {
      calendarContainer.remove();
    }
  );

  calendarContainer.appendChild(calendar);

  // Append inside the closest dialog (top layer) so it's not hidden behind it.
  // Fall back to document.body if not inside a dialog.
  const parentDialog = anchorElement.closest('dialog');
  const anchorParent = parentDialog || document.body;
  anchorParent.appendChild(calendarContainer);
  positionInlineCalendarPopup(anchorElement, calendarContainer, anchorParent);

  // Close on outside click
  setTimeout(() => {
    const closeOnOutsideClick = (e) => {
      if (!calendarContainer.contains(e.target) && e.target !== anchorElement) {
        calendarContainer.remove();
        document.removeEventListener('click', closeOnOutsideClick);
      }
    };
    document.addEventListener('click', closeOnOutsideClick);
  }, 100);
}

function renderInlineCalendar(year, month, onDateSelect, onCancel) {
  const monthNames = ['January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'];

  const container = el('div', { className: 'inline-calendar' });

  // Header with navigation
  const header = el('div', { className: 'calendar-header' });

  const prevBtn = el('button', {
    className: 'calendar-nav-btn',
    textContent: '◀',
    type: 'button'
  });

  const monthYearLabel = el('div', {
    className: 'calendar-month-year',
    textContent: `${monthNames[month]} ${year}`
  });

  const nextBtn = el('button', {
    className: 'calendar-nav-btn',
    textContent: '▶',
    type: 'button'
  });

  header.appendChild(prevBtn);
  header.appendChild(monthYearLabel);
  header.appendChild(nextBtn);
  container.appendChild(header);

  // Weekday labels
  const weekdays = el('div', { className: 'calendar-weekdays' });
  ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].forEach(day => {
    weekdays.appendChild(el('div', { textContent: day }));
  });
  container.appendChild(weekdays);

  // Calendar grid
  const gridContainer = el('div');
  gridContainer.appendChild(createCalendarGrid(year, month, onDateSelect));
  container.appendChild(gridContainer);

  // Footer with cancel button
  const footer = el('div', { className: 'calendar-footer' });
  const cancelBtn = el('button', {
    className: 'btn ghost',
    textContent: 'Cancel',
    type: 'button'
  });
  cancelBtn.onclick = onCancel;
  footer.appendChild(cancelBtn);
  container.appendChild(footer);

  // Navigation: only swap the grid and update the label to keep DOM stable
  function navigateMonth(newYear, newMonth) {
    monthYearLabel.textContent = `${monthNames[newMonth]} ${newYear}`;
    gridContainer.innerHTML = '';
    gridContainer.appendChild(createCalendarGrid(newYear, newMonth, onDateSelect));

    // Rebind arrows for the new month
    prevBtn.onclick = () => {
      const m = newMonth === 0 ? 11 : newMonth - 1;
      const y = newMonth === 0 ? newYear - 1 : newYear;
      navigateMonth(y, m);
    };
    nextBtn.onclick = () => {
      const m = newMonth === 11 ? 0 : newMonth + 1;
      const y = newMonth === 11 ? newYear + 1 : newYear;
      navigateMonth(y, m);
    };
  }

  prevBtn.onclick = () => {
    const m = month === 0 ? 11 : month - 1;
    const y = month === 0 ? year - 1 : year;
    navigateMonth(y, m);
  };

  nextBtn.onclick = () => {
    const m = month === 11 ? 0 : month + 1;
    const y = month === 11 ? year + 1 : year;
    navigateMonth(y, m);
  };

  return container;
}

// Extract account name from file path
// Handles: P:\Account\..., M:\Account\..., or \\acies.lan\cachedrive\projects2?\Account\...
function extractAccountFromPath(path) {
  if (!path) return null;

  // Normalize path separators to forward slashes
  const normalized = path.replace(/\\/g, '/');

  // Try P: or M: drive pattern first
  let match = normalized.match(/^([PM]):\/?([^\/]+)/i);
  if (match) return match[2];

  // Try network cached drive pattern: \\acies.lan\cachedrive\projects2?\Account\...
  match = normalized.match(/^\/\/[^\/]+\/cachedrive\/projects2?\/([^\/]+)/i);
  if (match) return match[1];

  return null;
}

function basename(path) {
  try {
    if (!path) return "";
    const norm = path.replace(/\\/g, "/");
    const idx = norm.lastIndexOf("/");
    return idx >= 0 ? norm.slice(idx + 1) : norm;
  } catch {
    return path;
  }
}

function toFileURL(raw) {
  if (!raw) return "";
  let s = raw.trim();
  if (/^https?:\/\//i.test(s)) return s;
  if (/^\\\\/.test(s))
    return "file:" + s.replace(/^\\\\/, "/////").replace(/\\/g, "/");
  if (/^[A-Za-z]:\\/.test(s)) return "file:///" + s.replace(/\\/g, "/");
  return s;
}

function normalizeLink(input) {
  const raw = (input || "").trim();
  const url = toFileURL(raw);
  const label = basename(raw) || raw || "link";
  return { label, url, raw };
}

function fileUrlToLocalPath(url) {
  try {
    const parsed = new URL(url);
    if (parsed.protocol !== "file:") return "";
    let path = decodeURIComponent(parsed.pathname || "");
    if (/^\/[A-Za-z]:/.test(path)) path = path.slice(1);
    if (parsed.host) {
      const uncPath = path.replace(/\//g, "\\");
      return `\\\\${parsed.host}${uncPath}`;
    }
    return path.replace(/\//g, "\\");
  } catch {
    return "";
  }
}

function isEmailFilePath(value) {
  const s = String(value || "").trim();
  return /\.(msg|eml)$/i.test(s);
}

function inferEmailRefSource(raw = "", url = "") {
  const joined = `${raw} ${url}`.toLowerCase();
  if (joined.includes(".msg") || joined.includes(".eml") || /^file:\/\//i.test(url)) {
    return "file";
  }
  if (
    joined.includes("outlook.office.com/") ||
    joined.includes("outlook.office365.com/") ||
    joined.includes("outlook.live.com/")
  ) {
    return "outlook-url";
  }
  if (/^outlook:/i.test(raw) || /^outlook:/i.test(url)) return "outlook-url";
  if (/^mailto:/i.test(raw) || /^mailto:/i.test(url)) return "mailto";
  return "url";
}

function normalizeEmailRef(value) {
  if (!value) return null;
  if (typeof value === "string") {
    const link = normalizeLink(value);
    if (!link.raw) return null;
    return {
      raw: link.raw,
      url: link.url || link.raw,
      label: link.label || "Email",
      source: inferEmailRefSource(link.raw, link.url),
      savedAt: "",
    };
  }
  if (typeof value !== "object") return null;
  const raw = String(value.raw || value.url || "").trim();
  if (!raw) return null;
  const link = normalizeLink(raw);
  const url = String(value.url || link.url || raw).trim();
  const label = String(value.label || link.label || "Email").trim() || "Email";
  const source = String(value.source || inferEmailRefSource(raw, url)).trim();
  const savedAt = String(value.savedAt || value.saved_at || "").trim();
  const messageId = String(
    value.messageId || value.message_id || value.graphMessageId || ""
  ).trim();
  const internetMessageId = String(
    value.internetMessageId || value.internet_message_id || ""
  ).trim();
  return { raw, url, label, source, savedAt, messageId, internetMessageId };
}

function normalizeEmailRefKey(value) {
  const ref = normalizeEmailRef(value);
  if (!ref) return "";
  const messageId = String(ref.messageId || "").trim().toLowerCase();
  const internetMessageId = String(ref.internetMessageId || "")
    .trim()
    .toLowerCase();
  if (messageId || internetMessageId) {
    return [`msg:${messageId}`, `internet:${internetMessageId}`].join("|");
  }
  return [
    String(ref.raw || "").toLowerCase(),
    String(ref.url || "").toLowerCase(),
    String(ref.source || "").toLowerCase(),
  ].join("|");
}

function sameEmailRef(a, b) {
  const left = normalizeEmailRef(a);
  const right = normalizeEmailRef(b);
  if (!left && !right) return true;
  if (!left || !right) return false;
  return normalizeEmailRefKey(left) === normalizeEmailRefKey(right);
}

function normalizeEmailRefs(value, fallbackSingle = null) {
  const candidates = [];
  if (Array.isArray(value)) {
    candidates.push(...value);
  } else if (value != null) {
    candidates.push(value);
  }
  if (fallbackSingle != null) candidates.push(fallbackSingle);

  const seen = new Set();
  const out = [];
  for (const candidate of candidates) {
    const normalized = normalizeEmailRef(candidate);
    if (!normalized) continue;
    const key = normalizeEmailRefKey(normalized);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push(normalized);
    if (out.length >= MAX_DELIVERABLE_EMAIL_REFS) break;
  }
  return out;
}

function sameEmailRefList(a, b) {
  const left = normalizeEmailRefs(a);
  const right = normalizeEmailRefs(b);
  if (left.length !== right.length) return false;
  for (let i = 0; i < left.length; i++) {
    if (!sameEmailRef(left[i], right[i])) return false;
  }
  return true;
}

function isWebAttachmentTarget(value) {
  return /^https?:\/\//i.test(String(value || "").trim());
}

function normalizeAttachmentTarget(target, type = "path") {
  let raw = String(target || "").trim();
  if (!raw) return "";
  if (type === "url") return raw;
  const localPathFromUrl = fileUrlToLocalPath(raw);
  if (localPathFromUrl) {
    raw = localPathFromUrl;
  }
  if (/^[A-Za-z]:[\\/]/.test(raw) || /^\\\\/.test(raw)) {
    return normalizeWindowsPath(raw);
  }
  return raw;
}

function inferAttachmentType(target, preferredType = "") {
  const normalizedPreferred = String(preferredType || "").trim().toLowerCase();
  if (["file", "folder", "path", "url", "email"].includes(normalizedPreferred)) {
    return normalizedPreferred;
  }
  return isWebAttachmentTarget(target) ? "url" : "path";
}

function getAttachmentTypeLabel(type = "path") {
  if (type === "file") return "File";
  if (type === "folder") return "Folder";
  if (type === "url") return "URL";
  if (type === "email") return "Email";
  return "Path";
}

function getAttachmentDescriptionFallback({
  type = "path",
  target = "",
  emailRef = null,
} = {}) {
  if (type === "email") {
    const normalizedEmailRef = normalizeEmailRef(emailRef);
    return (
      String(normalizedEmailRef?.label || "").trim() ||
      basename(getEmailRefLocalPath(normalizedEmailRef)) ||
      basename(normalizedEmailRef?.raw || normalizedEmailRef?.url || "") ||
      "Email"
    );
  }
  if (type === "url") {
    try {
      const parsed = new URL(String(target || "").trim());
      return parsed.hostname || parsed.href || "Link";
    } catch {
      return String(target || "").trim() || "Link";
    }
  }
  return basename(String(target || "").trim()) || String(target || "").trim() || "Attachment";
}

function getAttachmentEntryKey(attachment) {
  const normalized = normalizeAttachmentEntry(attachment);
  if (!normalized) return "";
  if (normalized.type === "email") {
    return `email:${normalizeEmailRefKey(normalized.emailRef)}`;
  }
  return `${normalized.type}:${String(normalized.target || "").trim().toLowerCase()}`;
}

function normalizeAttachmentEntry(entry) {
  if (!entry) return null;
  const source =
    typeof entry === "string" ? { target: entry, description: "" } : entry;
  const normalizedEmailRef = normalizeEmailRef(source.emailRef || source.ref || null);
  const type = inferAttachmentType(
    source.target || source.raw || source.url || "",
    normalizedEmailRef ? "email" : source.type
  );

  if (type === "email") {
    if (!normalizedEmailRef) return null;
    return {
      id: String(source.id || createId("att")).trim() || createId("att"),
      type: "email",
      description:
        String(source.description || source.label || "").trim() ||
        getAttachmentDescriptionFallback({
          type: "email",
          emailRef: normalizedEmailRef,
        }),
      emailRef: normalizedEmailRef,
    };
  }

  const target = normalizeAttachmentTarget(
    source.target || source.raw || source.url || "",
    type
  );
  if (!target) return null;

  return {
    id: String(source.id || createId("att")).trim() || createId("att"),
    type,
    description:
      String(source.description || source.label || "").trim() ||
      getAttachmentDescriptionFallback({ type, target }),
    target,
  };
}

function normalizeAttachments(
  attachments,
  { legacyLinks = [], legacyEmailRefs = [], legacyEmailRef = null } = {}
) {
  const hasExplicitAttachments = Array.isArray(attachments);
  const normalized = [];
  const seen = new Set();

  const appendAttachment = (candidate) => {
    const next = normalizeAttachmentEntry(candidate);
    if (!next) return;
    const key = getAttachmentEntryKey(next);
    if (!key || seen.has(key)) return;
    seen.add(key);
    normalized.push(next);
  };

  if (hasExplicitAttachments) {
    attachments.forEach(appendAttachment);
    return normalized;
  }

  normalizeDeliverableLinks(legacyLinks).forEach((link) => {
    appendAttachment({
      type: isWebAttachmentTarget(link.raw || link.url || "") ? "url" : "path",
      target: link.raw || link.url || "",
      description: String(link.label || "").trim(),
    });
  });

  normalizeEmailRefs(legacyEmailRefs, legacyEmailRef).forEach((emailRef) => {
    appendAttachment({
      type: "email",
      description: String(emailRef?.label || "").trim(),
      emailRef,
    });
  });

  return normalized;
}

function buildLegacyLinksFromAttachments(attachments = []) {
  return normalizeAttachments(attachments)
    .filter((attachment) => attachment.type !== "email")
    .map((attachment) =>
      normalizeDeliverableLinkEntry({
        label: String(attachment.description || "").trim(),
        raw: attachment.target || "",
      })
    )
    .filter(Boolean);
}

function buildLegacyEmailRefsFromAttachments(attachments = []) {
  return normalizeAttachments(attachments)
    .filter((attachment) => attachment.type === "email")
    .map((attachment) => normalizeEmailRef(attachment.emailRef))
    .filter(Boolean);
}

function syncAttachmentOwnerCompatFields(
  owner,
  {
    includeEmailRefs = true,
    legacyLinks = owner?.links || [],
    legacyEmailRefs = owner?.emailRefs || [],
    legacyEmailRef = owner?.emailRef || null,
  } = {}
) {
  if (!owner || typeof owner !== "object") return [];
  const attachments = normalizeAttachments(owner.attachments, {
    legacyLinks,
    legacyEmailRefs,
    legacyEmailRef,
  });
  owner.attachments = attachments;
  owner.links = buildLegacyLinksFromAttachments(attachments);
  if (includeEmailRefs) {
    const emailRefs = buildLegacyEmailRefsFromAttachments(attachments);
    owner.emailRefs = emailRefs;
    owner.emailRef = emailRefs[0] || null;
  }
  return attachments;
}

function syncProjectAttachmentFields(project) {
  return syncAttachmentOwnerCompatFields(project, {
    includeEmailRefs: false,
    legacyLinks: project?.links || [],
  });
}

function syncDeliverableAttachmentFields(deliverable) {
  return syncAttachmentOwnerCompatFields(deliverable, {
    includeEmailRefs: true,
    legacyLinks: normalizeDeliverableLinks(
      deliverable?.links,
      deliverable?.linkPath || ""
    ),
    legacyEmailRefs: deliverable?.emailRefs,
    legacyEmailRef: deliverable?.emailRef,
  });
}

function syncAttachmentOwnerEmailRefs(owner) {
  if (!owner || typeof owner !== "object") return [];
  syncAttachmentOwnerCompatFields(owner, {
    includeEmailRefs: true,
    legacyLinks: owner?.links || [],
    legacyEmailRefs: owner?.emailRefs,
    legacyEmailRef: owner?.emailRef,
  });
  return owner.emailRefs || [];
}





function getAttachmentOwnerKindLabel(kind = "deliverable") {
  if (kind === "project") return "Project";
  if (kind === "task") return "Task";
  if (kind === "note") return "Note";
  return "Deliverable";
}

function getAttachmentOwnerLabel(descriptor = {}) {
  const { kind = "deliverable", owner = null } = descriptor;
  const deliverable =
    descriptor.deliverable || (kind === "deliverable" ? owner : null);
  const ownerText = String(owner?.text || "").trim();
  const projectName = String(descriptor.project?.name || owner?.name || "").trim();
  const deliverableName = String(deliverable?.name || "").trim();
  if (kind === "project") return projectName || getAttachmentOwnerKindLabel(kind);
  return ownerText || deliverableName || projectName || getAttachmentOwnerKindLabel(kind);
}

function getEmailRefLocalPath(emailRef) {
  const ref = normalizeEmailRef(emailRef);
  if (!ref) return "";
  const raw = String(ref.raw || "").trim();
  if (/^[A-Za-z]:[\\/]/.test(raw) || /^\\\\/.test(raw)) return raw;
  if (/^file:\/\//i.test(raw)) return fileUrlToLocalPath(raw);
  const url = String(ref.url || "").trim();
  if (/^file:\/\//i.test(url)) return fileUrlToLocalPath(url);
  return "";
}

function isManagedSavedEmailRef(emailRef) {
  const ref = normalizeEmailRef(emailRef);
  return !!ref && String(ref.source || "").toLowerCase() === "saved-file";
}

async function deleteManagedSavedEmailRef(emailRef) {
  const path = getEmailRefLocalPath(emailRef);
  if (!path || !isManagedSavedEmailRef(emailRef)) return;
  if (!window.pywebview?.api?.delete_saved_email) return;
  try {
    await window.pywebview.api.delete_saved_email(path);
  } catch (e) {
    console.warn("Failed to delete managed saved email:", e);
  }
}

async function openDeliverableEmailRef(emailRef) {
  const ref = normalizeEmailRef(emailRef);
  if (!ref) return false;
  const source = String(ref.source || "").trim().toLowerCase();
  if (
    source === "outlook-desktop" &&
    ref.messageId &&
    window.pywebview?.api?.open_outlook_desktop_message
  ) {
    try {
      const res = await window.pywebview.api.open_outlook_desktop_message(
        ref.messageId
      );
      if (res && res.status === "error") {
        throw new Error(res.message || "Unable to open Desktop Outlook email.");
      }
      return true;
    } catch (e) {
      toast("Could not open Desktop Outlook email.");
      return false;
    }
  }
  if (source === "outlook-desktop" && ref.messageId) {
    toast("Desktop Outlook message opening is unavailable in this environment.");
    return false;
  }
  const localPath = getEmailRefLocalPath(ref);
  if (localPath && window.pywebview?.api?.open_path) {
    try {
      const res = await window.pywebview.api.open_path(localPath);
      if (res && res.status === "error") {
        throw new Error(res.message || "Unable to open email file.");
      }
      return true;
    } catch (e) {
      toast("Could not open linked email file.");
      return false;
    }
  }
  openExternalUrl(ref.url || ref.raw);
  return true;
}

function buildEmailRefFromRawInput(rawInput, source = "url") {
  const raw = String(rawInput || "").trim();
  if (!raw) return null;
  const isUrlLike =
    /^https?:\/\//i.test(raw) ||
    /^outlook:/i.test(raw) ||
    /^mailto:/i.test(raw) ||
    /^file:\/\//i.test(raw);
  const isPathLike = /^[A-Za-z]:[\\/]/.test(raw) || /^\\\\/.test(raw);
  if (!isUrlLike && !isPathLike && !isEmailFilePath(raw)) {
    return null;
  }
  const normalized = normalizeEmailRef({
    raw,
    url: toFileURL(raw),
    label: basename(raw) || "Email",
    source,
    savedAt: new Date().toISOString(),
  });
  if (!normalized) return null;
  if (source === "saved-file") normalized.source = "saved-file";
  return normalized;
}

function extractEmailUrlFromUriList(uriList) {
  const lines = String(uriList || "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith("#"));
  return lines[0] || "";
}

function extractEmailUrlFromHtml(html) {
  if (!html) return "";
  try {
    const doc = new DOMParser().parseFromString(html, "text/html");
    const anchor = doc.querySelector("a[href]");
    return anchor?.getAttribute("href")?.trim() || "";
  } catch {
    return "";
  }
}

function extractEmailUrlFromText(text) {
  const s = String(text || "").trim();
  if (!s) return "";
  const match = s.match(
    /(https?:\/\/[^\s<>"']+|outlook:[^\s<>"']+|mailto:[^\s<>"']+|file:\/\/\/[^\s<>"']+)/i
  );
  if (match) return match[1].trim();
  return "";
}

function getTransferDataText(dt, type) {
  try {
    return dt?.getData?.(type) || "";
  } catch {
    return "";
  }
}

function extractEmailUrlFromDropData(dt) {
  const uriList =
    getTransferDataText(dt, "text/uri-list") ||
    getTransferDataText(dt, "URL") ||
    getTransferDataText(dt, "UniformResourceLocator") ||
    getTransferDataText(dt, "UniformResourceLocatorW");
  const fromUriList = extractEmailUrlFromUriList(uriList);
  if (fromUriList) return fromUriList;

  const html = getTransferDataText(dt, "text/html");
  const fromHtml = extractEmailUrlFromHtml(html);
  if (fromHtml) return fromHtml;

  const text =
    getTransferDataText(dt, "text/plain") ||
    getTransferDataText(dt, "Text") ||
    getTransferDataText(dt, "text/x-moz-url");
  return extractEmailUrlFromText(text);
}

function isSupportedEmailFile(file) {
  if (!file) return false;
  const name = String(file.name || "").toLowerCase();
  return name.endsWith(".msg") || name.endsWith(".eml");
}

function buildAttachmentOwnerEmailContext(descriptor = {}, scope = "projects-tab") {
  const { kind = "deliverable", owner = null, project = null } = descriptor;
  const deliverable =
    descriptor.deliverable || (kind === "deliverable" ? owner : null);
  const context = {
    projectId: String(project?.id || val("f_id") || "").trim(),
    projectName: String(project?.name || val("f_name") || "").trim(),
    deliverableId: String(deliverable?.id || "").trim(),
    deliverableName: String(deliverable?.name || "").trim(),
    scope,
    attachmentOwnerKind: kind,
    attachmentOwnerLabel: getAttachmentOwnerLabel({
      kind,
      owner,
      deliverable,
    }),
  };
  const ownerText = String(owner?.text || "").trim();
  if (ownerText) {
    context.attachmentOwnerText = ownerText;
  }
  if (
    kind !== "deliverable" &&
    Number.isInteger(descriptor.index) &&
    descriptor.index >= 0
  ) {
    context.attachmentOwnerIndex = descriptor.index;
  }
  return context;
}



async function saveDroppedEmailFile(file, context = {}) {
  if (!isSupportedEmailFile(file)) {
    throw new Error("Only .msg or .eml files are supported.");
  }
  if (!window.pywebview?.api?.save_dropped_email) {
    throw new Error("Email file saving API is unavailable.");
  }
  const upload = {
    name: file.name || "email.msg",
    dataUrl: await readFileAsDataUrl(file),
  };
  const response = await window.pywebview.api.save_dropped_email(upload, context);
  if (!response || response.status !== "success") {
    throw new Error(response?.message || "Failed to save dropped email.");
  }
  const normalized = normalizeEmailRef(response.emailRef);
  if (!normalized) throw new Error("Invalid email reference returned by backend.");
  normalized.source = "saved-file";
  return normalized;
}

// Outlook publishes a dragged message as a *virtual* file (CF_FILEGROUPDESCRIPTORW +
// CF_FILECONTENTS). Those never show up in dataTransfer.files, but Chromium does expose
// them through items[].webkitGetAsEntry(). Both reads have to happen before the first
// await -- the DataTransfer is dead once the drop handler returns.
function captureDropFileEntries(dt) {
  const entries = [];
  const items = Array.from(dt?.items || []);
  for (const item of items) {
    if (item?.kind !== "file") continue;
    let entry = null;
    try {
      entry = item.webkitGetAsEntry?.();
    } catch {
      entry = null;
    }
    if (entry?.isFile) entries.push(entry);
  }
  return entries;
}

const OUTLOOK_DROP_TYPE_PREFIXES = ["filegroupdescriptor", "filecontents", "renprivate", "application/x-moz-file-promise"];

function looksLikeOutlookDrop(types) {
  return Array.from(types || [])
    .map((type) => String(type || "").toLowerCase())
    .some((type) => OUTLOOK_DROP_TYPE_PREFIXES.some((prefix) => type.startsWith(prefix)));
}

function captureEmailDropSources(dt) {
  if (!dt) return null;
  return {
    files: Array.from(dt.files || []),
    entries: captureDropFileEntries(dt),
    urlCandidate: extractEmailUrlFromDropData(dt),
    types: Array.from(dt.types || []),
  };
}

function readEntryAsFile(entry) {
  return new Promise((resolve) => {
    try {
      entry.file(resolve, () => resolve(null));
    } catch {
      resolve(null);
    }
  });
}

async function resolveEmailRefFromCapturedDrop(captured, context = {}) {
  if (!captured) return { emailRef: null, reason: "no-data-transfer" };

  const emailFile = captured.files.find(isSupportedEmailFile);
  if (emailFile) {
    const emailRef = await saveDroppedEmailFile(emailFile, context);
    return { emailRef, source: "file-drop" };
  }

  for (const entry of captured.entries) {
    if (!isSupportedEmailFile({ name: entry.name })) continue;
    const file = await readEntryAsFile(entry);
    if (!file) continue;
    const emailRef = await saveDroppedEmailFile(
      // Virtual files can arrive with an empty name; fall back to the entry's.
      file.name ? file : new File([file], entry.name, { type: file.type }),
      context
    );
    return { emailRef, source: "entry-drop" };
  }

  if (captured.urlCandidate) {
    const emailRef = buildEmailRefFromRawInput(captured.urlCandidate, "url");
    if (emailRef) {
      return { emailRef, source: "url-drop" };
    }
  }

  return {
    emailRef: null,
    reason: "unsupported-drop-data",
    outlookDrop: looksLikeOutlookDrop(captured.types),
  };
}

async function resolveEmailRefFromDrop(event, context = {}) {
  const captured = captureEmailDropSources(event?.dataTransfer);
  return resolveEmailRefFromCapturedDrop(captured, context);
}

async function promptForEmailLinkRef() {
  const raw = prompt("Paste an Outlook/OWA email link.");
  if (raw == null) return null;
  const emailRef = buildEmailRefFromRawInput(raw, "url");
  if (!emailRef) {
    toast("That does not look like a valid email link.");
    return null;
  }
  return emailRef;
}

async function chooseEmailFileRefFromPicker() {
  if (!window.pywebview?.api?.select_files) {
    toast("File picker is unavailable.");
    return null;
  }
  try {
    const res = await window.pywebview.api.select_files({
      allow_multiple: false,
      file_types: [
        "Email Files (*.msg;*.eml)",
        "Outlook Message (*.msg)",
        "Email Message (*.eml)",
      ],
    });
    if (res?.status !== "success" || !res.paths?.length) return null;
    return buildEmailRefFromRawInput(res.paths[0], "file");
  } catch (e) {
    toast("Unable to open file picker.");
    return null;
  }
}

async function requestEmailRefFromFallbackActions() {
  const choosePaste = confirm(
    "No email is linked yet.\nPress OK to paste an email link.\nPress Cancel to choose a .msg/.eml file."
  );
  if (choosePaste) {
    const pasted = await promptForEmailLinkRef();
    if (pasted) return pasted;
    const chooseFileInstead = confirm("No valid link was provided. Choose a .msg/.eml file instead?");
    if (!chooseFileInstead) return null;
  }
  return chooseEmailFileRefFromPicker();
}

function showEmailLinkFallbackGuidance() {
  toast("Could not read Outlook drop data. Use the email icon to paste a link or choose a .msg/.eml file.");
}

async function saveActiveOutlookSelectionRef(context = {}) {
  if (!window.pywebview?.api?.save_active_outlook_selection) return null;
  try {
    const res = await window.pywebview.api.save_active_outlook_selection(context);
    if (res?.status !== "success") {
      if (res?.message) toast(res.message);
      return null;
    }
    return normalizeEmailRef(res.emailRef);
  } catch (e) {
    toast("Could not read the message selected in Outlook.");
    return null;
  }
}

// --- Page editor email attachments -----------------------------------------
// The TipTap bundle has no access to the emailRef helpers above, so the host owns
// resolution and the editor only stores the resulting reference on a chip node.

function buildPageEmailDropContext() {
  const project = pageNav?.project || null;
  return {
    projectId: String(project?.id || "").trim(),
    projectName: String(project?.name || "").trim(),
    // Reused as the second path segment under email-links/, so page emails stay
    // grouped per page rather than colliding in the project root.
    deliverableId: String(pageEditorOwnerKey || "page").trim(),
    scope: "page-editor",
    attachmentOwnerKind: "page",
  };
}

async function resolvePageEmailDropRef(event, context = {}) {
  // Must run before any await: the DataTransfer is invalidated the moment the
  // editor's drop handler returns.
  const captured = captureEmailDropSources(event?.dataTransfer);
  let result = null;
  let dropError = null;
  try {
    result = await resolveEmailRefFromCapturedDrop(captured, context);
  } catch (e) {
    dropError = e;
  }
  if (result?.emailRef) {
    console.info(`[page-email] attached via ${result.source}`);
    return { status: "success", emailRef: result.emailRef };
  }
  const outlookDrop = looksLikeOutlookDrop(captured?.types);
  // Some WebView2 versions expose only an empty Files payload. Ask before
  // using Outlook's selection because that payload cannot identify its source.
  const unreadableFileDrop = captured && !captured.files.length &&
    !captured.entries.length && !captured.urlCandidate &&
    captured.types.some((type) => String(type).toLowerCase() === "files");
  if (outlookDrop || (unreadableFileDrop &&
      window.pywebview?.api?.save_active_outlook_selection &&
      confirm("This drop contains no readable file. Attach the message currently selected in Outlook to these notes?"))) {
    const fromSelection = await saveActiveOutlookSelectionRef(context);
    if (fromSelection) {
      console.info("[page-email] attached via outlook-selection");
      return { status: "success", emailRef: fromSelection };
    }
  }
  return { status: "error", message: dropError?.message ||
    "Could not read the email drop. Type /email in your notes to attach the selected Outlook message, paste a link, or choose a .msg/.eml file." };
}

async function requestPageEmailRef(context = {}) {
  if (window.pywebview?.api?.save_active_outlook_selection) {
    const useSelection = confirm(
      "Attach the message currently selected in Outlook?\nPress Cancel to paste a link or choose a .msg/.eml file instead."
    );
    if (useSelection) {
      const fromSelection = await saveActiveOutlookSelectionRef(context);
      return fromSelection
        ? { status: "success", emailRef: fromSelection }
        : { status: "error", message: "" };
    }
  }
  const chosen = await requestEmailRefFromFallbackActions();
  return chosen ? { status: "success", emailRef: chosen } : { status: "error", message: "" };
}

async function openPageEmailRef(attrs) {
  const ref = normalizeEmailRef(attrs);
  if (!ref) return { status: "error", message: "This email reference is incomplete." };
  const opened = await openDeliverableEmailRef(ref);
  // openDeliverableEmailRef raises its own toast, so no message here.
  return opened ? { status: "success" } : { status: "error", message: "" };
}

async function deletePageEmailRef(attrs) {
  const ref = normalizeEmailRef(attrs);
  // Only managed copies are ours to delete; links and EntryIDs just drop the chip.
  if (ref) await deleteManagedSavedEmailRef(ref);
  return { status: "success" };
}

function openExternalUrl(url) {
  try {
    if (window.pywebview?.api?.open_url) {
      Promise.resolve(window.pywebview.api.open_url(url)).then((result) => {
        if (result?.status === "error" && result.message) toast(result.message);
      });
      return;
    }
  } catch {
    /* fallthrough */
  }
  window.open(url, "_blank", "noreferrer");
}

function convertPath(raw) {
  if (raw.startsWith("\\\\acies.lan\\cachedrive\\projects2\\"))
    return raw.replace("\\\\acies.lan\\cachedrive\\projects2\\", "M:\\");
  if (raw.startsWith("\\\\acies.lan\\cachedrive\\projects\\"))
    return raw.replace("\\\\acies.lan\\cachedrive\\projects\\", "P:\\");
  return raw;
}

function normalizeWindowsPath(rawPath) {
  let normalized = String(rawPath || "")
    .trim()
    .replace(/^['"]+|['"]+$/g, "")
    .replace(/\//g, "\\");
  if (!normalized) return "";
  if (/^[A-Za-z]:\\?$/.test(normalized)) {
    return `${normalized.slice(0, 2)}\\`;
  }
  normalized = normalized.replace(/\\+$/, "");
  return normalized;
}

function getWindowsPathLeaf(rawPath) {
  const normalized = normalizeWindowsPath(rawPath);
  if (!normalized) return "";
  const parts = normalized.split("\\");
  return parts[parts.length - 1] || "";
}

function getWindowsPathParent(rawPath) {
  const normalized = normalizeWindowsPath(rawPath);
  if (!normalized) return "";
  if (/^[A-Za-z]:\\$/.test(normalized)) return "";
  if (/^\\\\[^\\]+\\[^\\]+$/.test(normalized)) return "";
  const idx = normalized.lastIndexOf("\\");
  if (idx <= 0) return "";
  return normalized.slice(0, idx);
}

function findProjectRootPath(rawPath) {
  let current = normalizeWindowsPath(rawPath);
  if (!current) return "";
  while (current) {
    const folderName = getWindowsPathLeaf(current);
    if (PROJECT_ROOT_SEGMENT_REGEX.test(folderName)) {
      return current;
    }
    const parent = getWindowsPathParent(current);
    if (!parent || parent.toLowerCase() === current.toLowerCase()) break;
    current = parent;
  }
  return "";
}

function normalizeProjectPath(rawPath) {
  const normalized = normalizeWindowsPath(rawPath);
  if (!normalized) return "";
  return findProjectRootPath(normalized) || normalized;
}

function parseProjectFromPath(rawPath) {
  const rootPath = findProjectRootPath(rawPath);
  if (!rootPath) return null;
  const match = getWindowsPathLeaf(rootPath).match(PROJECT_ROOT_SEGMENT_REGEX);
  if (!match) return null;
  return {
    id: String(match[1] || "").trim(),
    name: String(match[2] || "").trim(),
  };
}

function getProjectBasePath(rawPath) {
  const normalized = normalizeWindowsPath(rawPath);
  if (!normalized) return "";
  const projectRoot = findProjectRootPath(normalized);
  if (projectRoot) return projectRoot.replace(/\\/g, "/");
  const leaf = getWindowsPathLeaf(normalized);
  const basePath = /\.[A-Za-z0-9]{1,5}$/.test(leaf)
    ? getWindowsPathParent(normalized)
    : normalized;
  return basePath ? basePath.replace(/\\/g, "/") : "";
}

function getProjectBaseKey(rawPath) {
  const base = getProjectBasePath(rawPath);
  return base ? base.toLowerCase() : "";
}

function applyProjectFromPath(path, { force = false } = {}) {
  const parsed = parseProjectFromPath(path);
  if (!parsed) return false;
  const idInput = document.getElementById("f_id");
  const nameInput = document.getElementById("f_name");
  if (!idInput || !nameInput) return false;

  const currentId = idInput.value.trim();
  const currentName = nameInput.value.trim();
  const shouldSetId = force || !currentId;
  const shouldSetName = (force || !currentName) && !!parsed.name;

  if (shouldSetId) idInput.value = parsed.id;
  if (shouldSetName) nameInput.value = parsed.name;
  return shouldSetId || shouldSetName;
}

function normalizeProjectPathInput(pathInput, { forceProjectFields = false } = {}) {
  if (!pathInput) return "";
  const rawValue = String(pathInput.value || "");
  applyProjectFromPath(rawValue, { force: forceProjectFields });
  const normalized = normalizeProjectPath(rawValue);
  pathInput.value = normalized;
  pathInput.title = normalized;
  return normalized;
}

function toast(msg, duration = 2500) {
  const existing = document.querySelector(".toast-notification");
  if (existing) existing.remove();

  const t = el("div", {
    textContent: msg,
    style: `
            position: fixed;
            bottom: 24px;
            left: 50%;
            transform: translateX(-50%);
            background: var(--surface);
            backdrop-filter: blur(12px);
            border: 1px solid var(--accent);
            color: var(--text);
            padding: 0.75rem 1.25rem;
            border-radius: 12px;
            z-index: 9999;
            box-shadow: 0 8px 32px rgba(0,0,0,0.4);
            font-weight: 500;
            display: flex;
            align-items: center;
            gap: 8px;
            animation: slideUp 0.3s ease-out forwards;
        `,
  });

  document.body.append(t);
  setTimeout(() => {
    t.style.opacity = "0";
    t.style.transform = "translateX(-50%) translateY(10px)";
    t.style.transition = "all 0.3s ease";
    setTimeout(() => t.remove(), 300);
  }, duration);
}

function createActivityId(prefix = "activity") {
  const normalizedPrefix = String(prefix || "activity")
    .trim()
    .replace(/[^a-z0-9_-]+/gi, "-")
    .replace(/^-+|-+$/g, "") || "activity";
  if (window.crypto?.randomUUID) {
    return `${normalizedPrefix}_${window.crypto.randomUUID()}`;
  }
  return `${normalizedPrefix}_${Date.now().toString(36)}_${Math.random()
    .toString(36)
    .slice(2, 8)}`;
}

function isTerminalActivityStatus(status) {
  return [
    ACTIVITY_STATUS.SUCCESS,
    ACTIVITY_STATUS.WARNING,
    ACTIVITY_STATUS.ERROR,
    ACTIVITY_STATUS.CANCELLED,
  ].includes(String(status || "").trim().toLowerCase());
}

function isRunningActivityStatus(status) {
  return String(status || "").trim().toLowerCase() === ACTIVITY_STATUS.RUNNING;
}

function isQueuedActivityStatus(status) {
  return String(status || "").trim().toLowerCase() === ACTIVITY_STATUS.QUEUED;
}

function clampActivityProgress(value, fallback = 0) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return Math.max(0, Math.min(100, Number(fallback) || 0));
  return Math.max(0, Math.min(100, Math.round(numeric)));
}

function normalizeActivityTimestamp(value, fallback = 0) {
  const numeric = Number(value);
  if (Number.isFinite(numeric) && numeric > 0) {
    // Accept seconds as well as the millisecond timestamps used by the client.
    return numeric < 1e12 ? numeric * 1000 : numeric;
  }
  const parsed = Date.parse(String(value || ""));
  return Number.isFinite(parsed) && parsed > 0 ? parsed : Number(fallback) || 0;
}

function normalizeDwgComparePairs(value) {
  const pairs = Array.isArray(value) ? value : value ? [value] : [];
  const seen = new Set();
  return pairs.reduce((normalized, pair) => {
    if (!pair || typeof pair !== "object") return normalized;
    const newPath = String(pair.newPath || pair.new_path || "").trim();
    const oldPath = String(pair.oldPath || pair.old_path || "").trim();
    if (!newPath || !oldPath) return normalized;
    const key = `${normalizeWindowsPath(newPath).toLowerCase()}|${normalizeWindowsPath(
      oldPath
    ).toLowerCase()}`;
    if (seen.has(key)) return normalized;
    seen.add(key);
    const fallbackLabel = getWindowsPathLeaf(newPath).replace(/\.dwg$/i, "");
    normalized.push({
      newPath,
      oldPath,
      label: String(pair.label || fallbackLabel || "Drawing").trim(),
    });
    return normalized;
  }, []);
}

function appendDwgComparePair(pairs, pair) {
  return normalizeDwgComparePairs([...(Array.isArray(pairs) ? pairs : []), pair]);
}

function formatActivityDateTime(timestamp) {
  const normalized = normalizeActivityTimestamp(timestamp);
  if (!normalized) return "Unknown";
  return new Intl.DateTimeFormat(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
    second: "2-digit",
  }).format(new Date(normalized));
}

function formatActivityDuration(startedAt, endedAt = Date.now()) {
  const start = normalizeActivityTimestamp(startedAt);
  const end = normalizeActivityTimestamp(endedAt, Date.now());
  const totalSeconds = Math.max(0, Math.floor((end - start) / 1000));
  const days = Math.floor(totalSeconds / 86400);
  const hours = Math.floor((totalSeconds % 86400) / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  const clock = [hours, minutes, seconds]
    .map((part) => String(part).padStart(2, "0"))
    .join(":");
  return days ? `${days}d ${clock}` : clock;
}

function updateActivityTimingDurations(now = Date.now()) {
  const { list } = getActivityTrayElements();
  if (!list) return;
  list.querySelectorAll("[data-activity-duration-id]").forEach((node) => {
    const activityId = String(node.dataset.activityDurationId || "").trim();
    const activity = getActivityById(activityId);
    if (!activity) return;
    const isTerminal = isTerminalActivityStatus(activity.status);
    const isQueued = isQueuedActivityStatus(activity.status);
    if (isQueued) {
      node.textContent = "Waiting for earlier activities";
      return;
    }
    const endedAt = isTerminal
      ? normalizeActivityTimestamp(activity.endedAt, now)
      : now;
    node.textContent = `${isTerminal ? "Duration" : "Elapsed"}: ${formatActivityDuration(
      activity.startedAt,
      endedAt
    )}`;
  });
}

function syncActivityTimingTimer() {
  const hasRunningActivity = activityTrayState.items.some((item) =>
    isRunningActivityStatus(item?.status)
  );
  if (hasRunningActivity && activityTrayState.timingTimerId == null) {
    activityTrayState.timingTimerId = window.setInterval(
      () => updateActivityTimingDurations(),
      1000
    );
  } else if (!hasRunningActivity && activityTrayState.timingTimerId != null) {
    window.clearInterval(activityTrayState.timingTimerId);
    activityTrayState.timingTimerId = null;
  }
  updateActivityTimingDurations();
}

function getActivityTrayElements() {
  return {
    tray: document.getElementById("activityTray"),
    toggle: document.getElementById("activityTrayToggle"),
    counts: document.getElementById("activityTrayCounts"),
    body: document.getElementById("activityTrayBody"),
    empty: document.getElementById("activityTrayEmpty"),
    list: document.getElementById("activityTrayList"),
    clearAll: document.getElementById("activityTrayClearAll"),
  };
}

function getToolActivityLabel(toolId, fallback = "") {
  const normalizedToolId = String(toolId || "").trim();
  const normalizedFallback = String(fallback || "").trim();
  if (normalizedToolId === "toolWorkflow" && normalizedFallback) {
    return normalizedFallback;
  }
  if (normalizedToolId && typeof getSharedToolLaunchEntry === "function") {
    const entry = getSharedToolLaunchEntry(normalizedToolId);
    if (entry?.label) return entry.label;
  }
  return normalizedFallback || normalizedToolId || "Activity";
}

function findActivityProjectForPath(rawPath) {
  const normalizedPath = normalizeWindowsPath(rawPath).toLowerCase();
  if (!normalizedPath || !Array.isArray(db)) return null;

  const parsedProject = parseProjectFromPath(rawPath);
  const parsedProjectId = String(parsedProject?.id || "").trim().toLowerCase();
  if (parsedProjectId) {
    const idMatch = db.find(
      (project) => String(project?.id || "").trim().toLowerCase() === parsedProjectId
    );
    if (idMatch) return idMatch;
  }

  let bestMatch = null;
  let bestMatchLength = -1;
  db.forEach((project) => {
    [project?.path, project?.localProjectPath].forEach((projectPath) => {
      const normalizedProjectPath = normalizeWindowsPath(projectPath).toLowerCase();
      if (
        !normalizedProjectPath ||
        (normalizedPath !== normalizedProjectPath &&
          !normalizedPath.startsWith(`${normalizedProjectPath}\\`)) ||
        normalizedProjectPath.length <= bestMatchLength
      ) {
        return;
      }
      bestMatch = project;
      bestMatchLength = normalizedProjectPath.length;
    });
  });
  return bestMatch;
}

function getActivityProjectName({
  projectName = "",
  launchContext = null,
  rerunDefaultPath = "",
  openFolderPath = "",
} = {}) {
  const explicitName = String(projectName || launchContext?.projectName || "").trim();
  if (explicitName) return explicitName;

  const projectId = String(launchContext?.projectId || "").trim().toLowerCase();
  if (projectId && Array.isArray(db)) {
    const project = db.find(
      (candidate) => String(candidate?.id || "").trim().toLowerCase() === projectId
    );
    const matchedName = String(
      project?.name || project?.nick || project?.id || ""
    ).trim();
    if (matchedName) return matchedName;
  }

  const candidatePaths = [
    launchContext?.rootProjectPath,
    launchContext?.projectPath,
    ...(Array.isArray(launchContext?.cadFilePaths) ? launchContext.cadFilePaths : []),
    rerunDefaultPath,
    openFolderPath,
  ];
  for (const candidatePath of candidatePaths) {
    const project = findActivityProjectForPath(candidatePath);
    const matchedName = String(
      project?.name || project?.nick || project?.id || ""
    ).trim();
    if (matchedName) return matchedName;

    const parsedProject = parseProjectFromPath(candidatePath);
    const parsedName = String(parsedProject?.name || parsedProject?.id || "").trim();
    if (parsedName) return parsedName;
  }
  return "";
}

function isRerunnableToolId(toolId) {
  const normalizedToolId = String(toolId || "").trim();
  if (!ACTIVITY_RERUN_TOOL_IDS.has(normalizedToolId)) return false;
  if (typeof getSharedToolLaunchEntry !== "function") return true;
  const entry = getSharedToolLaunchEntry(normalizedToolId);
  return entry?.isReady === true;
}

function makeRerunLaunchContext(defaultPath = "", baseContext = null) {
  const normalizedDefaultPath = String(defaultPath || "").trim();
  const context =
    baseContext && typeof baseContext === "object"
      ? deepCloneJson(baseContext, {})
      : {};
  if (!normalizedDefaultPath) {
    return Object.keys(context).length ? context : null;
  }
  return {
    ...context,
    source: "rerun",
    projectPath: normalizedDefaultPath,
    rootProjectPath: normalizedDefaultPath,
    cadFilePaths: [],
  };
}

function getActivityRerunLaunchContext(activity) {
  if (!activity || typeof activity !== "object") return null;
  const defaultPath = String(activity.rerunDefaultPath || "").trim();
  const storedContext = deepCloneJson(activity.rerunLaunchContext, null);
  if (defaultPath) return makeRerunLaunchContext(defaultPath, storedContext);
  return storedContext && typeof storedContext === "object" ? storedContext : null;
}

function canRerunActivity(activity) {
  if (!activity || activity.canRerun === false) return false;
  return isRerunnableToolId(activity.toolId);
}

function canQueueActivity(activity) {
  return canRerunActivity(activity) && Boolean(getActivityRerunLaunchContext(activity));
}

function canCancelActivity(activity) {
  if (!activity || isTerminalActivityStatus(activity.status)) return false;
  if (isQueuedActivityStatus(activity.status)) {
    return activity.id !== activityTrayState.launchingQueuedActivityId;
  }
  return (
    isRunningActivityStatus(activity.status) &&
    ACTIVITY_CANCELLABLE_TOOL_IDS.has(String(activity.toolId || "").trim()) &&
    activity.canCancel !== false
  );
}

function getQueuedActivities() {
  return activityTrayState.items
    .filter((item) => isQueuedActivityStatus(item?.status))
    .sort(
      (left, right) =>
        Number(left?.queueSequence || 0) - Number(right?.queueSequence || 0)
    );
}

function scheduleNextQueuedActivity() {
  window.setTimeout(() => {
    void launchNextQueuedActivity();
  }, 0);
}

async function launchNextQueuedActivity() {
  if (activityTrayState.launchingQueuedActivityId) return false;
  if (activityTrayState.items.some((item) => isRunningActivityStatus(item?.status))) {
    return false;
  }
  const nextActivity = getQueuedActivities()[0];
  if (!nextActivity) return false;

  const toolId = String(nextActivity.toolId || "").trim();
  activityTrayState.launchingQueuedActivityId = nextActivity.id;
  updateActivity(nextActivity.id, {
    status: ACTIVITY_STATUS.QUEUED,
    message: "Starting queued activity...",
    progress: 3,
    cancelRequested: false,
  });

  const didLaunch = launchSharedToolCard(
    toolId,
    getActivityRerunLaunchContext(nextActivity)
  );
  if (!didLaunch) {
    activityTrayState.launchingQueuedActivityId = "";
    completeActivity(nextActivity.id, {
      status: ACTIVITY_STATUS.WARNING,
      message: `${nextActivity.label || "Tool"} is unavailable and was skipped.`,
    });
    return false;
  }
  return true;
}

function enqueueActivityRerun(activityId) {
  const sourceActivity = getActivityById(activityId);
  if (!canQueueActivity(sourceActivity)) {
    toast("This activity cannot be queued.");
    return false;
  }
  const queuedId = createActivityId(sourceActivity.toolId || "queued-tool");
  const queueSequence = activityTrayState.nextQueueSequence++;
  upsertActivity(
    {
      ...sourceActivity,
      id: queuedId,
      status: ACTIVITY_STATUS.QUEUED,
      message: "Queued — waiting for earlier activities.",
      progress: 0,
      queueSequence,
      createdAt: Date.now(),
      startedAt: 0,
      endedAt: 0,
      cancelRequested: false,
      openFolderPath: "",
      combinedPdfPath: "",
      dwgComparePairs: [],
    },
    { autoExpandReason: "update" }
  );
  toast(`${sourceActivity.label || "Tool"} added to the queue.`);
  scheduleNextQueuedActivity();
  return true;
}

function getActivityById(activityId) {
  return activityTrayState.items.find((item) => item.id === activityId) || null;
}

function setToolCardRunning(toolId, isRunning) {
  const card = document.getElementById(String(toolId || "").trim());
  if (!card) return;
  card.classList.toggle("running", Boolean(isRunning));
}

function bindToolActivity(toolId, activityId) {
  const normalizedToolId = String(toolId || "").trim();
  const normalizedActivityId = String(activityId || "").trim();
  if (!normalizedToolId || !normalizedActivityId) return;
  activeToolActivityIds.set(normalizedToolId, normalizedActivityId);
}

function releaseToolActivity(toolId, activityId = "") {
  const normalizedToolId = String(toolId || "").trim();
  if (!normalizedToolId) return;
  const boundId = activeToolActivityIds.get(normalizedToolId);
  if (!boundId) return;
  if (activityId && boundId !== activityId) return;
  activeToolActivityIds.delete(normalizedToolId);
}

function sortActivityItems(items = []) {
  return [...items].sort((left, right) => {
    const rank = (item) => {
      if (isRunningActivityStatus(item?.status)) return 0;
      if (isQueuedActivityStatus(item?.status)) return 1;
      return 2;
    };
    const leftRank = rank(left);
    const rightRank = rank(right);
    if (leftRank !== rightRank) return leftRank - rightRank;
    if (leftRank === 1) {
      return Number(left?.queueSequence || 0) - Number(right?.queueSequence || 0);
    }
    return Number(right?.updatedAt || 0) - Number(left?.updatedAt || 0);
  });
}

function toggleActivityTrayCollapsed(nextCollapsed, { force = false } = {}) {
  const { tray, toggle, body } = getActivityTrayElements();
  if (!tray || !toggle || !body) return;
  const hasItems = activityTrayState.items.length > 0;
  if (!hasItems && !force) return;
  activityTrayState.collapsed = Boolean(nextCollapsed);
  tray.classList.toggle("is-collapsed", activityTrayState.collapsed);
  toggle.setAttribute("aria-expanded", String(!activityTrayState.collapsed));
  body.hidden = activityTrayState.collapsed;
}

function maybeExpandActivityTray(reason = "update") {
  if (!activityTrayState.items.length) return;
  if (reason === "first" && !activityTrayState.hasAutoExpanded) {
    activityTrayState.hasAutoExpanded = true;
    toggleActivityTrayCollapsed(false, { force: true });
    return;
  }
  if (reason === "error") {
    toggleActivityTrayCollapsed(false, { force: true });
  }
}

function renderActivityTray() {
  initActivityTray();
  const { tray, counts, empty, list, clearAll } = getActivityTrayElements();
  if (!tray || !counts || !empty || !list) return;

  const items = sortActivityItems(activityTrayState.items);
  const activeCount = items.filter((item) => isRunningActivityStatus(item.status)).length;
  const queuedCount = items.filter((item) => isQueuedActivityStatus(item.status)).length;
  const completedCount = items.length - activeCount - queuedCount;
  counts.textContent = `${activeCount} active, ${queuedCount} queued, ${completedCount} completed`;

  if (!items.length) {
    tray.hidden = true;
    empty.hidden = false;
    list.replaceChildren();
    if (clearAll) clearAll.hidden = true;
    toggleActivityTrayCollapsed(false, { force: true });
    activityTrayState.hasAutoExpanded = false;
    syncActivityTimingTimer();
    return;
  }

  tray.hidden = false;
  empty.hidden = true;
  if (clearAll) clearAll.hidden = completedCount === 0;
  list.replaceChildren();

  items.forEach((item) => {
    const status = String(item.status || ACTIVITY_STATUS.RUNNING).trim().toLowerCase();
    const workflowTitle = String(item.workflowTitle || "").trim();
    const projectName = String(item.projectName || "").trim();
    const activityTitle =
      String(item.toolId || "").trim() === "toolWorkflow" && workflowTitle
        ? `Workflow: ${workflowTitle}`
        : item.label || "Activity";
    const iconText =
      status === ACTIVITY_STATUS.QUEUED
        ? "#"
        : status === ACTIVITY_STATUS.SUCCESS
        ? "✓"
        : status === ACTIVITY_STATUS.WARNING
          ? "!"
          : [ACTIVITY_STATUS.ERROR, ACTIVITY_STATUS.CANCELLED].includes(status)
            ? "×"
            : "•";

    const card = el("article", {
      className: "activity-card",
      "data-status": status,
    });
    const icon = el("div", {
      className: `activity-card-icon ${status}`,
      textContent: iconText,
      title: status,
    });
    const content = el("div", { className: "activity-card-content" });
    const header = el("div", { className: "activity-card-header" });
    const titleGroup = el("div", { className: "activity-card-title-group" });
    titleGroup.appendChild(
      el("div", {
        className: "activity-card-title",
        textContent: activityTitle,
        title: activityTitle,
      })
    );
    if (projectName) {
      titleGroup.appendChild(
        el("div", {
          className: "activity-card-project",
          textContent: `Project: ${projectName}`,
          title: projectName,
        })
      );
    }
    const queuedPosition = isQueuedActivityStatus(status)
      ? getQueuedActivities().findIndex((queued) => queued.id === item.id) + 1
      : 0;
    header.append(
      titleGroup,
      el("div", {
        className: "activity-card-percent",
        textContent: queuedPosition
          ? `Queued #${queuedPosition}`
          : `${clampActivityProgress(item.progress, 0)}%`,
      })
    );
    const message = el("div", {
      className: "activity-card-message",
      textContent: item.message || "Working...",
    });
    const isTerminal = isTerminalActivityStatus(status);
    const isQueued = isQueuedActivityStatus(status);
    const startedAt = normalizeActivityTimestamp(item.startedAt, item.createdAt);
    const endedAt = isTerminal
      ? normalizeActivityTimestamp(item.endedAt, item.updatedAt)
      : 0;
    const timing = el("div", { className: "activity-card-timing" }, [
      el("span", {
        className: "activity-card-timing-item",
        textContent: `${isQueued ? "Queued" : "Started"}: ${formatActivityDateTime(startedAt)}`,
        title: `${isQueued ? "Queued" : "Started"}: ${formatActivityDateTime(startedAt)}`,
      }),
    ]);
    if (isTerminal) {
      timing.appendChild(
        el("span", {
          className: "activity-card-timing-item",
          textContent: `Ended: ${formatActivityDateTime(endedAt)}`,
          title: `Ended: ${formatActivityDateTime(endedAt)}`,
        })
      );
    }
    timing.appendChild(
      el("span", {
        className: "activity-card-timing-item activity-card-duration",
        textContent: isQueued
          ? "Waiting for earlier activities"
          : `${isTerminal ? "Duration" : "Elapsed"}: ${formatActivityDuration(
              startedAt,
              isTerminal ? endedAt : Date.now()
            )}`,
        "data-activity-duration-id": item.id,
      })
    );
    const progress = el("div", { className: "activity-card-progress" }, [
      el("div", {
        className: "activity-card-progress-bar",
        style: `width:${clampActivityProgress(item.progress, 0)}%`,
      }),
    ]);
    const actions = el("div", { className: "activity-card-actions" });
    if (canCancelActivity(item)) {
      actions.appendChild(
        el("button", {
          className: "activity-card-action cancel",
          type: "button",
          textContent: item.cancelRequested ? "Cancelling..." : isQueued ? "Remove" : "Cancel",
          disabled: Boolean(item.cancelRequested),
          "data-activity-action": "cancel",
          "data-activity-id": item.id,
          onclick: (event) => {
            event.preventDefault();
            event.stopPropagation();
            void handleActivityTrayCancel(item.id);
          },
        })
      );
    }
    if (canQueueActivity(item)) {
      actions.appendChild(
        el("button", {
          className: "activity-card-action queue",
          type: "button",
          textContent: "Queue Again",
          "data-activity-action": "queue",
          "data-activity-id": item.id,
          onclick: (event) => {
            event.preventDefault();
            event.stopPropagation();
            enqueueActivityRerun(item.id);
          },
        })
      );
    }
    if (isTerminal && item.combinedPdfPath) {
      actions.appendChild(
        el("button", {
          className: "activity-card-action",
          type: "button",
          textContent: "Copy Combined PDF",
          "data-activity-action": "copy-combined-pdf",
          "data-activity-id": item.id,
          onclick: (event) => {
            event.preventDefault();
            event.stopPropagation();
            void handleActivityTrayCopyCombinedPdf(item.id);
          },
        })
      );
      actions.appendChild(
        el("button", {
          className: "activity-card-action",
          type: "button",
          textContent: "Open Combined PDF",
          "data-activity-action": "open-combined-pdf",
          "data-activity-id": item.id,
          onclick: (event) => {
            event.preventDefault();
            event.stopPropagation();
            void handleActivityTrayOpenCombinedPdf(item.id);
          },
        })
      );
    }
    if (isTerminal && item.canvasPanelReview) {
      actions.appendChild(
        el("button", {
          className: "activity-card-action",
          type: "button",
          textContent: "Review findings",
          "data-activity-action": "review-canvas-panel",
          "data-activity-id": item.id,
          onclick: (event) => {
            event.preventDefault();
            event.stopPropagation();
            handleActivityTrayReviewCanvasPanel(item.id);
          },
        })
      );
    }
    const dwgComparePairs = normalizeDwgComparePairs(item.dwgComparePairs);
    if (isTerminal && dwgComparePairs.length) {
      dwgComparePairs.forEach((pair, pairIndex) => {
        const pairLabel = String(pair.label || `Drawing ${pairIndex + 1}`).trim();
        actions.appendChild(
          el("button", {
            className: "activity-card-action compare",
            type: "button",
            textContent:
              dwgComparePairs.length === 1
                ? "Compare Old vs New"
                : `Compare ${pairLabel}`,
            title: `Open AutoCAD modelspace comparison for ${pairLabel}`,
            "data-activity-action": "dwg-compare",
            "data-activity-id": item.id,
            "data-dwg-compare-index": String(pairIndex),
            onclick: (event) => {
              event.preventDefault();
              event.stopPropagation();
              void handleActivityTrayDwgCompare(item.id, pairIndex);
            },
          })
        );
      });
    }
    if (isTerminal && item.openFolderPath) {
      actions.appendChild(
        el("button", {
          className: "activity-card-action",
          type: "button",
          textContent: item.openFolderLabel || "Open Folder",
          "data-activity-action": "open",
          "data-activity-id": item.id,
          onclick: (event) => {
            event.preventDefault();
            event.stopPropagation();
            void handleActivityTrayOpenFolder(item.id);
          },
        })
      );
    }
    if (isTerminal && canRerunActivity(item)) {
      actions.appendChild(
        el("button", {
          className: "activity-card-action rerun",
          type: "button",
          textContent: "Rerun",
          "data-activity-action": "rerun",
          "data-activity-id": item.id,
          onclick: (event) => {
            event.preventDefault();
            event.stopPropagation();
            void handleActivityTrayRerun(item.id);
          },
        })
      );
    }
    if (isTerminal) {
      actions.appendChild(
        el("button", {
          className: "activity-card-action accept",
          type: "button",
          textContent: "Accept",
          "data-activity-action": "accept",
          "data-activity-id": item.id,
          onclick: (event) => {
            event.preventDefault();
            event.stopPropagation();
            handleActivityTrayAccept(item.id);
          },
        })
      );
    }

    content.append(header, message, timing, progress);
    if (actions.childNodes.length) {
      content.appendChild(actions);
    }
    card.append(icon, content);
    list.appendChild(card);
  });

  toggleActivityTrayCollapsed(activityTrayState.collapsed, { force: true });
  syncActivityTimingTimer();
}

async function handleActivityTrayOpenFolder(activityId) {
  const activity = getActivityById(activityId);
  if (!activity?.openFolderPath) {
    toast("Unable to open folder.");
    return false;
  }
  if (!window.pywebview?.api?.open_path) {
    toast("Open path is unavailable.");
    return false;
  }
  try {
    const result = await window.pywebview.api.open_path(activity.openFolderPath);
    if (result && String(result.status || "").trim().toLowerCase() !== "success") {
      throw new Error(result.message || "Unable to open folder.");
    }
    return true;
  } catch (error) {
    toast(error?.message || "Unable to open folder.");
    return false;
  }
}

async function handleActivityTrayDwgCompare(activityId, pairIndex = 0) {
  const activity = getActivityById(activityId);
  const normalizedIndex = Number(pairIndex) || 0;
  const pair = normalizeDwgComparePairs(activity?.dwgComparePairs)[normalizedIndex];
  if (!pair) {
    toast("The old and new XREF drawings are unavailable.");
    return false;
  }
  if (!window.pywebview?.api?.launch_dwg_compare) {
    toast("AutoCAD drawing comparison is unavailable.");
    return false;
  }

  const launchKey = `${activityId}:${normalizedIndex}`;
  if (activeDwgCompareLaunches.has(launchKey)) {
    toast("That drawing comparison is already opening.");
    return false;
  }
  activeDwgCompareLaunches.add(launchKey);
  try {
    const result = await window.pywebview.api.launch_dwg_compare(
      pair.newPath,
      pair.oldPath
    );
    if (String(result?.status || "").trim().toLowerCase() !== "success") {
      throw new Error(result?.message || "Unable to open the AutoCAD comparison.");
    }
    toast(result?.message || "Opening the modelspace comparison in AutoCAD.");
    return true;
  } catch (error) {
    toast(error?.message || "Unable to open the AutoCAD comparison.");
    return false;
  } finally {
    activeDwgCompareLaunches.delete(launchKey);
  }
}

function handleActivityTrayReviewCanvasPanel(activityId) {
  if (!canvasPanelScheduleState.pendingResult) {
    toast("Those findings were already reviewed.");
    acceptActivity(activityId);
    return;
  }
  showCanvasPanelScheduleFindings(canvasPanelScheduleState.pendingResult);
  acceptActivity(activityId);
}

async function handleActivityTrayCopyCombinedPdf(activityId) {
  const activity = getActivityById(activityId);
  if (!activity?.combinedPdfPath) {
    toast("Unable to copy combined PDF.");
    return false;
  }
  if (!window.pywebview?.api?.copy_file_to_clipboard) {
    toast("Copy file is unavailable.");
    return false;
  }
  try {
    const result = await window.pywebview.api.copy_file_to_clipboard(
      activity.combinedPdfPath
    );
    if (result && String(result.status || "").trim().toLowerCase() !== "success") {
      throw new Error(result.message || "Unable to copy combined PDF.");
    }
    toast("Combined PDF copied.");
    return true;
  } catch (error) {
    toast(error?.message || "Unable to copy combined PDF.");
    return false;
  }
}

async function handleActivityTrayOpenCombinedPdf(activityId) {
  const activity = getActivityById(activityId);
  if (!activity?.combinedPdfPath) {
    toast("Unable to open combined PDF.");
    return false;
  }
  if (!window.pywebview?.api?.open_path) {
    toast("Open path is unavailable.");
    return false;
  }
  try {
    const result = await window.pywebview.api.open_path(activity.combinedPdfPath);
    if (result && String(result.status || "").trim().toLowerCase() !== "success") {
      throw new Error(result.message || "Unable to open combined PDF.");
    }
    return true;
  } catch (error) {
    toast(error?.message || "Unable to open combined PDF.");
    return false;
  }
}

async function handleActivityTrayCancel(activityId) {
  const activity = getActivityById(activityId);
  if (!canCancelActivity(activity)) {
    toast("This activity cannot be cancelled.");
    return false;
  }
  if (isQueuedActivityStatus(activity.status)) {
    completeActivity(activityId, {
      status: ACTIVITY_STATUS.CANCELLED,
      message: "Removed from queue.",
    });
    return true;
  }
  if (!window.pywebview?.api?.cancel_activity) {
    toast("Cancellation is unavailable.");
    return false;
  }

  updateActivity(activityId, {
    cancelRequested: true,
    message: "Cancelling activity...",
  });
  try {
    const result = await window.pywebview.api.cancel_activity(activityId);
    if (String(result?.status || "").trim().toLowerCase() !== "success") {
      throw new Error(result?.message || "Could not cancel the activity.");
    }
    completeActivity(activityId, {
      status: ACTIVITY_STATUS.CANCELLED,
      message: "Cancelled by user.",
      cancelRequested: false,
    });
    return true;
  } catch (error) {
    updateActivity(activityId, {
      cancelRequested: false,
      message: error?.message || "Could not cancel the activity.",
    });
    toast(error?.message || "Could not cancel the activity.");
    return false;
  }
}

async function handleActivityTrayRerun(activityId) {
  const activity = getActivityById(activityId);
  if (!canRerunActivity(activity)) {
    toast("Unable to rerun this tool.");
    return false;
  }
  const toolId = String(activity.toolId || "").trim();
  const label = getToolActivityLabel(toolId, activity.label || "Tool");
  const card = document.getElementById(toolId);
  if (activeToolActivityIds.has(toolId) || card?.classList.contains("running")) {
    toast(`${label} is already running.`);
    return false;
  }
  const launchContext = getActivityRerunLaunchContext(activity);
  const didLaunch = launchSharedToolCard(toolId, launchContext);
  if (!didLaunch) {
    toast(`${label} is unavailable.`);
    return false;
  }
  return true;
}

function handleActivityTrayAccept(activityId) {
  acceptActivity(activityId);
}

function clearAllActivityNotifications() {
  activityTrayState.items
    .filter((item) => isTerminalActivityStatus(item?.status))
    .forEach((item) => {
      if (item?.toolId) {
        const activeId = activeToolActivityIds.get(item.toolId);
        releaseToolActivity(item.toolId, item.id);
        if (!activeId || activeId === item.id) {
          setToolCardRunning(item.toolId, false);
        }
      }
    });
  activityTrayState.items = activityTrayState.items.filter(
    (item) => !isTerminalActivityStatus(item?.status)
  );
  renderActivityTray();
}

function handleActivityTrayClearAll() {
  clearAllActivityNotifications();
}

function initActivityTray() {
  if (activityTrayState.initialized) return;
  activityTrayState.initialized = true;
  const { toggle, list, clearAll } = getActivityTrayElements();
  toggle?.addEventListener("click", () => {
    toggleActivityTrayCollapsed(!activityTrayState.collapsed, { force: true });
  });
  clearAll?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    handleActivityTrayClearAll();
  });
  list?.addEventListener("click", async (event) => {
    const button = event.target.closest("[data-activity-action]");
    if (!button) return;
    event.preventDefault();
    event.stopPropagation();
    const activityId = String(button.dataset.activityId || "").trim();
    const action = String(button.dataset.activityAction || "").trim().toLowerCase();
    if (action === "accept") {
      handleActivityTrayAccept(activityId);
      return;
    }
    if (action === "open") {
      await handleActivityTrayOpenFolder(activityId);
      return;
    }
    if (action === "review-canvas-panel") {
      handleActivityTrayReviewCanvasPanel(activityId);
      return;
    }
    if (action === "copy-combined-pdf") {
      await handleActivityTrayCopyCombinedPdf(activityId);
      return;
    }
    if (action === "open-combined-pdf") {
      await handleActivityTrayOpenCombinedPdf(activityId);
      return;
    }
    if (action === "dwg-compare") {
      await handleActivityTrayDwgCompare(
        activityId,
        Number(button.dataset.dwgCompareIndex || 0)
      );
      return;
    }
    if (action === "rerun") {
      await handleActivityTrayRerun(activityId);
    }
  });
  renderActivityTray();
}

function upsertActivity(nextItem, { autoExpandReason = "update" } = {}) {
  const incoming = nextItem && typeof nextItem === "object" ? nextItem : null;
  if (!incoming?.id) return null;

  const now = Date.now();
  const existing = getActivityById(incoming.id);
  const mergedToolId = String(incoming.toolId || existing?.toolId || "").trim();
  const hasIncomingRerunContext = Object.prototype.hasOwnProperty.call(
    incoming,
    "rerunLaunchContext"
  );
  const nextRerunLaunchContext = hasIncomingRerunContext
    ? deepCloneJson(incoming.rerunLaunchContext, null)
    : deepCloneJson(existing?.rerunLaunchContext, null);
  const mergedRerunDefaultPath = String(
    incoming.rerunDefaultPath || existing?.rerunDefaultPath || ""
  ).trim();
  const mergedOpenFolderPath = String(
    incoming.openFolderPath || existing?.openFolderPath || ""
  ).trim();
  const hasIncomingDwgComparePairs = Object.prototype.hasOwnProperty.call(
    incoming,
    "dwgComparePairs"
  );
  const mergedDwgComparePairs = normalizeDwgComparePairs(
    hasIncomingDwgComparePairs ? incoming.dwgComparePairs : existing?.dwgComparePairs
  );
  const mergedStatus = String(
    incoming.status || existing?.status || ACTIVITY_STATUS.RUNNING
  )
    .trim()
    .toLowerCase();
  const createdAt = normalizeActivityTimestamp(
    existing?.createdAt || incoming.createdAt,
    now
  );
  const startedAt = normalizeActivityTimestamp(
    incoming.startedAt || existing?.startedAt,
    createdAt
  );
  const endedAt = isTerminalActivityStatus(mergedStatus)
    ? normalizeActivityTimestamp(incoming.endedAt || existing?.endedAt, now)
    : 0;
  const merged = {
    id: incoming.id,
    kind: existing?.kind || incoming.kind || "tool",
    toolId: mergedToolId,
    label: String(incoming.label || existing?.label || "Activity").trim(),
    projectName: getActivityProjectName({
      projectName: incoming.projectName || existing?.projectName || "",
      launchContext: nextRerunLaunchContext,
      rerunDefaultPath: mergedRerunDefaultPath,
      openFolderPath: mergedOpenFolderPath,
    }),
    message: String(
      incoming.message == null ? existing?.message || "" : incoming.message
    ).trim(),
    status: mergedStatus,
    progress: clampActivityProgress(
      incoming.progress == null ? existing?.progress ?? 0 : incoming.progress,
      existing?.progress ?? 0
    ),
    openFolderPath: mergedOpenFolderPath,
    openFolderLabel: String(
      incoming.openFolderLabel || existing?.openFolderLabel || "Open Folder"
    ).trim(),
    combinedPdfPath: String(
      incoming.combinedPdfPath || existing?.combinedPdfPath || ""
    ).trim(),
    dwgComparePairs: mergedDwgComparePairs,
    workflowTitle: String(
      incoming.workflowTitle || existing?.workflowTitle || ""
    ).trim(),
    rerunDefaultPath: mergedRerunDefaultPath,
    rerunLaunchContext: nextRerunLaunchContext,
    canRerun:
      incoming.canRerun == null
        ? existing?.canRerun ?? isRerunnableToolId(mergedToolId)
        : Boolean(incoming.canRerun),
    canCancel:
      incoming.canCancel == null
        ? existing?.canCancel ?? ACTIVITY_CANCELLABLE_TOOL_IDS.has(mergedToolId)
        : Boolean(incoming.canCancel),
    cancelRequested: Boolean(
      incoming.cancelRequested ?? existing?.cancelRequested ?? false
    ),
    queueSequence: Math.max(
      Number(incoming.queueSequence ?? existing?.queueSequence ?? 0) || 0,
      0
    ),
    panelCount: Math.max(
      Number(incoming.panelCount ?? existing?.panelCount ?? 0) || 0,
      0
    ),
    completedCount: Math.max(
      Number(incoming.completedCount ?? existing?.completedCount ?? 0) || 0,
      0
    ),
    canvasPanelReview: Boolean(
      incoming.canvasPanelReview ?? existing?.canvasPanelReview ?? false
    ),
    createdAt,
    startedAt,
    endedAt,
    updatedAt: now,
  };

  if (existing) {
    const index = activityTrayState.items.findIndex((item) => item.id === merged.id);
    if (index >= 0) {
      activityTrayState.items.splice(index, 1, merged);
    }
  } else {
    activityTrayState.items.push(merged);
  }

  if (merged.toolId && isRunningActivityStatus(merged.status)) {
    bindToolActivity(merged.toolId, merged.id);
    setToolCardRunning(merged.toolId, true);
  } else if (merged.toolId && isTerminalActivityStatus(merged.status)) {
    const activeId = activeToolActivityIds.get(merged.toolId);
    releaseToolActivity(merged.toolId, merged.id);
    if (!activeId || activeId === merged.id) {
      setToolCardRunning(merged.toolId, false);
    }
  }

  renderActivityTray();
  maybeExpandActivityTray(autoExpandReason);
  return merged;
}

function beginActivity({
  activityId = "",
  toolId = "",
  label = "",
  projectName = "",
  message = "Starting...",
  progress = 5,
  kind = "tool",
  openFolderPath = "",
  openFolderLabel = "Open Folder",
  combinedPdfPath = "",
  dwgComparePairs = [],
  rerunDefaultPath = "",
  rerunLaunchContext = null,
  workflowTitle = "",
  canRerun,
  canCancel,
  startedAt = 0,
  endedAt = 0,
} = {}) {
  const queuedLaunch = getActivityById(activityTrayState.launchingQueuedActivityId);
  const reuseQueuedActivity = Boolean(
    !activityId &&
      queuedLaunch &&
      (isQueuedActivityStatus(queuedLaunch.status) ||
        isRunningActivityStatus(queuedLaunch.status)) &&
      String(queuedLaunch.toolId || "").trim() === String(toolId || "").trim()
  );
  const resolvedId = String(
    activityId || (reuseQueuedActivity ? queuedLaunch.id : createActivityId(toolId || kind))
  ).trim();
  if (reuseQueuedActivity) {
    activityTrayState.launchingQueuedActivityId = "";
  }
  return upsertActivity(
    {
      id: resolvedId,
      kind,
      toolId,
      label: getToolActivityLabel(toolId, label),
      projectName,
      message,
      status: ACTIVITY_STATUS.RUNNING,
      progress,
      openFolderPath,
      openFolderLabel,
      combinedPdfPath,
      dwgComparePairs,
      rerunDefaultPath,
      rerunLaunchContext,
      workflowTitle,
      canRerun,
      canCancel,
      queueSequence: reuseQueuedActivity ? queuedLaunch.queueSequence : 0,
      createdAt: reuseQueuedActivity ? queuedLaunch.createdAt : 0,
      startedAt: startedAt || (reuseQueuedActivity ? queuedLaunch.startedAt : 0),
      endedAt,
    },
    { autoExpandReason: activityTrayState.items.length ? "update" : "first" }
  )?.id || resolvedId;
}

function updateActivity(activityId, patch = {}) {
  const existing = getActivityById(activityId);
  if (!existing) return null;
  const nextStatus = String(patch.status || existing.status || ACTIVITY_STATUS.RUNNING)
    .trim()
    .toLowerCase();
  return upsertActivity(
    {
      ...existing,
      ...patch,
      id: existing.id,
      status: nextStatus,
    },
    {
      autoExpandReason:
        nextStatus === ACTIVITY_STATUS.ERROR ? "error" : "update",
    }
  );
}

function completeActivity(activityId, patch = {}) {
  const existing = getActivityById(activityId);
  if (!existing) return null;
  const nextStatus = String(patch.status || ACTIVITY_STATUS.SUCCESS).trim().toLowerCase();
  const completed = upsertActivity(
    {
      ...existing,
      ...patch,
      id: existing.id,
      status: nextStatus,
      progress: 100,
    },
    {
      autoExpandReason: nextStatus === ACTIVITY_STATUS.ERROR ? "error" : "update",
    }
  );
  scheduleNextQueuedActivity();
  return completed;
}

function failActivity(activityId, patch = {}) {
  return completeActivity(activityId, {
    ...patch,
    status: ACTIVITY_STATUS.ERROR,
    progress: 100,
  });
}

function acceptActivity(activityId) {
  const existing = getActivityById(activityId);
  if (!existing) return;
  if (existing.toolId) {
    const activeId = activeToolActivityIds.get(existing.toolId);
    releaseToolActivity(existing.toolId, activityId);
    if (!activeId || activeId === activityId) {
      setToolCardRunning(existing.toolId, false);
    }
  }
  activityTrayState.items = activityTrayState.items.filter((item) => item.id !== activityId);
  renderActivityTray();
}

function getActivityIdForTool(toolId, { create = false, label = "" } = {}) {
  const normalizedToolId = String(toolId || "").trim();
  if (!normalizedToolId) return "";
  const boundId = activeToolActivityIds.get(normalizedToolId);
  if (boundId && getActivityById(boundId)) return boundId;
  if (!create) return "";
  return beginActivity({
    toolId: normalizedToolId,
    label,
    message: "Starting...",
    progress: 5,
  });
}

function normalizeActivityStatusFromPayload(payload = {}, message = "", fallback = ACTIVITY_STATUS.RUNNING) {
  const rawStatus = String(payload?.status || "").trim().toLowerCase();
  if (
    [
      ACTIVITY_STATUS.QUEUED,
      ACTIVITY_STATUS.RUNNING,
      ACTIVITY_STATUS.SUCCESS,
      ACTIVITY_STATUS.WARNING,
      ACTIVITY_STATUS.ERROR,
      ACTIVITY_STATUS.CANCELLED,
    ].includes(rawStatus)
  ) {
    return rawStatus;
  }
  if (message === "DONE") return ACTIVITY_STATUS.SUCCESS;
  if (message.startsWith("WARN:") || message.startsWith("WARNING:")) {
    return ACTIVITY_STATUS.WARNING;
  }
  if (message.startsWith("ERROR:")) return ACTIVITY_STATUS.ERROR;
  return String(fallback || ACTIVITY_STATUS.RUNNING).trim().toLowerCase();
}

function getActivityLabelFromPayload(toolId, payload = {}, existing = null) {
  const normalizedToolId = String(toolId || "").trim();
  const workflowTitle = String(payload?.workflowTitle || existing?.workflowTitle || "").trim();
  const payloadLabel = String(payload?.label || "").trim();
  if (normalizedToolId === "toolWorkflow" && workflowTitle) {
    return getToolActivityLabel(
      normalizedToolId,
      payloadLabel || `Workflow: ${workflowTitle}`
    );
  }
  return getToolActivityLabel(normalizedToolId, payloadLabel || existing?.label || "");
}

function deriveToolActivityProgress(toolId, message, currentProgress = 5) {
  const normalizedToolId = String(toolId || "").trim();
  const text = String(message || "").trim();
  if (!text) return clampActivityProgress(currentProgress, 5);
  if (normalizedToolId === "toolCleanDrawings") {
    let progress = currentProgress;
    if (/^Finding electrical/.test(text)) progress = 4;
    else if (/^Finding published/.test(text)) progress = 8;
    else if (/^Reading PDF/.test(text)) progress = 12;
    else if (/^Inspecting paper-space/.test(text)) progress = 16;
    else if (/^Inspecting drawings and required/.test(text)) progress = 25;
    else if (/^Copying/.test(text)) progress = 30;
    else if (/^Redirecting/.test(text)) progress = 35;
    else if (/^Cleaning the titleblock/.test(text)) progress = 40;
    else if (/^Validating the saved titleblock/.test(text)) progress = 45;
    else if (/^Checking source versions/.test(text)) progress = 95;
    const drawing = text.match(/^(Cleaning|Validating) drawing (\d+) of (\d+):/);
    if (drawing) {
      const fraction = (Number(drawing[2]) - (drawing[1] === "Cleaning" ? 1 : 0.25)) / Math.max(Number(drawing[3]), 1);
      progress = 45 + 45 * fraction;
    }
    // Worker heartbeat messages retain the stage's progress; never imply completion early.
    return clampActivityProgress(Math.max(Number(currentProgress) || 0, Number(progress) || 0), 2);
  }
  if (text === "DONE" || text.startsWith("WARN:") || text.startsWith("ERROR:")) {
    return 100;
  }

  const fileMatch = text.match(/(?:Plotting|Processing|Updating)\s+(\d+)\s+of\s+(\d+)\s*:/i);
  if (fileMatch) {
    const completed = Number(fileMatch[1]);
    const total = Math.max(Number(fileMatch[2]), 1);
    if (Number.isFinite(completed) && Number.isFinite(total)) {
      return clampActivityProgress(20 + (completed / total) * 65, currentProgress);
    }
  }

  if (normalizedToolId === "toolPublishDwgs") {
    if (/Waiting for paper size/i.test(text)) return 15;
    if (/Using auto-selected|Received auto-selected|Found AutoCAD|Using specified AutoCAD/i.test(text)) return 10;
    if (/Combining/i.test(text)) return 90;
    if (/Shrinking/i.test(text)) return 95;
    if (/No PDFs were generated/i.test(text)) return 95;
  }

  if (
    ["toolManageLayers", "toolRepairXrefPaths", "toolCleanXrefs"].includes(
      normalizedToolId
    )
  ) {
    if (/Waiting for layer selection|Waiting for XREF path selections|Waiting for user input/i.test(text)) {
      return 15;
    }
    if (/Reading extracted data|Scanning \d+ of \d+|Using \d+ (?:selected )?DWG|ZIP source selected|Found \d+ DWG/i.test(text)) {
      return 20;
    }
    if (/Successfully processed|Processing \d+ file\(s\)/i.test(text)) return 92;
  }

  if (/Select project folder|Select output folder/i.test(text)) return 10;
  if (/Resolving project folder|Resolving/i.test(text)) return 18;
  if (/Copying|Syncing|Creating archive backup|Saving|Installing|Updating|Uninstalling/i.test(text)) {
    return Math.max(clampActivityProgress(currentProgress, 25), 35);
  }

  return clampActivityProgress(currentProgress, 12);
}

function updateActivityStatusFromPayload(payload = {}) {
  const toolId = String(payload?.toolId || "").trim();
  const activityId =
    String(payload?.activityId || "").trim() ||
    (toolId ? getActivityIdForTool(toolId, { create: true }) : beginActivity({ kind: "activity" }));
  const existing = getActivityById(activityId);
  const rawMessage = String(payload?.message || "").trim();
  const status = normalizeActivityStatusFromPayload(payload, rawMessage, existing?.status);

  let nextMessage = rawMessage;
  let openFolderPath = String(
    payload?.openFolderPath ||
      payload?.outputFolderPath ||
      payload?.bundlePath ||
      payload?.pluginsFolderPath ||
      payload?.archivePath ||
      payload?.localProjectPath ||
      payload?.serverProjectPath ||
      payload?.outputFolder ||
      payload?.folderPath ||
      existing?.openFolderPath ||
      ""
  ).trim();
  let combinedPdfPath = String(
    payload?.combinedPdfPath || existing?.combinedPdfPath || ""
  ).trim();
  let dwgComparePairs = normalizeDwgComparePairs(
    payload?.dwgComparePairs || existing?.dwgComparePairs || []
  );
  let rerunDefaultPath = String(
    payload?.rerunDefaultPath || existing?.rerunDefaultPath || ""
  ).trim();
  const rerunLaunchContext = Object.prototype.hasOwnProperty.call(
    payload,
    "rerunLaunchContext"
  )
    ? payload.rerunLaunchContext
    : existing?.rerunLaunchContext || null;
  const workflowTitle = String(
    payload?.workflowTitle || existing?.workflowTitle || ""
  ).trim();
  const projectName = getActivityProjectName({
    projectName: payload?.projectName || existing?.projectName || "",
    launchContext: rerunLaunchContext,
    rerunDefaultPath,
    openFolderPath,
  });
  const activityLabel = getActivityLabelFromPayload(toolId, payload, existing);

  if (rawMessage.startsWith("OUTPUT_FOLDER:")) {
    openFolderPath = rawMessage.substring("OUTPUT_FOLDER:".length).trim();
    nextMessage = existing?.message || "Working...";
  } else if (rawMessage.startsWith("COMBINED_PDF:")) {
    combinedPdfPath = rawMessage.substring("COMBINED_PDF:".length).trim();
    nextMessage = existing?.message || "Working...";
  } else if (rawMessage.startsWith("INPUT_FOLDER:")) {
    rerunDefaultPath = rawMessage.substring("INPUT_FOLDER:".length).trim();
    nextMessage = existing?.message || "Working...";
  } else if (rawMessage.startsWith("DWG_COMPARE_PAIR:")) {
    const pairJson = rawMessage.substring("DWG_COMPARE_PAIR:".length).trim();
    try {
      dwgComparePairs = appendDwgComparePair(dwgComparePairs, JSON.parse(pairJson));
    } catch (error) {
      console.warn("Ignoring invalid DWG compare activity metadata:", error);
    }
    nextMessage = existing?.message || "Working...";
  } else if (rawMessage.startsWith("WARN:")) {
    nextMessage = rawMessage.substring(5).trim() || "Completed with warnings.";
  } else if (rawMessage.startsWith("WARNING:")) {
    nextMessage = rawMessage.substring(8).trim() || "Completed with warnings.";
  } else if (rawMessage.startsWith("ERROR:")) {
    nextMessage = rawMessage.substring(6).trim() || "Activity failed.";
  } else if (rawMessage === "DONE") {
    nextMessage = payload?.completedMessage || existing?.message || "Done.";
  }

  const explicitProgress = Number(payload?.progress);
  let nextProgress = Number.isFinite(explicitProgress)
    ? clampActivityProgress(explicitProgress, existing?.progress ?? 0)
    : deriveToolActivityProgress(toolId, rawMessage, existing?.progress ?? 5);

  if (toolId === "toolCircuitBreaker") {
    const panelCount = Math.max(Number(payload?.panelCount || existing?.panelCount || 0), 0);
    const completedCount = Math.max(
      Number(
        payload?.completedCount ??
          (Number(payload?.successCount || 0) + Number(payload?.failureCount || 0))
      ) || 0,
      0
    );
    if (status === ACTIVITY_STATUS.RUNNING && panelCount > 0) {
      nextProgress = clampActivityProgress(20 + (completedCount / panelCount) * 70, nextProgress);
    }
  }

  if (!existing) {
    beginActivity({
      activityId,
      toolId,
      label: activityLabel,
      projectName,
      message: nextMessage || "Starting...",
      progress: nextProgress,
      openFolderPath,
      openFolderLabel: payload?.openFolderLabel || "Open Folder",
      combinedPdfPath,
      dwgComparePairs,
      rerunDefaultPath,
      rerunLaunchContext,
      workflowTitle,
      canRerun: payload?.canRerun,
      kind: payload?.kind || (toolId === "toolWorkflow" ? "workflow" : "tool"),
      startedAt: payload?.startedAt,
      endedAt: payload?.endedAt,
    });
  }

  const commonPatch = {
    label: activityLabel,
    projectName,
    message:
      nextMessage ||
      existing?.message ||
      (status === ACTIVITY_STATUS.ERROR ? "Activity failed." : "Working..."),
    progress: isTerminalActivityStatus(status) ? 100 : nextProgress,
    openFolderPath,
    openFolderLabel: String(
      payload?.openFolderLabel || existing?.openFolderLabel || "Open Folder"
    ).trim(),
    combinedPdfPath,
    dwgComparePairs,
    rerunDefaultPath,
    rerunLaunchContext,
    workflowTitle,
    canRerun: payload?.canRerun,
    panelCount: payload?.panelCount,
    completedCount: payload?.completedCount,
    startedAt: payload?.startedAt,
    endedAt: payload?.endedAt,
  };

  if (status === ACTIVITY_STATUS.ERROR) {
    failActivity(activityId, commonPatch);
    return activityId;
  }
  if (
    status === ACTIVITY_STATUS.SUCCESS ||
    status === ACTIVITY_STATUS.WARNING ||
    status === ACTIVITY_STATUS.CANCELLED
  ) {
    completeActivity(activityId, {
      ...commonPatch,
      status,
    });
    return activityId;
  }
  updateActivity(activityId, {
    ...commonPatch,
    status: ACTIVITY_STATUS.RUNNING,
  });
  return activityId;
}

window.updateActivityStatus = function (payload) {
  initActivityTray();
  return updateActivityStatusFromPayload(payload);
};

function reportClientError(message, error) {
  const detail = error?.message || error?.toString?.() || "";
  const payload = detail ? `${message}: ${detail}` : message;
  console.error(payload, error || "");
  try {
    toast(payload, 6000);
  } catch {
    try {
      alert(payload);
    } catch {
      /* noop */
    }
  }
}

window.addEventListener("error", (event) => {
  reportClientError("JS error", event?.error || event?.message);
});

window.addEventListener("unhandledrejection", (event) => {
  reportClientError("Unhandled promise rejection", event?.reason);
});

function showDialog(dialogEl) {
  if (!dialogEl) return false;
  try {
    dialogEl.showModal();
    return true;
  } catch (err) {
    try {
      dialogEl.setAttribute("open", "");
      return true;
    } catch (fallbackErr) {
      reportClientError("Failed to open dialog", fallbackErr);
      return false;
    }
  }
}

const updateStickyOffsets = () => {
  const header = document.querySelector(".app-header");
  const toolbar = document.querySelector("#projects-panel .panel-toolbar");
  const projectsFilters = document.querySelector(
    "#projects-panel .projects-filter-controls"
  );
  if (header)
    document.documentElement.style.setProperty(
      "--header-height",
      `${header.offsetHeight}px`
    );
  if (toolbar)
    document.documentElement.style.setProperty(
      "--toolbar-height",
      `${toolbar.offsetHeight}px`
    );
  if (projectsFilters)
    document.documentElement.style.setProperty(
      "--projects-filters-height",
      `${projectsFilters.offsetHeight}px`
    );
};

const debouncedStickyOffsets = debounce(updateStickyOffsets, 150);
window.addEventListener("resize", debouncedStickyOffsets);

const PROJECTS_BACK_TO_TOP_SCROLL_THRESHOLD = 240;

const isProjectsTabActive = () => {
  const panel = document.getElementById("projects-panel");
  return Boolean(panel && !panel.hidden && panel.classList.contains("active"));
};

function updateProjectsBackToTopVisibility() {
  const backToTopBtn = document.getElementById("projectsBackToTopBtn");
  if (!backToTopBtn) return;
  const scrollTop = window.scrollY || document.documentElement.scrollTop || 0;
  const shouldShow =
    isProjectsTabActive() && scrollTop > PROJECTS_BACK_TO_TOP_SCROLL_THRESHOLD;
  backToTopBtn.classList.toggle("is-visible", shouldShow);
  backToTopBtn.setAttribute("aria-hidden", shouldShow ? "false" : "true");
}

function initProjectsBackToTop() {
  const backToTopBtn = document.getElementById("projectsBackToTopBtn");
  if (!backToTopBtn) return;
  backToTopBtn.addEventListener("click", () => {
    window.scrollTo({ top: 0, behavior: "smooth" });
  });
  window.addEventListener("scroll", updateProjectsBackToTopVisibility, {
    passive: true,
  });
  window.addEventListener("resize", updateProjectsBackToTopVisibility);
  updateProjectsBackToTopVisibility();
}

