function getDefaultProjectCardColumn(key) {
  return PROJECT_CARD_COLUMNS_BY_KEY.get(String(key || "").trim()) || null;
}

function getProjectCardColumnLabel(column) {
  const fallback = getDefaultProjectCardColumn(column?.key);
  const label =
    typeof column?.label === "string" ? column.label.trim() : "";
  return label || fallback?.label || String(column?.key || "").trim();
}

function normalizeProjectCardColumns(raw) {
  const defaults = DEFAULT_PROJECT_CARD_COLUMNS;
  const defaultKeys = new Set(defaults.map((c) => c.key));
  const list = Array.isArray(raw) ? raw : [];
  const seen = new Set();
  const normalized = [];
  const findDefaultIndex = (key) =>
    defaults.findIndex((defaultColumn) => defaultColumn.key === key);
  const insertMissingColumn = (column) => {
    const defaultIndex = findDefaultIndex(column.key);
    const previousDefaultKeys = defaults
      .slice(0, defaultIndex)
      .map((defaultColumn) => defaultColumn.key)
      .reverse();
    const previousKey = previousDefaultKeys.find((key) =>
      normalized.some((existing) => existing.key === key)
    );
    if (previousKey) {
      const previousIndex = normalized.findIndex(
        (existing) => existing.key === previousKey
      );
      normalized.splice(previousIndex + 1, 0, { ...column });
      seen.add(column.key);
      return;
    }
    const nextIndex = normalized.findIndex(
      (existing) => findDefaultIndex(existing.key) > defaultIndex
    );
    if (nextIndex >= 0) {
      normalized.splice(nextIndex, 0, { ...column });
    } else {
      normalized.push({ ...column });
    }
    seen.add(column.key);
  };

  for (const entry of list) {
    if (!entry || typeof entry !== "object") continue;
    const oldKey = String(entry.key || "").trim();
    const key = oldKey === "none" ? "In progress" : oldKey;
    if (!key || !defaultKeys.has(key) || seen.has(key)) continue;
    normalized.push({
      key,
      label: getProjectCardColumnLabel({ key, label: oldKey === "none" ? "In progress" : entry.label }),
      hidden: entry.hidden === true,
    });
    seen.add(key);
  }
  for (const col of defaults) {
    if (!seen.has(col.key)) insertMissingColumn(col);
  }
  return normalized;
}

