async function init() {
  showAppLoader();
  window.addEventListener("pagehide", () => {
    if (typeof debouncedSaveUserSettings?.flush === "function") {
      debouncedSaveUserSettings.flush();
    }
  });
  try {
    if (!window.pywebview)
      await new Promise((r) => window.addEventListener("pywebviewready", r));
    initEventListeners();
    initTabbedInterfaces();
    initProjectsBackToTop();
    updateStickyOffsets();
    refreshAppUpdateStatus();
    await loadGoogleAuthState({ silent: true });
    await loadUserSettings();
    initThemeFromPreferences();
    const [
      loadedDb,
      loadedNotes,
      loadedTimesheets,
      loadedTemplates,
      loadedChecklists,
    ] = await Promise.all([
      load(),
      loadGlobalPages(),
      loadTimesheets(),
      loadTemplates(),
      loadChecklists(),
    ]);
    db = loadedDb || [];
    globalPages = Array.isArray(loadedNotes) ? loadedNotes : [];
    timesheetDb = loadedTimesheets || { weeks: {}, expenses: {}, lastModified: null };
    if (!timesheetDb.expenses || typeof timesheetDb.expenses !== "object") {
      timesheetDb.expenses = {};
    }
    templatesDb = loadedTemplates || {
      templates: [],
      defaultTemplatesInstalled: false,
      lastModified: null,
    };
    checklistsDb = loadedChecklists || {
      checklists: [],
      templateOverrides: {},
      lastModified: null,
    };


    if (checklistsDb.checklists.length > 0) {
      activeChecklistTabId =
        checklistsDb.checklists.find((checklist) => checklist.id === activeChecklistTabId)
          ?.id || checklistsDb.checklists[0].id;
    } else {
      activeChecklistTabId = null;
    }

    if (isNewUser()) {
      hideMainApp();
      showOnboardingModal();
    } else {
      showMainApp();
      renderGlobalPagesView();
      renderChecklistTabs();
      renderChecklistsView();
      renderTemplates();
      renderTimesheets();
      render();
      updateTimesheetsDuplicateIndicator(
        getWeekEntries(formatWeekKey(currentTimesheetWeek))
      );

      if (userSettings.showSetupHelp !== false) {
        setTimeout(() => showSetupHelpBanner(), 1000);
      }
    }
    await showDataRecoveryNotices();
    if (projectDataLoadError) {
      // Let the loader close first so the warning is not hidden behind it.
      setTimeout(showProjectDataLoadError, 300);
    }
    prefetchBundles();
  } finally {
    hideAppLoader();
  }
}

