const PAGE_IMAGE_MIN_PERCENT = 10;
const PAGE_IMAGE_MAX_PERCENT = 100;
const PAGE_IMAGE_STEP_PERCENT = 5;
const PAGE_IMAGE_DEFAULT_PERCENT = 80;

function getPageEditorEl() {
  return document.getElementById("pageEditor");
}
function getProjectPagesEditorRoot() {
  return document.getElementById("projectPagesEditorRoot");
}
function isProjectPagesEditorAvailable() {
  return !!window.ProjectPagesEditor?.mount;
}
function prepareProjectPagesEditorMount() {
  const root = getProjectPagesEditorRoot();
  if (!root) return null;
  const parent = root.parentElement;
  if (parent) {
    Array.from(parent.children).forEach((child) => {
      if (child !== root) child.remove();
    });
  }
  return root;
}
function normalizeHtmlForProjectPagesEditor(html) {
  const holder = document.createElement("div");
  holder.innerHTML = html || "";
  flattenLegacyPageItems(holder);
  normalizePageChecklistItems(holder);
  holder.querySelectorAll("img").forEach((img) => {
    img.classList.add("page-inline-image");
    if (!img.alt) img.alt = "Image";
    if (img.dataset.asset) img.removeAttribute("src");
  });
  hydratePageWikiLinks(holder);
  return holder.innerHTML;
}
function setPageSaveStatus(text) {
  const el = document.getElementById("pageSaveStatus");
  if (el) {
    el.textContent = text || "";
    if (text === "Save failed") {
      const retry = document.createElement("button");
      retry.type = "button";
      retry.className = "btn mini";
      retry.textContent = "Retry";
      retry.addEventListener("click", () => void flushPageSave());
      el.append(" ", retry);
    }
    el.classList.toggle("is-saved", text === "Saved" || text === "Published");
  }
}

const PAGE_FIND_MATCH_SELECTOR = 'mark.page-find-match[data-page-find-match="true"]';
const PAGE_FIND_HIGHLIGHT_NAME = "page-find-match";
const PAGE_FIND_ACTIVE_HIGHLIGHT_NAME = "page-find-active";
const PAGE_FIND_TEXT_BLOCK_SELECTOR = [
  "p",
  "h1",
  "h2",
  "h3",
  "h4",
  "h5",
  "h6",
  "li",
  "pre",
  "blockquote",
  "td",
  "th",
  "summary",
  "figcaption",
  ".page-workbook",
].join(",");

function getPageFindRoots() {
  return [document.getElementById("pageTitle"), getPageEditorEl()].filter(Boolean);
}

function pageFindCssHighlightsAvailable() {
  return (
    typeof Highlight === "function" &&
    !!globalThis.CSS?.highlights &&
    typeof globalThis.CSS.highlights.set === "function" &&
    typeof globalThis.CSS.highlights.delete === "function"
  );
}

function clearPageFindCssHighlights() {
  if (!pageFindCssHighlightsAvailable()) return;
  globalThis.CSS.highlights.delete(PAGE_FIND_HIGHLIGHT_NAME);
  globalThis.CSS.highlights.delete(PAGE_FIND_ACTIVE_HIGHLIGHT_NAME);
}

function unwrapPageFindHighlights(root) {
  if (!root?.querySelectorAll) return;
  const doc = root.ownerDocument || document;
  root.querySelectorAll(PAGE_FIND_MATCH_SELECTOR).forEach((mark) => {
    mark.replaceWith(doc.createTextNode(mark.textContent || ""));
  });
  try {
    root.normalize();
  } catch (_) {}
}

function clearPageFindHighlights({ updateUi = true } = {}) {
  clearPageFindCssHighlights();
  getPageFindRoots().forEach(unwrapPageFindHighlights);
  pageFindState.matches = [];
  pageFindState.matchCount = 0;
  pageFindState.activeIndex = -1;
  if (updateUi) updatePageFindUi();
}

function getPageFindTextBlock(node, root) {
  let element = node?.parentElement || null;
  let topLevelElement = element;
  while (element && element !== root) {
    topLevelElement = element;
    if (element.matches?.(PAGE_FIND_TEXT_BLOCK_SELECTOR)) return element;
    element = element.parentElement;
  }
  return topLevelElement || root;
}

function collectPageFindTextParts(root) {
  const parts = [];
  let text = "";
  let previousBlock = null;
  if (!root) return { text, parts };
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      const value = String(node.nodeValue || "");
      if (!value) return NodeFilter.FILTER_REJECT;
      if (node.parentElement?.closest?.(PAGE_FIND_MATCH_SELECTOR)) {
        return NodeFilter.FILTER_REJECT;
      }
      return NodeFilter.FILTER_ACCEPT;
    },
  });
  let node = walker.nextNode();
  while (node) {
    const value = String(node.nodeValue || "");
    const block = getPageFindTextBlock(node, root);
    // A separator prevents a query from becoming a false match across unrelated
    // paragraphs, table cells, list items, or other block-level content.
    if (text && previousBlock && block !== previousBlock) text += "\n";
    parts.push({ node, start: text.length, end: text.length + value.length });
    text += value;
    previousBlock = block;
    node = walker.nextNode();
  }
  return { text, parts };
}

function getPageFindRanges(text, query, startIndex = 0) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return [];
  const lower = String(text || "").toLowerCase();
  const ranges = [];
  let idx = lower.indexOf(q);
  while (idx !== -1) {
    ranges.push({
      start: idx,
      end: idx + q.length,
      index: startIndex + ranges.length,
    });
    idx = lower.indexOf(q, idx + q.length);
  }
  return ranges;
}

function createPageFindDomRange(parts, match) {
  const startPart = parts.find(
    (part) => match.start >= part.start && match.start < part.end
  );
  const endPart = parts.find(
    (part) => match.end > part.start && match.end <= part.end
  );
  if (!startPart || !endPart) return null;
  const doc = startPart.node.ownerDocument || document;
  const range = doc.createRange();
  try {
    range.setStart(startPart.node, match.start - startPart.start);
    range.setEnd(endPart.node, match.end - endPart.start);
    return range;
  } catch (_) {
    range.detach?.();
    return null;
  }
}

function highlightPageFindMatchesInRoot(root, query, startIndex = 0) {
  const { text, parts } = collectPageFindTextParts(root);
  const ranges = getPageFindRanges(text, query, startIndex);
  const matches = ranges
    .map((match) => ({
      index: match.index,
      range: createPageFindDomRange(parts, match),
    }))
    .filter((match) => !!match.range);
  return {
    matches,
    nextIndex: startIndex + matches.length,
  };
}

function renderPageFindHighlights() {
  if (!pageFindCssHighlightsAvailable()) return;
  const ranges = pageFindState.matches.map((match) => match.range);
  if (ranges.length) {
    globalThis.CSS.highlights.set(
      PAGE_FIND_HIGHLIGHT_NAME,
      new Highlight(...ranges)
    );
  } else {
    globalThis.CSS.highlights.delete(PAGE_FIND_HIGHLIGHT_NAME);
  }
}

function getPageFindMatch(index = pageFindState.activeIndex) {
  if (index < 0) return null;
  return pageFindState.matches[index] || null;
}

function renderPageFindActiveHighlight(match) {
  if (!pageFindCssHighlightsAvailable()) return;
  globalThis.CSS.highlights.delete(PAGE_FIND_ACTIVE_HIGHLIGHT_NAME);
  if (!match?.range) return;
  const activeHighlight = new Highlight(match.range);
  activeHighlight.priority = 1;
  globalThis.CSS.highlights.set(
    PAGE_FIND_ACTIVE_HIGHLIGHT_NAME,
    activeHighlight
  );
}

function scrollPageFindMatchIntoView(match) {
  const range = match?.range;
  if (!range) return;
  const rects = Array.from(range.getClientRects?.() || []);
  const rect =
    rects.find((candidate) => candidate.width || candidate.height) ||
    range.getBoundingClientRect?.();
  const scrollContainer = document.querySelector("#pageView .page-view-scroll");
  if (scrollContainer && rect && (rect.width || rect.height)) {
    const containerRect = scrollContainer.getBoundingClientRect();
    const targetTop =
      scrollContainer.scrollTop +
      (rect.top - containerRect.top) -
      (scrollContainer.clientHeight - rect.height) / 2;
    const maxTop = Math.max(
      0,
      scrollContainer.scrollHeight - scrollContainer.clientHeight
    );
    scrollContainer.scrollTo({
      top: Math.max(0, Math.min(maxTop, targetTop)),
      behavior: "smooth",
    });
    return;
  }
  const startElement =
    range.startContainer?.nodeType === Node.ELEMENT_NODE
      ? range.startContainer
      : range.startContainer?.parentElement;
  startElement?.scrollIntoView?.({
    behavior: "smooth",
    block: "center",
    inline: "nearest",
  });
}

function updatePageFindUi() {
  const input = document.getElementById("pageFindInput");
  const countEl = document.getElementById("pageFindCount");
  const prevBtn = document.getElementById("pageFindPrevBtn");
  const nextBtn = document.getElementById("pageFindNextBtn");
  if (input && input.value !== pageFindState.query) {
    input.value = pageFindState.query;
  }
  const hasQuery = String(pageFindState.query || "").trim().length > 0;
  document.getElementById("pageFind")?.classList.toggle("has-query", hasQuery);
  if (countEl) {
    countEl.textContent = hasQuery
      ? pageFindState.matchCount
        ? `${pageFindState.activeIndex + 1} / ${pageFindState.matchCount}`
        : "0 / 0"
      : "";
  }
  const disabled = !pageFindState.matchCount;
  if (prevBtn) prevBtn.disabled = disabled;
  if (nextBtn) nextBtn.disabled = disabled;
}

function setPageFindActiveMatch(index, { scroll = true } = {}) {
  if (!pageFindState.matchCount) {
    pageFindState.activeIndex = -1;
    renderPageFindActiveHighlight(null);
    updatePageFindUi();
    return;
  }
  const count = pageFindState.matchCount;
  pageFindState.activeIndex = (index + count) % count;
  const active = getPageFindMatch(pageFindState.activeIndex);
  renderPageFindActiveHighlight(active);
  if (scroll) scrollPageFindMatchIntoView(active);
  updatePageFindUi();
}

function applyPageFindHighlights({ preserveIndex = true, scroll = false } = {}) {
  const previousIndex = pageFindState.activeIndex;
  clearPageFindHighlights({ updateUi: false });
  const query = String(pageFindState.query || "").trim();
  if (!query) {
    updatePageFindUi();
    return;
  }
  let nextIndex = 0;
  const matches = [];
  getPageFindRoots().forEach((root) => {
    const result = highlightPageFindMatchesInRoot(root, query, nextIndex);
    matches.push(...result.matches);
    nextIndex = result.nextIndex;
  });
  pageFindState.matches = matches;
  pageFindState.matchCount = matches.length;
  renderPageFindHighlights();
  const activeIndex =
    preserveIndex && previousIndex >= 0
      ? Math.min(previousIndex, pageFindState.matchCount - 1)
      : 0;
  setPageFindActiveMatch(activeIndex, { scroll: scroll && pageFindState.matchCount > 0 });
}

function stepPageFindMatch(delta) {
  if (!pageFindState.matchCount) return;
  setPageFindActiveMatch(pageFindState.activeIndex + delta, { scroll: true });
}

function queuePageFindRefresh() {
  if (!String(pageFindState.query || "").trim()) return;
  if (pageFindRefreshTimer) clearTimeout(pageFindRefreshTimer);
  pageFindRefreshTimer = setTimeout(() => {
    pageFindRefreshTimer = null;
    applyPageFindHighlights({ preserveIndex: true, scroll: false });
  }, 100);
}

function handlePageFindInput(event) {
  pageFindState.query = String(event?.target?.value || "");
  applyPageFindHighlights({ preserveIndex: false, scroll: true });
}

function handlePageFindKeydown(event) {
  if (event.key === "Enter") {
    event.preventDefault();
    stepPageFindMatch(event.shiftKey ? -1 : 1);
  } else if (event.key === "Escape") {
    event.preventDefault();
    event.stopPropagation();
    if (String(pageFindState.query || "").trim()) {
      pageFindState.query = "";
      clearPageFindHighlights();
    } else {
      event.currentTarget?.blur?.();
    }
  }
}

function focusPageFindInput() {
  const input = document.getElementById("pageFindInput");
  if (!input) return;
  input.focus();
  input.select();
}

// --- Selection helpers (scoped to the page editor) ---
function pageNodeInEditor(node, editor) {
  if (!node || !editor) return false;
  const target = node.nodeType === Node.TEXT_NODE ? node.parentNode : node;
  return !!target && editor.contains(target);
}
function clonePageRange(range) {
  try {
    return range ? range.cloneRange() : null;
  } catch (_) {
    return null;
  }
}
function getPageSelectionRange(editor) {
  const sel = window.getSelection?.();
  if (!sel || sel.rangeCount === 0) return null;
  const range = sel.getRangeAt(0);
  return pageNodeInEditor(range.commonAncestorContainer, editor) ? range : null;
}
function savePageSelection(editor) {
  const range = getPageSelectionRange(editor);
  if (range) pageSelectionRange = clonePageRange(range);
}
function restorePageSelection(editor) {
  if (!editor) return null;
  editor.focus();
  let range = clonePageRange(pageSelectionRange);
  if (!range || !pageNodeInEditor(range.commonAncestorContainer, editor)) {
    range = document.createRange();
    range.selectNodeContents(editor);
    range.collapse(false);
  }
  const sel = window.getSelection?.();
  if (sel) {
    sel.removeAllRanges();
    sel.addRange(range);
  }
  pageSelectionRange = clonePageRange(range);
  return range;
}
function placePageCaretAfterNode(editor, node) {
  if (!editor) return;
  const range = document.createRange();
  if (node?.parentNode) range.setStartAfter(node);
  else range.selectNodeContents(editor);
  range.collapse(true);
  const sel = window.getSelection?.();
  if (sel) {
    sel.removeAllRanges();
    sel.addRange(range);
  }
  pageSelectionRange = clonePageRange(range);
}
function movePageCaretToPoint(editor, x, y) {
  if (!editor) return;
  let range = null;
  if (document.caretRangeFromPoint) {
    range = document.caretRangeFromPoint(x, y);
  } else if (document.caretPositionFromPoint) {
    const pos = document.caretPositionFromPoint(x, y);
    if (pos?.offsetNode) {
      range = document.createRange();
      range.setStart(pos.offsetNode, pos.offset);
      range.collapse(true);
    }
  }
  if (!range || !pageNodeInEditor(range.commonAncestorContainer, editor)) return;
  const sel = window.getSelection?.();
  if (sel) {
    sel.removeAllRanges();
    sel.addRange(range);
  }
  pageSelectionRange = clonePageRange(range);
}

// --- Serialization & save ---
function getPageWorkbookRefs(pageTarget) {
  const html = String(pageTarget?.page?.html || "");
  if (!html || !html.includes("data-page-file")) return [];
  const doc = new DOMParser().parseFromString(`<div>${html}</div>`, "text/html");
  return Array.from(doc.querySelectorAll(".page-workbook[data-page-file]"))
    .map((card) => String(card.getAttribute("data-page-file") || "").trim())
    .filter(Boolean);
}

async function deleteManagedPageWorkbooks(pageTargets) {
  const refs = Array.from(
    new Set((Array.isArray(pageTargets) ? pageTargets : []).flatMap(getPageWorkbookRefs))
  );
  if (!refs.length) return { status: "success", deleted: 0, missing: 0, failed: [] };
  if (!window.pywebview?.api?.delete_page_files) {
    return {
      status: "partial",
      deleted: 0,
      missing: 0,
      failed: refs.map((fileRef) => ({ fileRef, message: "Managed file deletion is unavailable." })),
    };
  }
  try {
    return await window.pywebview.api.delete_page_files(refs);
  } catch (error) {
    return {
      status: "partial",
      deleted: 0,
      missing: 0,
      failed: refs.map((fileRef) => ({ fileRef, message: String(error?.message || error) })),
    };
  }
}

function reportPageWorkbookCleanup(result) {
  const failedCount = Array.isArray(result?.failed) ? result.failed.length : 0;
  if (!failedCount) return;
  toast(
    `Deletion completed, but ${failedCount} workbook${failedCount === 1 ? "" : "s"} could not be removed from local storage.`
  );
}

function serializePageHtml(editor) {
  if (!editor) return "";
  syncPageChecklistItems(editor);
  const clone = editor.cloneNode(true);
  unwrapPageFindHighlights(clone);
  clone.querySelectorAll("img").forEach((img) => {
    img.classList.add("page-inline-image");
    img.classList.remove("is-selected");
    if (img.dataset.asset) img.removeAttribute("src");
  });
  // Strip transient hydration state from wiki links; data-page-id is the source of
  // truth and the title/broken state are recomputed on load.
  clone.querySelectorAll("a.page-wiki-link").forEach((link) => {
    link.classList.remove("is-broken");
    link.removeAttribute("title");
  });
  return clone.innerHTML;
}
// Route page persistence to the correct store: global pages -> notes.json,
// project notes and subpages -> tasks.json.
async function persistActivePage() {
  if (pageNav.globalPage) return saveGlobalPages({ silent: true });
  return save({ silent: true });
}
// All page edits share one serialized, revision-aware persistence queue.
const pagePersistence = window.ProjectPagesEditor.createSaveQueue({
  persist: persistActivePage,
  onStatus: setPageSaveStatus,
});
function queueProjectPagesEditorSave(html, { persist = true } = {}) {
  if (!pageEditorTarget) return;
  const next = String(html || "");
  if (pageEditorTarget.html === next) return;
  pageEditorTarget.html = next;
  pageEditorTarget.updatedAt = new Date().toISOString();
  pagePersistence.dirty();
  queuePageFindRefresh();
}
function queuePageSave() {
  const editor = getPageEditorEl();
  if (!editor || !pageEditorTarget) return;
  queueProjectPagesEditorSave(serializePageHtml(editor));
}
async function flushPageSave() {
  try {
    if (window.ProjectPagesEditor?.flushSave) {
      await window.ProjectPagesEditor.flushSave();
    }
    const editor = getPageEditorEl();
    const reactEditorActive = !!getProjectPagesEditorRoot()?.querySelector("#pageEditor");
    if (!reactEditorActive && editor && pageEditorTarget && !isCanvasPage(pageEditorTarget)) {
      queuePageSave();
    }
    if (await pagePersistence.flush()) return true;
  } catch (error) {
    console.warn("Page save failed:", error);
    setPageSaveStatus("Save failed");
  }
  toast("Your changes have not been saved. Use Retry before leaving this page.");
  return false;
}

function getActivePagePdfPayload() {
  const { project, subpage, globalPage } = pageNav;
  if (globalPage) {
    return {
      kind: "global",
      title: globalPage.title || "Untitled",
      projectName: "",
      html: pageEditorTarget?.html || globalPage.page?.html || "",
      defaultDirectory: "",
    };
  }
  if (!project) return null;
  return {
    kind: subpage ? "subpage" : "project",
    title: (subpage ? subpage.title : project.name) || "Untitled",
    projectName: project.name || "",
    html: pageEditorTarget?.html || (subpage ? subpage.page?.html : project.page?.html) || "",
    defaultDirectory: project.path || "",
  };
}

async function publishActivePagePdf() {
  const button = document.getElementById("pagePublishPdfBtn");
  if (!window.pywebview?.api?.publish_project_page_pdf) {
    toast("PDF publishing is unavailable.");
    return;
  }

  try {
    if (button) {
      button.disabled = true;
      button.classList.add("is-busy");
      button.setAttribute("aria-busy", "true");
    }
    setPageSaveStatus("Preparing PDF...");
    if (!await flushPageSave()) return;
    const payload = getActivePagePdfPayload();
    if (!payload) {
      setPageSaveStatus("Save failed");
      toast("No page is open.");
      return;
    }

    setPageSaveStatus("Publishing...");
    const result = await window.pywebview.api.publish_project_page_pdf(payload);
    if (result?.status === "success") {
      setPageSaveStatus("Published");
      toast(`Published ${result.fileName || "page PDF"}.`);
    } else if (result?.status === "cancelled") {
      setPageSaveStatus("Saved");
    } else {
      setPageSaveStatus("Publish failed");
      toast(result?.message || "Could not publish this page as a PDF.");
    }
  } catch (error) {
    console.error("Page PDF publishing failed:", error);
    setPageSaveStatus("Publish failed");
    toast(error?.message || "Could not publish this page as a PDF.");
  } finally {
    if (button) {
      button.disabled = false;
      button.classList.remove("is-busy");
      button.removeAttribute("aria-busy");
    }
  }
}

// --- Inline image sizing/selection ---
function normalizePageImagePercent(value, fallback = PAGE_IMAGE_DEFAULT_PERCENT) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return fallback;
  const stepped =
    Math.round(numeric / PAGE_IMAGE_STEP_PERCENT) * PAGE_IMAGE_STEP_PERCENT;
  return Math.min(
    PAGE_IMAGE_MAX_PERCENT,
    Math.max(PAGE_IMAGE_MIN_PERCENT, stepped)
  );
}
function getPageEditorContentWidth(editor) {
  if (!editor) return 0;
  const styles = window.getComputedStyle(editor);
  const pad =
    (parseFloat(styles.paddingLeft || "0") || 0) +
    (parseFloat(styles.paddingRight || "0") || 0);
  return Math.max(160, editor.clientWidth - pad);
}
function getPageImageWidthPercent(img, editor) {
  if (!img || !editor) return PAGE_IMAGE_DEFAULT_PERCENT;
  const dataPercent = normalizePageImagePercent(img.dataset.widthPercent, NaN);
  if (Number.isFinite(dataPercent)) return dataPercent;
  const raw = String(img.style.width || "").trim();
  if (raw.endsWith("%")) return normalizePageImagePercent(parseFloat(raw));
  const widthPx =
    parseFloat(raw) || img.getBoundingClientRect().width || img.naturalWidth || 0;
  if (!widthPx) return PAGE_IMAGE_DEFAULT_PERCENT;
  const base = getPageEditorContentWidth(editor);
  if (!base) return PAGE_IMAGE_DEFAULT_PERCENT;
  return normalizePageImagePercent((widthPx / base) * 100);
}
function applyPageImageWidth(img, percent, { save: doSave = true } = {}) {
  const editor = getPageEditorEl();
  if (!editor || !img || !editor.contains(img)) return;
  const pct = normalizePageImagePercent(percent);
  const widthPx = Math.max(
    32,
    Math.round((getPageEditorContentWidth(editor) * pct) / 100)
  );
  img.dataset.widthPercent = String(pct);
  img.classList.add("page-inline-image");
  img.style.width = `${widthPx}px`;
  img.style.maxWidth = "100%";
  img.style.height = "auto";
  img.removeAttribute("width");
  img.removeAttribute("height");
  updatePageImageControls();
  if (doSave) queuePageSave();
}
function getActivePageImage(editor) {
  if (!editor || !pageSelectedImage || !editor.contains(pageSelectedImage)) {
    return null;
  }
  return pageSelectedImage;
}
function updatePageImageControls() {
  const editor = getPageEditorEl();
  const controls = document.getElementById("pageImageControls");
  const sizeRange = document.getElementById("pageImageSizeRange");
  const sizeLabel = document.getElementById("pageImageSizeLabel");
  const btns = [
    "pageImageSmallerBtn",
    "pageImageLargerBtn",
    "pageImageResetBtn",
    "pageRemoveImageBtn",
  ].map((id) => document.getElementById(id));
  const activeImage = getActivePageImage(editor);
  const hasImage = !!activeImage;
  if (controls) controls.hidden = !hasImage;
  if (sizeRange) sizeRange.disabled = !hasImage;
  btns.forEach((b) => {
    if (b) b.disabled = !hasImage;
  });
  if (!hasImage) {
    if (sizeLabel) sizeLabel.textContent = "";
    return;
  }
  const pct = getPageImageWidthPercent(activeImage, editor);
  if (sizeRange) sizeRange.value = String(pct);
  if (sizeLabel) sizeLabel.textContent = `${pct}%`;
}
function clearPageSelectedImage() {
  if (pageSelectedImage) pageSelectedImage.classList.remove("is-selected");
  pageSelectedImage = null;
  updatePageImageControls();
}
function setPageSelectedImage(img) {
  const editor = getPageEditorEl();
  if (!editor || !img || !editor.contains(img)) {
    clearPageSelectedImage();
    return;
  }
  if (pageSelectedImage && pageSelectedImage !== img) {
    pageSelectedImage.classList.remove("is-selected");
  }
  pageSelectedImage = img;
  img.classList.add("is-selected");
  updatePageImageControls();
}
function normalizePageInlineImage(img) {
  const editor = getPageEditorEl();
  if (!editor || !img || !editor.contains(img)) return;
  img.classList.add("page-inline-image");
  img.draggable = false;
  if (!img.alt) img.alt = "Image";
  applyPageImageWidth(img, getPageImageWidthPercent(img, editor), { save: false });
}
function normalizePageEditorImages(editor) {
  if (!editor) return;
  editor.querySelectorAll("img").forEach(normalizePageInlineImage);
  if (pageSelectedImage && !editor.contains(pageSelectedImage)) {
    clearPageSelectedImage();
  } else {
    updatePageImageControls();
  }
}
function getPageImageFromSelection(editor) {
  const range = getPageSelectionRange(editor);
  if (!range) return null;
  if (
    range.startContainer === range.endContainer &&
    range.startContainer?.nodeType === Node.ELEMENT_NODE &&
    range.endOffset === range.startOffset + 1
  ) {
    const node = range.startContainer.childNodes[range.startOffset];
    if (node instanceof HTMLImageElement && editor.contains(node)) return node;
  }
  const target =
    range.startContainer?.nodeType === Node.ELEMENT_NODE
      ? range.startContainer
      : range.startContainer?.parentElement;
  return target instanceof HTMLImageElement
    ? target
    : target?.closest?.("img.page-inline-image") || null;
}
function syncPageSelectionState(editor) {
  savePageSelection(editor);
  const img = getPageImageFromSelection(editor);
  if (img) setPageSelectedImage(img);
  else clearPageSelectedImage();
}

// --- Page checklist/todo blocks ---
function createPageChecklistItem({ checked = false, text = "" } = {}) {
  const item = document.createElement("div");
  item.className = "page-checklist-item";
  item.dataset.pageTodo = "true";
  const checkbox = document.createElement("input");
  checkbox.className = "page-checklist-checkbox";
  checkbox.type = "checkbox";
  checkbox.contentEditable = "false";
  checkbox.checked = !!checked;
  if (checkbox.checked) checkbox.setAttribute("checked", "checked");
  const textEl = document.createElement("span");
  textEl.className = "page-checklist-text";
  textEl.contentEditable = "true";
  textEl.spellcheck = true;
  textEl.setAttribute("role", "textbox");
  textEl.setAttribute("aria-label", "Todo text");
  if (String(text || "").trim()) textEl.textContent = text;
  else textEl.appendChild(document.createElement("br"));
  item.append(checkbox, textEl);
  syncPageChecklistItem(item);
  return item;
}

function syncPageChecklistItem(item) {
  if (!item) return;
  const checkbox = item.querySelector?.("input.page-checklist-checkbox");
  if (!checkbox) return;
  checkbox.contentEditable = "false";
  if (checkbox.checked) {
    checkbox.setAttribute("checked", "checked");
    item.dataset.checked = "true";
    item.classList.add("is-complete");
  } else {
    checkbox.removeAttribute("checked");
    item.dataset.checked = "false";
    item.classList.remove("is-complete");
  }
}

function syncPageChecklistItems(root) {
  root?.querySelectorAll?.(".page-checklist-item").forEach(syncPageChecklistItem);
}

function normalizePageChecklistItems(editor) {
  if (!editor) return;
  editor.querySelectorAll(".page-checklist-item").forEach((item) => {
    item.dataset.pageTodo = "true";
    let checkbox = item.querySelector("input.page-checklist-checkbox");
    if (!checkbox) {
      checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.className = "page-checklist-checkbox";
      item.prepend(checkbox);
    }
    checkbox.type = "checkbox";
    checkbox.classList.add("page-checklist-checkbox");
    checkbox.contentEditable = "false";
    checkbox.checked = checkbox.checked || checkbox.hasAttribute("checked") || item.dataset.checked === "true";
    let textEl = item.querySelector(".page-checklist-text");
    if (!textEl) {
      textEl = document.createElement("span");
      textEl.className = "page-checklist-text";
      textEl.innerHTML = item.textContent.trim() ? escapeHtml(item.textContent.trim()) : "<br>";
      item.appendChild(textEl);
    }
    textEl.contentEditable = "true";
    textEl.spellcheck = true;
    textEl.setAttribute("role", "textbox");
    textEl.setAttribute("aria-label", "Todo text");
    syncPageChecklistItem(item);
  });
}

function placePageCaretInChecklistText(textEl) {
  const editor = getPageEditorEl();
  if (!editor || !textEl) return;
  const range = document.createRange();
  range.selectNodeContents(textEl);
  range.collapse(false);
  const sel = window.getSelection?.();
  if (sel) {
    sel.removeAllRanges();
    sel.addRange(range);
  }
  editor.focus();
  savePageSelection(editor);
}

function isPageChecklistTextEmpty(textEl) {
  return !String(textEl?.textContent || "").trim();
}

function isPageSelectionAtChecklistTextEnd(textEl) {
  const selection = window.getSelection?.();
  if (!selection || selection.rangeCount === 0 || !textEl) return false;
  const range = selection.getRangeAt(0);
  if (!range.collapsed || !textEl.contains(range.commonAncestorContainer)) return false;
  const after = range.cloneRange();
  try {
    after.selectNodeContents(textEl);
    after.setStart(range.endContainer, range.endOffset);
    return after.toString().length === 0;
  } catch (_) {
    return false;
  }
}

function replacePageChecklistItemWithParagraph(item) {
  const editor = getPageEditorEl();
  if (!editor || !item || !editor.contains(item)) return;
  const line = document.createElement("div");
  line.appendChild(document.createElement("br"));
  item.replaceWith(line);
  const range = document.createRange();
  range.setStart(line, 0);
  range.collapse(true);
  const selection = window.getSelection?.();
  if (selection) {
    selection.removeAllRanges();
    selection.addRange(range);
  }
  editor.focus();
  savePageSelection(editor);
  queuePageSave();
}

function insertPageTodo() {
  const editor = getPageEditorEl();
  if (!editor) return;
  const range = restorePageSelection(editor) || getPageSelectionRange(editor);
  if (!range) return;
  const block = getPageSlashBlockForRange(range, editor);
  const item = createPageChecklistItem();
  const canReplaceBlock =
    block &&
    block !== editor &&
    editor.contains(block) &&
    !String(block.textContent || "").trim() &&
    !block.querySelector("img");
  if (canReplaceBlock) {
    block.replaceWith(item);
  } else {
    range.deleteContents();
    range.insertNode(item);
  }
  placePageCaretInChecklistText(item.querySelector(".page-checklist-text"));
  queuePageSave();
}

function handlePageChecklistKeydown(event) {
  if (event.key !== "Enter" || event.shiftKey || event.ctrlKey || event.metaKey || event.altKey) {
    return false;
  }
  const textEl = event.target?.closest?.(".page-checklist-text");
  const item = textEl?.closest?.(".page-checklist-item");
  const editor = getPageEditorEl();
  if (!editor || !item || !editor.contains(item)) return false;
  if (isPageChecklistTextEmpty(textEl)) {
    event.preventDefault();
    replacePageChecklistItemWithParagraph(item);
    return true;
  }
  if (!isPageSelectionAtChecklistTextEnd(textEl)) return false;
  event.preventDefault();
  const next = createPageChecklistItem();
  item.insertAdjacentElement("afterend", next);
  placePageCaretInChecklistText(next.querySelector(".page-checklist-text"));
  queuePageSave();
  return true;
}

function handlePageListIndentKeydown(event) {
  if (event.key !== "Tab" || event.ctrlKey || event.metaKey || event.altKey) {
    return false;
  }
  const editor = getPageEditorEl();
  if (!editor) return false;
  const range = getPageSelectionRange(editor);
  if (!range) return false;
  const startNode = range.startContainer;
  const element =
    startNode?.nodeType === Node.ELEMENT_NODE ? startNode : startNode?.parentElement;
  const item = element?.closest?.("li");
  const list = item?.closest?.("ul,ol");
  if (!item || !list || !editor.contains(item) || !editor.contains(list)) {
    return false;
  }
  event.preventDefault();
  try {
    document.execCommand(event.shiftKey ? "outdent" : "indent", false, null);
  } catch (_) {}
  editor.focus();
  savePageSelection(editor);
  queuePageSave();
  return true;
}

// --- Slash commands ---
function getPageSlashMenuEl() {
  return document.getElementById("pageSlashMenu");
}

function getRangeTextBeforeCaret(range, editor) {
  if (!range || !editor) return "";
  const before = range.cloneRange();
  before.selectNodeContents(editor);
  before.setEnd(range.startContainer, range.startOffset);
  return before.toString();
}

function getPageSlashBlockForRange(range, editor) {
  if (!range || !editor) return editor;
  let node = range.startContainer;
  if (node?.nodeType === Node.TEXT_NODE) node = node.parentElement;
  while (node && node !== editor) {
    if (node.nodeType === Node.ELEMENT_NODE && node.matches?.("p,div,h1,h2,h3,li,blockquote,pre")) {
      return node;
    }
    node = node.parentElement;
  }
  return editor;
}

function getRangeTextBeforeCaretInSlashBlock(range, editor) {
  if (!range || !editor) return "";
  const block = getPageSlashBlockForRange(range, editor);
  const before = range.cloneRange();
  try {
    before.selectNodeContents(block || editor);
    before.setEnd(range.startContainer, range.startOffset);
    return before.toString();
  } catch (_) {
    return getRangeTextBeforeCaret(range, editor);
  }
}

function getPageSlashRangeFromCaret(editor, { allowInlineTrigger = false } = {}) {
  const selection = window.getSelection?.();
  if (!editor || !selection || selection.rangeCount === 0) return null;
  const range = selection.getRangeAt(0);
  if (!range.collapsed || !pageNodeInEditor(range.commonAncestorContainer, editor)) return null;
  const textBefore = getRangeTextBeforeCaretInSlashBlock(range, editor);
  const slashIndex = textBefore.lastIndexOf("/");
  if (slashIndex < 0) return null;
  const prefix = textBefore.slice(0, slashIndex);
  const query = textBefore.slice(slashIndex + 1);
  if (/\s/.test(query)) return null;
  if (prefix && !/[\s\n]$/.test(prefix) && !allowInlineTrigger) return null;
  const slashRange = range.cloneRange();
  try {
    slashRange.setStart(range.startContainer, Math.max(0, range.startOffset - query.length - 1));
  } catch (_) {
    return null;
  }
  return { range: slashRange, query };
}

function getPageSlashCommands(query = "") {
  const normalized = String(query || "").trim().toLowerCase();
  return PAGE_SLASH_COMMANDS.filter((command) => {
    if (command.projectOnly && !pageNav.project) return false;
    if (!normalized) return true;
    return command.aliases.some((alias) =>
      String(alias || "").toLowerCase().replace(/\s+/g, "").includes(normalized)
    );
  });
}

function positionPageSlashMenu(menu, range) {
  const fallback = getPageEditorEl()?.getBoundingClientRect();
  let rect = null;
  try {
    rect = range?.getBoundingClientRect?.();
  } catch (_) {}
  const anchor = rect && (rect.width || rect.height) ? rect : fallback;
  if (!menu || !anchor) return;
  const margin = 12;
  const gap = 6;
  const menuWidth = menu.offsetWidth;
  const menuHeight = menu.offsetHeight;
  const left = Math.min(
    window.innerWidth - menuWidth - margin,
    Math.max(margin, anchor.left)
  );
  // Prefer opening below the caret, but flip above when there isn't room so the
  // menu stays fully on screen near the bottom of the viewport.
  const spaceBelow = window.innerHeight - anchor.bottom - gap;
  const spaceAbove = anchor.top - gap;
  let top;
  if (spaceBelow >= menuHeight || spaceBelow >= spaceAbove) {
    top = anchor.bottom + gap;
  } else {
    top = anchor.top - gap - menuHeight;
  }
  // Final clamp keeps the menu within the viewport vertically.
  top = Math.max(margin, Math.min(top, window.innerHeight - menuHeight - margin));
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
}

function closePageSlashMenu() {
  const menu = getPageSlashMenuEl();
  if (menu) {
    menu.hidden = true;
    menu.innerHTML = "";
  }
  pageSlashState = {
    open: false,
    query: "",
    range: null,
    selectedIndex: 0,
    preservedSelection: null,
  };
}

function openPageSlashMenu({ range, query = "", preservedSelection = null } = {}) {
  const menu = getPageSlashMenuEl();
  if (!menu || !range) return;
  pageSlashState.open = true;
  pageSlashState.query = query;
  pageSlashState.range = clonePageRange(range);
  pageSlashState.preservedSelection = clonePageRange(preservedSelection);
  pageSlashState.selectedIndex = 0;
  renderPageSlashMenu();
}

function updatePageSlashMenuFromCaret() {
  const editor = getPageEditorEl();
  if (!editor) return;
  const slash = getPageSlashRangeFromCaret(editor, {
    allowInlineTrigger: pageSlashState.open && !!pageSlashState.preservedSelection,
  });
  if (!slash) {
    if (pageSlashState.open) closePageSlashMenu();
    return;
  }
  if (!pageSlashState.open) pageSlashState.preservedSelection = null;
  pageSlashState.open = true;
  pageSlashState.query = slash.query;
  pageSlashState.range = clonePageRange(slash.range);
  const matches = getPageSlashCommands(slash.query);
  pageSlashState.selectedIndex = Math.min(pageSlashState.selectedIndex, Math.max(0, matches.length - 1));
  renderPageSlashMenu();
}

function getPageSlashCommandShortcut(command) {
  const alias = String(command?.aliases?.[0] || command?.id || "").replace(/\s+/g, "");
  return `/${alias}`;
}

function renderPageSlashMenu() {
  const menu = getPageSlashMenuEl();
  if (!menu || !pageSlashState.open) return;
  const commands = getPageSlashCommands(pageSlashState.query);
  menu.innerHTML = "";
  menu.hidden = false;
  menu.appendChild(
    el("div", { className: "page-slash-menu-header" }, [
      el("span", { className: "page-slash-menu-title", textContent: "Commands" }),
      el("span", {
        className: "page-slash-menu-query",
        textContent: pageSlashState.query ? `/${pageSlashState.query}` : "Type a command",
      }),
    ])
  );
  commands.forEach((command, index) => {
    const item = el("button", {
      className: `page-slash-menu-item ${index === pageSlashState.selectedIndex ? "is-active" : ""}`.trim(),
      type: "button",
      role: "option",
      "aria-selected": String(index === pageSlashState.selectedIndex),
      onclick: (event) => {
        event.preventDefault();
        executePageSlashCommand(command);
      },
    });
    item.append(
      el("span", { className: "page-slash-menu-icon", textContent: command.icon }),
      el("span", {}, [
        el("span", { className: "page-slash-menu-line" }, [
          el("span", { className: "page-slash-menu-label", textContent: command.label }),
          el("span", {
            className: "page-slash-menu-shortcut",
            textContent: getPageSlashCommandShortcut(command),
          }),
        ]),
        el("span", { className: "page-slash-menu-hint", textContent: command.hint }),
      ])
    );
    menu.appendChild(item);
  });
  if (!commands.length) {
    menu.appendChild(el("div", { className: "page-slash-menu-empty", textContent: "No commands found" }));
  }
  const colorCommand = commands.find((command) => command.id === "color");
  if (colorCommand) renderPageSlashColorRow(menu);
  requestAnimationFrame(() => positionPageSlashMenu(menu, pageSlashState.range));
}

function renderPageSlashColorRow(menu) {
  const row = el("div", { className: "page-slash-color-row" });
  PAGE_SLASH_COLORS.forEach((color) => {
    row.appendChild(
      el("button", {
        className: "page-slash-color-swatch",
        type: "button",
        title: color,
        "aria-label": `Text color ${color}`,
        style: `background: ${color};`,
        onclick: (event) => {
          event.preventDefault();
          executePageSlashCommand(PAGE_SLASH_COMMANDS.find((command) => command.id === "color"), { color });
        },
      })
    );
  });
  const custom = el("input", {
    className: "page-slash-color-custom",
    type: "color",
    value: "#2f6fed",
    title: "Custom color",
    "aria-label": "Custom text color",
  });
  custom.addEventListener("input", () => {
    executePageSlashCommand(PAGE_SLASH_COMMANDS.find((command) => command.id === "color"), {
      color: custom.value,
    });
  });
  row.appendChild(custom);
  menu.appendChild(row);
}

function deletePageSlashQuery() {
  const editor = getPageEditorEl();
  if (!editor || !pageSlashState.range) return;
  const range = clonePageRange(pageSlashState.range);
  if (!range) return;
  const selection = window.getSelection?.();
  const block = getPageSlashBlockForRange(range, editor);
  range.deleteContents();
  range.collapse(true);
  // Deleting the whole "/query" can leave the block empty. A truly-empty block
  // can't hold the caret, so a collapsed caret resolves into the PREVIOUS block —
  // which made commands like /h2 reformat the previous line. Anchor the caret with
  // a <br> placeholder so block/list commands apply to the current line.
  if (block && block !== editor && !block.textContent && !block.querySelector("br, img")) {
    block.appendChild(document.createElement("br"));
    range.setStart(block, 0);
    range.collapse(true);
  }
  if (selection) {
    selection.removeAllRanges();
    selection.addRange(range);
  }
  savePageSelection(editor);
}

function executePageSlashCommand(command, options = {}) {
  if (!command) return;
  const editor = getPageEditorEl();
  if (!editor) return;
  const preservedSelection = clonePageRange(pageSlashState.preservedSelection);
  deletePageSlashQuery();
  closePageSlashMenu();
  if (preservedSelection) {
    const selection = window.getSelection?.();
    if (selection) {
      selection.removeAllRanges();
      selection.addRange(preservedSelection);
    }
    savePageSelection(editor);
  }
  if (command.action.type === "block") {
    applyPageBlock(command.action.tag);
  } else if (command.action.type === "command") {
    applyPageCommand(command.action.command);
  } else if (command.action.type === "todo") {
    insertPageTodo();
  } else if (command.action.type === "link") {
    insertPageLink();
  } else if (command.action.type === "color") {
    applyPageTextColor(options.color || PAGE_SLASH_COLORS[0]);
  } else if (command.action.type === "image") {
    openPageImagePicker();
  } else if (command.action.type === "page") {
    createProjectSubpageFromSlash();
  } else if (command.action.type === "pageLink") {
    openPageLinkMenuFromSlash();
  }
}

function createProjectSubpageFromSlash() {
  const { project, subpage } = pageNav;
  if (!project) return;
  const editor = getPageEditorEl();
  if (editor && pageEditorTarget) {
    pageEditorTarget.html = serializePageHtml(editor);
    pageEditorTarget.updatedAt = new Date().toISOString();
  }
  const subpages = getProjectSubpages(project);
  const child = createProjectSubpage({
    title: "Untitled",
    parentId: subpage?.id || null,
    order: subpages.length,
  });
  subpages.push(child);
  void save({ silent: true });
  openProjectPage(project, child);
}

async function deleteProjectSubpage(project, subpage) {
  if (!project || !subpage) return;
  const descendants = getProjectSubpageDescendantIds(project, subpage.id);
  const title = subpage.title || "Untitled";
  if (!confirm(`Move "${title}"${descendants.size ? ` and ${descendants.size} nested pages` : ""} to trash? Attached files will be kept for restoration.`)) return;
  if (!await flushPageSave()) return;
  const removeIds = new Set([subpage.id, ...descendants]);
  const pages = getProjectSubpages(project);
  const removed = pages.filter((page) => removeIds.has(page.id));
  if (!removed.length) return;
  const entry = { id: createId("trash"), title, deletedAt: new Date().toISOString(), pages: removed };
  if (!Array.isArray(project.pageTrash)) project.pageTrash = [];
  project.pageTrash.push(entry);
  const original = [...pages];
  pages.splice(0, pages.length, ...pages.filter((page) => !removeIds.has(page.id)));
  if (!await save({ silent: true })) {
    pages.splice(0, pages.length, ...original);
    project.pageTrash = project.pageTrash.filter((item) => item !== entry);
    toast("Could not move the page to trash. Please try again.");
    return;
  }
  if (pageNav.subpage && removeIds.has(pageNav.subpage.id)) {
    await openProjectPage(project, getProjectSubpageById(project, subpage.parentId));
  } else { render(); if (pageNav.project === project) renderPageView(); }
}

function handlePageSlashBeforeInput(event) {
  const editor = getPageEditorEl();
  if (!editor || event.inputType !== "insertText" || event.data !== "/") return;
  const selection = window.getSelection?.();
  if (!selection || selection.rangeCount === 0) return;
  const range = selection.getRangeAt(0);
  if (!pageNodeInEditor(range.commonAncestorContainer, editor)) return;
  if (!range.collapsed) {
    event.preventDefault();
    const preservedSelection = clonePageRange(range);
    const slashRange = range.cloneRange();
    slashRange.collapse(false);
    const slashNode = document.createTextNode("/");
    slashRange.insertNode(slashNode);
    const queryRange = document.createRange();
    queryRange.setStart(slashNode, 0);
    queryRange.setEnd(slashNode, 1);
    const caretRange = document.createRange();
    caretRange.setStart(slashNode, 1);
    caretRange.collapse(true);
    selection.removeAllRanges();
    selection.addRange(caretRange);
    openPageSlashMenu({ range: queryRange, preservedSelection });
    return;
  }
  const textBefore = getRangeTextBeforeCaretInSlashBlock(range, editor);
  if (textBefore && !/[\s\n]$/.test(textBefore)) return;
  setTimeout(() => updatePageSlashMenuFromCaret(), 0);
}

function handlePageSlashKeydown(event) {
  if (!pageSlashState.open) return false;
  const commands = getPageSlashCommands(pageSlashState.query);
  if (event.key === "Escape") {
    event.preventDefault();
    closePageSlashMenu();
    return true;
  }
  if (event.key === "ArrowDown" || event.key === "ArrowUp") {
    event.preventDefault();
    if (commands.length) {
      const delta = event.key === "ArrowDown" ? 1 : -1;
      pageSlashState.selectedIndex =
        (pageSlashState.selectedIndex + delta + commands.length) % commands.length;
      renderPageSlashMenu();
    }
    return true;
  }
  if (event.key === "Enter" || event.key === "Tab") {
    event.preventDefault();
    executePageSlashCommand(commands[pageSlashState.selectedIndex]);
    return true;
  }
  return false;
}

// --- Image insertion / hydration (files-on-disk via backend) ---
function insertPageImage(dataUrl, assetPath, altText = "Image") {
  const editor = getPageEditorEl();
  if (!editor || !dataUrl) return null;
  const range = restorePageSelection(editor) || getPageSelectionRange(editor);
  if (!range) return null;
  range.deleteContents();
  const img = document.createElement("img");
  img.src = dataUrl;
  if (assetPath) img.dataset.asset = assetPath;
  img.alt = String(altText || "Image").trim() || "Image";
  img.dataset.widthPercent = String(PAGE_IMAGE_DEFAULT_PERCENT);
  range.insertNode(img);
  const spacer = document.createTextNode(" ");
  img.parentNode?.insertBefore(spacer, img.nextSibling);
  placePageCaretAfterNode(editor, spacer);
  normalizePageInlineImage(img);
  setPageSelectedImage(img);
  queuePageSave();
  return img;
}
async function handlePageImageFiles(files) {
  const imageFiles = Array.from(files || []).filter((f) =>
    String(f?.type || "").toLowerCase().startsWith("image/")
  );
  if (!imageFiles.length) return;
  const editor = getPageEditorEl();
  if (!editor) return;
  restorePageSelection(editor);
  let inserted = 0;
  for (const file of imageFiles) {
    try {
      const dataUrl = await readFileAsDataUrl(file);
      const res = await window.pywebview.api.save_page_asset(
        pageEditorOwnerKey,
        dataUrl,
        file.name || ""
      );
      if (!res || res.status !== "success" || !res.assetPath) {
        toast(res?.message || "Could not save image.");
        continue;
      }
      if (insertPageImage(dataUrl, res.assetPath, file.name || "Image")) {
        inserted += 1;
      }
    } catch (e) {
      console.warn("Page image insert failed:", e);
    }
  }
  if (inserted) toast(inserted === 1 ? "Image added." : `Added ${inserted} images.`);
}
function openPageImagePicker() {
  const editor = getPageEditorEl();
  const input = document.getElementById("pageImageInput");
  if (!editor || !input) return;
  savePageSelection(editor);
  input.value = "";
  input.click();
}
function removePageSelectedImage() {
  const editor = getPageEditorEl();
  const img = getActivePageImage(editor);
  if (!editor || !img) return;
  const prev = img.previousSibling;
  img.remove();
  clearPageSelectedImage();
  placePageCaretAfterNode(editor, prev || editor.lastChild);
  queuePageSave();
}
async function hydratePageImages(editor) {
  if (!editor) return;
  const imgs = Array.from(editor.querySelectorAll("img[data-asset]"));
  for (const img of imgs) {
    if (img.getAttribute("src")) continue;
    const assetPath = img.dataset.asset;
    if (!assetPath) continue;
    try {
      const res = await window.pywebview.api.get_page_asset(assetPath);
      if (res && res.status === "success" && res.dataUrl) {
        img.src = res.dataUrl;
      } else {
        img.alt = "Image unavailable";
        img.classList.add("page-image-missing");
      }
    } catch (e) {
      console.warn("Page image hydrate failed:", e);
    }
  }
}
function getPageClipboardImageFiles(clipboardData) {
  if (!clipboardData) return [];
  const files = Array.from(clipboardData.files || []).filter((f) =>
    String(f?.type || "").toLowerCase().startsWith("image/")
  );
  if (files.length) return files;
  return Array.from(clipboardData.items || [])
    .map((i) => i.getAsFile?.())
    .filter((f) => String(f?.type || "").toLowerCase().startsWith("image/"));
}

// --- Legacy tagged item compatibility ---
function flattenLegacyPageItems(editor) {
  if (!editor) return;
  const flatten = (node, textSelector) => {
    const line = document.createElement("div");
    const textEl = node.querySelector(textSelector);
    line.innerHTML = textEl ? textEl.innerHTML : "<br>";
    node.replaceWith(line);
  };
  editor.querySelectorAll(".page-todo").forEach((todo) => {
    flatten(todo, ".page-todo-text");
  });
  editor.querySelectorAll(".page-item").forEach((item) => {
    flatten(item, ".page-item-text");
  });
}

// --- Rich-text commands ---
function applyPageCommand(cmd) {
  const editor = getPageEditorEl();
  if (!editor) return;
  restorePageSelection(editor);
  try {
    document.execCommand(cmd, false, null);
  } catch (_) {}
  editor.focus();
  savePageSelection(editor);
  queuePageSave();
}
function applyPageBlock(tag) {
  const editor = getPageEditorEl();
  if (!editor) return;
  restorePageSelection(editor);
  try {
    document.execCommand("formatBlock", false, tag);
  } catch (_) {}
  editor.focus();
  savePageSelection(editor);
  queuePageSave();
}
function resetPageBlockAfterHeading(event) {
  const editor = getPageEditorEl();
  if (!editor || event.key !== "Enter" || event.shiftKey || event.ctrlKey || event.metaKey || event.altKey) {
    return;
  }
  const selection = window.getSelection?.();
  if (!selection || selection.rangeCount === 0) return;
  const node = selection.getRangeAt(0).startContainer;
  const element = node?.nodeType === Node.ELEMENT_NODE ? node : node?.parentElement;
  const block = element?.closest?.("h1,h2,h3");
  if (!block || !editor.contains(block)) return;
  setTimeout(() => {
    try {
      document.execCommand("formatBlock", false, "p");
    } catch (_) {}
  }, 0);
}
function applyPageTextColor(color) {
  const editor = getPageEditorEl();
  if (!editor) return;
  const value = String(color || "").trim() || "#2f6fed";
  restorePageSelection(editor);
  try {
    document.execCommand("foreColor", false, value);
  } catch (_) {}
  editor.focus();
  savePageSelection(editor);
  queuePageSave();
}
function normalizePageLinkHref(url) {
  const raw = String(url || "").trim();
  if (!raw) return "";
  if (/^(https?:|mailto:|tel:|file:|ftp:)/i.test(raw)) return raw;
  if (/^[\w.+-]+@[\w.-]+\.\w+$/.test(raw)) return `mailto:${raw}`;
  if (/^\/\//.test(raw)) return `https:${raw}`;
  return `https://${raw}`;
}
function insertPageLink() {
  const editor = getPageEditorEl();
  if (!editor) return;
  // Capture the selection BEFORE prompt() steals focus and collapses it.
  savePageSelection(editor);
  const url = window.prompt("Link URL", "https://");
  if (!url || !url.trim() || url.trim() === "https://") return;
  const href = normalizePageLinkHref(url);
  const range = restorePageSelection(editor);
  if (range && !range.collapsed) {
    try {
      document.execCommand("createLink", false, href);
    } catch (_) {}
  } else if (range) {
    // No text selected: insert a new anchor showing the URL.
    const anchor = document.createElement("a");
    anchor.href = href;
    anchor.textContent = url.trim();
    range.deleteContents();
    range.insertNode(anchor);
    placePageCaretAfterNode(editor, anchor);
  }
  // Make links open in the system browser and survive serialization.
  editor.querySelectorAll("a[href]").forEach((a) => {
    a.setAttribute("target", "_blank");
    a.setAttribute("rel", "noopener noreferrer");
  });
  editor.focus();
  savePageSelection(editor);
  queuePageSave();
}

// --- Page links ("[[" picker) ---
function getPageLinkMenuEl() {
  return document.getElementById("pageLinkMenu");
}

// Build the suggestion list for the picker: pages whose title contains the query
// (or all pages when empty), capped for readability, plus a "create" row when the
// typed title doesn't already exist.
function getPageLinkMatches(query = "") {
  const q = String(query || "").trim().toLowerCase();
  const pages = Array.isArray(globalPages) ? globalPages : [];
  const matched = q
    ? pages.filter((page) => String(page.title || "").toLowerCase().includes(q))
    : pages.slice();
  const rows = matched.slice(0, 8).map((page) => ({ type: "page", page }));
  const exists = pages.some(
    (page) => String(page.title || "").trim().toLowerCase() === q
  );
  if (q && !exists) rows.push({ type: "create", title: query.trim() });
  return rows;
}

// Find an open "[[" before the caret in the current block. The returned range spans
// from the first "[" through the caret so deleting it removes the whole "[[query".
function getPageLinkRangeFromCaret(editor) {
  const selection = window.getSelection?.();
  if (!editor || !selection || selection.rangeCount === 0) return null;
  const range = selection.getRangeAt(0);
  if (!range.collapsed || !pageNodeInEditor(range.commonAncestorContainer, editor)) return null;
  const textBefore = getRangeTextBeforeCaretInSlashBlock(range, editor);
  const openIndex = textBefore.lastIndexOf("[[");
  if (openIndex < 0) return null;
  const query = textBefore.slice(openIndex + 2);
  // A closing bracket or newline ends/cancels the link; titles may contain spaces.
  if (/[[\]\n]/.test(query)) return null;
  const linkRange = range.cloneRange();
  try {
    linkRange.setStart(
      range.startContainer,
      Math.max(0, range.startOffset - query.length - 2)
    );
  } catch (_) {
    return null;
  }
  return { range: linkRange, query };
}

function closePageLinkMenu() {
  const menu = getPageLinkMenuEl();
  if (menu) {
    menu.hidden = true;
    menu.innerHTML = "";
  }
  pageLinkState = { open: false, query: "", range: null, selectedIndex: 0 };
}

function openPageLinkMenu({ range, query = "" } = {}) {
  const menu = getPageLinkMenuEl();
  if (!menu || !range) return;
  pageLinkState.open = true;
  pageLinkState.query = query;
  pageLinkState.range = clonePageRange(range);
  pageLinkState.selectedIndex = 0;
  renderPageLinkMenu();
}

// The "/link to page" slash command funnels into the same bracket-anchored flow by
// inserting "[[" at the caret; the editor input handler then opens the picker.
function openPageLinkMenuFromSlash() {
  const editor = getPageEditorEl();
  if (!editor) return;
  // Restore the caret the slash query occupied (the menu button stole focus), then
  // insert "[[" so the input handler opens the picker via the shared bracket flow.
  restorePageSelection(editor);
  document.execCommand("insertText", false, "[[");
  editor.focus();
  updatePageLinkMenuFromCaret();
}

function updatePageLinkMenuFromCaret() {
  const editor = getPageEditorEl();
  if (!editor) return;
  const link = getPageLinkRangeFromCaret(editor);
  if (!link) {
    if (pageLinkState.open) closePageLinkMenu();
    return;
  }
  pageLinkState.open = true;
  pageLinkState.query = link.query;
  pageLinkState.range = clonePageRange(link.range);
  const matches = getPageLinkMatches(link.query);
  pageLinkState.selectedIndex = Math.min(
    pageLinkState.selectedIndex,
    Math.max(0, matches.length - 1)
  );
  renderPageLinkMenu();
}

function renderPageLinkMenu() {
  const menu = getPageLinkMenuEl();
  if (!menu || !pageLinkState.open) return;
  const matches = getPageLinkMatches(pageLinkState.query);
  const q = String(pageLinkState.query || "").trim().toLowerCase();
  menu.innerHTML = "";
  menu.hidden = false;
  menu.appendChild(
    el("div", { className: "page-slash-menu-header" }, [
      el("span", { className: "page-slash-menu-title", textContent: "Link to page" }),
      el("span", {
        className: "page-slash-menu-query",
        textContent: pageLinkState.query ? `[[${pageLinkState.query}` : "Type a page title",
      }),
    ])
  );
  matches.forEach((match, index) => {
    const isActive = index === pageLinkState.selectedIndex;
    const item = el("button", {
      className: `page-slash-menu-item ${match.type === "create" ? "page-link-create" : ""} ${isActive ? "is-active" : ""}`
        .replace(/\s+/g, " ")
        .trim(),
      type: "button",
      role: "option",
      "aria-selected": String(isActive),
      onclick: (event) => {
        event.preventDefault();
        choosePageLinkMatch(match);
      },
    });
    if (match.type === "create") {
      item.append(
        el("span", { className: "page-slash-menu-icon page-link-menu-icon", textContent: "+" }),
        el("span", {}, [
          el("span", { className: "page-slash-menu-line" }, [
            el("span", { className: "page-slash-menu-label", textContent: `Create "${match.title}"` }),
          ]),
          el("span", {
            className: "page-slash-menu-hint",
            textContent: "Add a new page to the Pages tab and link it",
          }),
        ])
      );
    } else {
      const page = match.page;
      const labelEl = el("span", { className: "page-slash-menu-label" });
      labelEl.appendChild(highlightText(page.title || "Untitled", q));
      const previewText = pageHtmlToPlainText(page.page?.html || "");
      item.append(
        el("span", { className: "page-slash-menu-icon page-link-menu-icon", textContent: "[[" }),
        el("span", {}, [
          el("span", { className: "page-slash-menu-line" }, [labelEl]),
          el("span", {
            className: "page-slash-menu-hint",
            textContent: previewText ? previewText.slice(0, 80) : "Empty page",
          }),
        ])
      );
    }
    menu.appendChild(item);
  });
  if (!matches.length) {
    menu.appendChild(
      el("div", { className: "page-slash-menu-empty", textContent: "No pages found" })
    );
  }
  requestAnimationFrame(() => positionPageSlashMenu(menu, pageLinkState.range));
}

function handlePageLinkKeydown(event) {
  if (!pageLinkState.open) return false;
  const matches = getPageLinkMatches(pageLinkState.query);
  if (event.key === "Escape") {
    event.preventDefault();
    closePageLinkMenu();
    return true;
  }
  if (event.key === "ArrowDown" || event.key === "ArrowUp") {
    event.preventDefault();
    if (matches.length) {
      const delta = event.key === "ArrowDown" ? 1 : -1;
      pageLinkState.selectedIndex =
        (pageLinkState.selectedIndex + delta + matches.length) % matches.length;
      renderPageLinkMenu();
    }
    return true;
  }
  if (event.key === "Enter" || event.key === "Tab") {
    event.preventDefault();
    if (matches.length) {
      choosePageLinkMatch(matches[pageLinkState.selectedIndex] || matches[0]);
    } else {
      closePageLinkMenu();
    }
    return true;
  }
  return false;
}

function choosePageLinkMatch(match) {
  if (!match) return;
  if (match.type === "create") {
    createGlobalPageAndLink(match.title);
  } else {
    insertPageWikiLink(match.page);
  }
}

// Remove the "[[query" text so the inserted anchor replaces it. Mirrors
// deletePageSlashQuery, leaving the caret where the brackets started.
function deletePageLinkQuery() {
  const editor = getPageEditorEl();
  if (!editor || !pageLinkState.range) return;
  const range = clonePageRange(pageLinkState.range);
  if (!range) return;
  const selection = window.getSelection?.();
  range.deleteContents();
  range.collapse(true);
  if (selection) {
    selection.removeAllRanges();
    selection.addRange(range);
  }
  savePageSelection(editor);
}

function insertPageWikiLink(page) {
  const editor = getPageEditorEl();
  if (!editor || !page) return;
  deletePageLinkQuery();
  closePageLinkMenu();
  const range = getPageSelectionRange(editor) || restorePageSelection(editor);
  const anchor = document.createElement("a");
  anchor.className = "page-wiki-link";
  anchor.dataset.pageId = page.id;
  anchor.setAttribute("contenteditable", "false");
  anchor.textContent = page.title || "Untitled";
  anchor.title = `Open page: ${page.title || "Untitled"}`;
  // Trailing space gives the caret a stable home after the atomic link token.
  const trailing = document.createTextNode(" ");
  // Insert as one fragment so order is always [anchor][space], regardless of how a
  // browser adjusts a collapsed range across multiple insertNode calls.
  const fragment = document.createDocumentFragment();
  fragment.appendChild(anchor);
  fragment.appendChild(trailing);
  if (range) {
    range.deleteContents();
    range.insertNode(fragment);
  } else {
    editor.appendChild(fragment);
  }
  placePageCaretAfterNode(editor, trailing);
  editor.focus();
  savePageSelection(editor);
  queuePageSave();
}

// "Create" picker option: make a new Pages-tab page, persist it to notes.json, then
// link it in one step.
function createGlobalPageAndLink(title) {
  const page = createGlobalPage({ title: String(title || "").trim() || "Untitled" });
  globalPages.push(page);
  saveGlobalPages({ silent: true });
  try {
    renderGlobalPagesView();
  } catch (_) {}
  insertPageWikiLink(page);
}

// Re-derive each wiki link's visible text from its target page so renames stay in
// sync, and flag links whose target page was deleted. Mirrors hydratePageImages.
function hydratePageWikiLinks(editor) {
  if (!editor) return;
  editor.querySelectorAll("a.page-wiki-link[data-page-id]").forEach((link) => {
    link.setAttribute("contenteditable", "false");
    const page = getGlobalPageById(link.dataset.pageId);
    if (page) {
      link.classList.remove("is-broken");
      link.textContent = page.title || "Untitled";
      link.title = `Open page: ${page.title || "Untitled"}`;
    } else {
      link.classList.add("is-broken");
      link.title = "Page deleted";
    }
  });
}

// --- Navigation state & rendering ---
let pageHeaderPlaceholder = null;
function showPageView() {
  const view = document.getElementById("pageView");
  if (!view) return;
  const header = document.querySelector(".app-header");
  if (header && !view.contains(header)) {
    pageHeaderPlaceholder = document.createComment("Application header home");
    header.before(pageHeaderPlaceholder);
    view.prepend(header);
  }
  const actions = document.getElementById("pageActionsMenu");
  if (actions) actions.open = false;
  view.hidden = false;
  document.body.dataset.pageOpen = "1";
  const editor = getPageEditorEl();
  setTimeout(() => {
    const activeEditor = getPageEditorEl();
    (activeEditor || editor)?.focus?.();
  }, 0);
}
function setPageViewMode(mode) {
  const canvas = mode === "canvas";
  const canvasRoot = document.getElementById("pageCanvasRoot");
  const scroll = document.querySelector("#pageView .page-view-scroll");
  const find = document.getElementById("pageFind");
  const publishBtn = document.getElementById("pagePublishPdfBtn");
  if (canvasRoot) canvasRoot.hidden = !canvas;
  if (scroll) scroll.hidden = canvas;
  if (find) find.hidden = canvas;
  if (publishBtn) publishBtn.hidden = canvas;
  if (canvas && window.ProjectPagesEditor?.unmount) {
    try {
      window.ProjectPagesEditor.unmount();
    } catch (e) {
      console.warn("React page editor unmount failed:", e);
    }
  }
}
let pageNavigationRequest = 0;
async function closePageView() {
  const request = ++pageNavigationRequest;
  if (!await flushPageSave()) return;
  if (request !== pageNavigationRequest) return;
  const header = document.querySelector("#pageView > .app-header");
  if (header && pageHeaderPlaceholder) pageHeaderPlaceholder.replaceWith(header);
  pageHeaderPlaceholder = null;
  if (window.ProjectPagesEditor?.unmount) {
    try {
      window.ProjectPagesEditor.unmount();
    } catch (e) {
      console.warn("React page editor unmount failed:", e);
    }
  }
  resetPageCanvasState();
  setPageViewMode("doc");
  if (pageFindRefreshTimer) {
    clearTimeout(pageFindRefreshTimer);
    pageFindRefreshTimer = null;
  }
  pageFindState.query = "";
  clearPageFindHighlights();
  const view = document.getElementById("pageView");
  if (view) view.hidden = true;
  delete document.body.dataset.pageOpen;
  pageNav = { project: null, subpage: null, globalPage: null };
  pageEditorTarget = null;
  pendingImportantPageScroll = false;
  clearPageSelectedImage();
  try {
    render();
    renderGlobalPagesView();
  } catch (_) {}
}
function pageGoBack() {
  const { project, subpage } = pageNav;
  if (subpage && project) {
    const parent = getProjectSubpageById(project, subpage.parentId);
    void openProjectPage(project, parent);
  } else {
    closePageView();
  }
}
async function openProjectPage(project, subpage = null) {
  if (!project) return;
  const request = ++pageNavigationRequest;
  if (pageEditorTarget && !await flushPageSave()) return;
  if (request !== pageNavigationRequest) return;
  ensurePageViewReady();
  const activeSubpage = subpage
    ? getProjectSubpageById(project, subpage.id || subpage)
    : null;
  pageNav = { project, subpage: activeSubpage, globalPage: null };
  // Show the view first so the editor is laid out before renderPageView() sizes
  // inline images against the editor's content width.
  showPageView();
  renderPageView();
}
async function openGlobalPage(globalPage) {
  if (!globalPage) return;
  const request = ++pageNavigationRequest;
  if (pageEditorTarget && !await flushPageSave()) return;
  if (request !== pageNavigationRequest) return;
  ensurePageViewReady();
  pageNav = { project: null, subpage: null, globalPage };
  activeGlobalPageId = globalPage.id;
  // Show the view first so the editor is laid out before renderPageView() sizes
  // inline images against the editor's content width.
  showPageView();
  renderPageView();
}
function getProjectPagesEditorChildren(project, activeSubpage = null) {
  if (!project) return [];
  const groups = getProjectSubpagesByParent(project);
  const parentKey = activeSubpage?.id || "";
  return (groups.get(parentKey) || []).map((child) => ({
    id: child.id,
    title: child.title || "Untitled",
    childCount: (groups.get(child.id) || []).length,
  }));
}
function handleProjectPagesEditorTitleChange(value) {
  const title = String(value || "").trim();
  const { project, subpage, globalPage } = pageNav;
  if (globalPage) globalPage.title = title || "Untitled";
  else if (subpage) subpage.title = title || "Untitled";
  else if (project) project.name = title;
  queuePageMiscSave();
  renderPageBreadcrumb(project, subpage);
}
async function persistProjectPagesEditorNow() {
  return flushPageSave();
}

function createProjectSubpageFromEditor(kind = "") {
  const { project, subpage } = pageNav;
  if (!project) return;
  flushPageSave().then((ok) => {
    if (!ok) return;
    const subpages = getProjectSubpages(project);
    const child = createProjectSubpage({
      title: "Untitled",
      parentId: subpage?.id || null,
      kind: kind === "canvas" ? "canvas" : "",
      order: subpages.length,
    });
    subpages.push(child);
    void save({ silent: true });
    openProjectPage(project, child);
  });
}
function createGlobalPageFromEditor(title) {
  const page = createGlobalPage({ title: String(title || "").trim() || "Untitled" });
  globalPages.push(page);
  saveGlobalPages({ silent: true });
  try {
    renderGlobalPagesView();
  } catch (_) {}
  return { id: page.id, title: page.title };
}
function setProjectPagesEditorDocument(context) {
  const root = prepareProjectPagesEditorMount();
  if (!root || !isProjectPagesEditorAvailable()) return false;
  const ownerKey = pageEditorOwnerKey;
  window.ProjectPagesEditor.mount(root, {});
  window.ProjectPagesEditor.setDocument({
    ...context,
    trashEntries: (context.project ? context.project.pageTrash || [] : globalPageTrash).map((entry) => ({
      id: entry.id, title: entry.title, count: entry.pages.length, deletedAt: entry.deletedAt,
    })),
    onRestoreTrash: (id) => restoreNotesTrash(context.project || null, id),
    navigationPages: context.project ? (() => {
      const groups = getProjectSubpagesByParent(context.project);
      const pages = [];
      const visited = new Set();
      const visit = (parentId, depth) => {
        (groups.get(parentId) || []).forEach((page) => {
          if (visited.has(page.id)) return;
          visited.add(page.id);
          pages.push({ id: page.id, title: page.title || "Untitled", depth,
            canvas: isCanvasPage(page.page) });
          visit(page.id, depth + 1);
        });
      };
      visit("", 0);
      return pages;
    })() : [],
    onOpenOverview: () => openProjectPage(pageNav.project),
    globalPages: (Array.isArray(globalPages) ? globalPages : []).map((page) => ({
      id: page.id,
      title: page.title || "Untitled",
    })),
    onHtmlChange: (html, options = {}) => {
      queueProjectPagesEditorSave(html, { persist: options.immediate !== true });
      if (options.immediate === true) return true;
      return true;
    },
    onTitleChange: handleProjectPagesEditorTitleChange,
    onRequestPersist: persistProjectPagesEditorNow,
    onCreateSubpage: createProjectSubpageFromEditor,
    onOpenSubpage: (subpageId) => {
      const child = getProjectSubpageById(pageNav.project, subpageId);
      if (child) openProjectPage(pageNav.project, child);
    },
    onDeleteSubpage: (subpageId) => {
      const child = getProjectSubpageById(pageNav.project, subpageId);
      if (child) deleteProjectSubpage(pageNav.project, child);
    },
    onOpenGlobalPage: (pageId) => {
      const target = getGlobalPageById(pageId);
      if (target) openGlobalPage(target);
    },
    onCreateGlobalPage: createGlobalPageFromEditor,
    onSaveAsset: (dataUrl, filename) =>
      window.pywebview.api.save_page_asset(ownerKey, dataUrl, filename || ""),
    onGetAsset: (assetPath) => window.pywebview.api.get_page_asset(assetPath),
    onCreateWorkbook: (name) =>
      window.pywebview.api.create_page_workbook(ownerKey, name || ""),
    onLinkWorkbook: (path) => window.pywebview.api.link_page_workbook(path || ""),
    onChooseWorkbookFile: () =>
      window.pywebview.api.select_files({
        allow_multiple: false,
        file_types: ["Excel Files (*.xlsx;*.xlsm;*.xls;*.xlsb;*.csv)"],
      }),
    onAttachEmailDrop: (event) => resolvePageEmailDropRef(event, buildPageEmailDropContext()),
    onPickEmail: () => requestPageEmailRef(buildPageEmailDropContext()),
    onOpenEmail: (attrs) => openPageEmailRef(attrs),
    onOpenAttachment: (attrs) => openAttachmentEntry(attrs),
    onPickAttachment: async () => {
      const result = await window.pywebview.api.select_files({ allow_multiple: true, file_types: ["All files (*.*)"] });
      return (result?.paths || []).map((target) => ({ type: "path", target, description: String(target).split(/[\\/]/).pop() || target }));
    },
    onDeleteEmail: (attrs) => deletePageEmailRef(attrs),
    onGetPageFileInfo: (fileRef) => window.pywebview.api.get_page_file_info(fileRef),
    onOpenPageFile: (fileRef) => window.pywebview.api.open_page_file(fileRef),
    onDeletePageFile: (fileRef) => window.pywebview.api.delete_page_file(fileRef),
    onToast: (message) => toast(message),
  });
  return true;
}
function renderPageView() {
  const { project, subpage, globalPage } = pageNav;
  const editor = getPageEditorEl();
  const titleEl = document.getElementById("pageTitle");
  const childLinksEl = document.getElementById("pageChildLinks");
  const deleteProjectBtn = document.getElementById("pageDeleteProjectBtn");
  if (deleteProjectBtn) {
    deleteProjectBtn.style.display =
      project && !subpage && !globalPage ? "inline-flex" : "none";
  }

  if (globalPage) {
    if (!globalPage.page || typeof globalPage.page !== "object") {
      globalPage.page = { html: "", updatedAt: "" };
    }
    pageEditorTarget = globalPage.page;
    pageEditorOwnerKey = `page_global_${globalPage.id || "x"}`;
    renderPageBreadcrumb(null, null);
    if (isCanvasPage(pageEditorTarget)) {
      setPageViewMode("canvas");
      renderPageCanvasView();
      setPageSaveStatus("");
      return;
    }
    setPageViewMode("doc");
    if (
      setProjectPagesEditorDocument({
        documentKey: `global:${globalPage.id || "x"}`,
        kind: "global",
        globalPage,
        html: normalizeHtmlForProjectPagesEditor(globalPage.page.html || ""),
        title: globalPage.title || "",
      })
    ) {
      setPageSaveStatus("");
      applyPageFindHighlights({ preserveIndex: false, scroll: false });
      return;
    }
    if (titleEl) titleEl.textContent = globalPage.title || "";
    if (childLinksEl) {
      childLinksEl.hidden = true;
      childLinksEl.innerHTML = "";
    }
    clearPageSelectedImage();
    if (editor) {
      editor.innerHTML = globalPage.page.html || "";
      flattenLegacyPageItems(editor);
      normalizePageChecklistItems(editor);
      normalizePageEditorImages(editor);
      hydratePageImages(editor);
      hydratePageWikiLinks(editor);
    }
    setPageSaveStatus("");
    applyPageFindHighlights({ preserveIndex: false, scroll: false });
    return;
  }

  if (!project) return;
  // Consume the one-shot here so no exit path below can leave it set for an
  // unrelated page open.
  const focusImportant = pendingImportantPageScroll;
  pendingImportantPageScroll = false;
  getProjectSubpages(project);
  const activeSubpage = subpage ? getProjectSubpageById(project, subpage.id) : null;
  pageNav.subpage = activeSubpage;
  const target = activeSubpage || project;
  if (!target.page || typeof target.page !== "object") {
    target.page = { html: "", updatedAt: "" };
  }
  pageEditorTarget = target.page;
  pageEditorOwnerKey = activeSubpage
    ? `proj_${project.id || "x"}_subpage_${activeSubpage.id || "x"}`
    : `proj_${project.id || "x"}`;

  renderPageBreadcrumb(project, activeSubpage);

  if (isCanvasPage(pageEditorTarget)) {
    setPageViewMode("canvas");
    renderPageCanvasView();
    setPageSaveStatus("");
    return;
  }
  setPageViewMode("doc");

  if (
    setProjectPagesEditorDocument({
      documentKey: activeSubpage
        ? `project:${project.id || "x"}:subpage:${activeSubpage.id || "x"}`
        : `project:${project.id || "x"}:root`,
      kind: activeSubpage ? "subpage" : "project",
      project,
      subpage: activeSubpage,
      html: normalizeHtmlForProjectPagesEditor(target.page.html || ""),
      title: (activeSubpage ? activeSubpage.title : project.name) || "",
      childPages: getProjectPagesEditorChildren(project, activeSubpage),
      focusImportant,
    })
  ) {
    setPageSaveStatus("");
    applyPageFindHighlights({ preserveIndex: false, scroll: false });
    return;
  }

  if (titleEl) {
    titleEl.textContent = (activeSubpage ? activeSubpage.title : project.name) || "";
  }

  clearPageSelectedImage();
  if (editor) {
    editor.innerHTML = target.page.html || "";
    flattenLegacyPageItems(editor);
    normalizePageChecklistItems(editor);
    normalizePageEditorImages(editor);
    hydratePageImages(editor);
    hydratePageWikiLinks(editor);
  }

  renderPageChildLinks(project, activeSubpage);

  setPageSaveStatus("");
  applyPageFindHighlights({ preserveIndex: false, scroll: false });
}
function renderPageBreadcrumb(project, subpage) {
  const nav = document.getElementById("pageBreadcrumb");
  if (!nav) return;
  nav.innerHTML = "";
  const addCrumb = (label, onClick, isCurrent) => {
    const el = document.createElement(onClick ? "button" : "span");
    el.className = "page-crumb" + (isCurrent ? " is-current" : "");
    el.textContent = label || "Untitled";
    if (onClick) {
      el.type = "button";
      el.addEventListener("click", onClick);
    }
    nav.appendChild(el);
  };
  const addSep = () => {
    const s = document.createElement("span");
    s.className = "page-crumb-sep";
    s.textContent = "/";
    nav.appendChild(s);
  };
  if (pageNav.globalPage) {
    addCrumb("Pages", () => closePageView(), false);
    addSep();
    addCrumb(pageNav.globalPage.title || "Untitled", null, true);
    return;
  }
  addCrumb("Projects", () => closePageView(), false);
  addSep();
  if (subpage) {
    addCrumb(project.name || project.id || "Project", () => openProjectPage(project), false);
    getProjectSubpageAncestors(project, subpage).forEach((ancestor) => {
      addSep();
      addCrumb(ancestor.title || "Untitled", () => openProjectPage(project, ancestor), false);
    });
    addSep();
    addCrumb(subpage.title || "Untitled", null, true);
  } else {
    addCrumb(project.name || project.id || "Project", null, false);
    addSep();
    addCrumb("Overview", null, true);
  }
}
function queuePageMiscSave() {
  pagePersistence.dirty();
}

function compareProjectSubpageOrder(a, b) {
  const orderA = Number.isFinite(Number(a?.order)) ? Number(a.order) : 0;
  const orderB = Number.isFinite(Number(b?.order)) ? Number(b.order) : 0;
  if (orderA !== orderB) return orderA - orderB;
  return String(a?.title || "").localeCompare(String(b?.title || ""));
}

function getProjectSubpagesByParent(project) {
  const groups = new Map();
  getProjectSubpages(project).forEach((subpage) => {
    const key = subpage.parentId || "";
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(subpage);
  });
  groups.forEach((items) => items.sort(compareProjectSubpageOrder));
  return groups;
}

function renderPageChildLinks(project, activeSubpage = null) {
  const container = document.getElementById("pageChildLinks");
  if (!container) return;
  if (getProjectPagesEditorRoot()?.contains(container)) return;
  container.innerHTML = "";
  if (!project) {
    container.hidden = true;
    return;
  }
  const groups = getProjectSubpagesByParent(project);
  const parentKey = activeSubpage?.id || "";
  const children = groups.get(parentKey) || [];
  container.hidden = false;
  container.appendChild(el("div", { className: "page-child-links-label", textContent: "Subpages" }));
  children.forEach((child) => {
    const childCount = (groups.get(child.id) || []).length;
    const row = el("button", {
      className: "page-child-link",
      type: "button",
      title: child.title || "Untitled",
      onclick: () => openProjectPage(project, child),
    });
    const del = createTabDeleteIcon("Delete subpage", (e) => {
      e.stopPropagation();
      deleteProjectSubpage(project, child);
    });
    row.append(
      el("span", { className: "page-child-link-icon", textContent: "Pg" }),
      el("span", { className: "page-child-link-title", textContent: child.title || "Untitled" }),
      el("span", {
        className: "page-child-link-meta",
        textContent: childCount ? `${childCount} subpage${childCount === 1 ? "" : "s"}` : "",
      }),
      del
    );
    container.appendChild(row);
  });
  const addBtn = el("button", {
    className: "page-child-link page-child-link-add",
    type: "button",
    textContent: "+ Add subpage",
    onclick: () => createProjectSubpageFromSlash(),
  });
  container.appendChild(addBtn);
}

function queuePageTitleSave() {
  const titleEl = document.getElementById("pageTitle");
  if (!titleEl) return;
  const value = (titleEl.textContent || "").trim();
  const { project, subpage, globalPage } = pageNav;
  if (globalPage) globalPage.title = value;
  else if (subpage) subpage.title = value || "Untitled";
  else if (project) project.name = value;
  queuePageMiscSave();
}

function ensurePageViewReady() {
  if (pageViewInitialized) return;
  const view = document.getElementById("pageView");
  const editor = getPageEditorEl();
  const reactPageEditorEnabled = !!getProjectPagesEditorRoot();
  if (!view || (!editor && !reactPageEditorEnabled)) return;
  pageViewInitialized = true;

  if (editor) {
    editor.addEventListener("beforeinput", handlePageSlashBeforeInput);
    editor.addEventListener("input", () => {
      normalizePageEditorImages(editor);
      updatePageSlashMenuFromCaret();
      updatePageLinkMenuFromCaret();
      queuePageSave();
      queuePageFindRefresh();
    });
    editor.addEventListener("change", (e) => {
      const checkbox = e.target?.closest?.("input.page-checklist-checkbox");
      if (!checkbox || !editor.contains(checkbox)) return;
      syncPageChecklistItem(checkbox.closest(".page-checklist-item"));
      queuePageSave();
    });
    editor.addEventListener("keydown", (e) => {
      if (handlePageLinkKeydown(e)) return;
      if (handlePageSlashKeydown(e)) return;
      if (handlePageListIndentKeydown(e)) return;
      if (handlePageChecklistKeydown(e)) return;
      resetPageBlockAfterHeading(e);
    });
    editor.addEventListener("keyup", () => syncPageSelectionState(editor));
    editor.addEventListener("mouseup", () => syncPageSelectionState(editor));
    editor.addEventListener("blur", () => savePageSelection(editor));
    editor.addEventListener("click", (e) => {
      const wiki = e.target?.closest?.("a.page-wiki-link[data-page-id]");
      if (wiki) {
        e.preventDefault();
        const target = getGlobalPageById(wiki.dataset.pageId);
        if (target) openGlobalPage(target);
        return;
      }
      const link = e.target?.closest?.("a[href]");
      if (link && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        openExternalUrl(link.getAttribute("href"));
        return;
      }
      const img = e.target?.closest?.("img.page-inline-image");
      if (img) setPageSelectedImage(img);
      else clearPageSelectedImage();
    });
    editor.addEventListener("dblclick", (e) => {
      const img = e.target?.closest?.("img.page-inline-image");
      if (img && img.src) {
        openImagePreviewDialog({
          dataUrl: img.src,
          filename: img.alt || "Image",
          width: img.naturalWidth || 1,
          height: img.naturalHeight || 1,
        });
      }
    });
    editor.addEventListener("paste", (e) => {
      const files = getPageClipboardImageFiles(e.clipboardData);
      if (files.length) {
        e.preventDefault();
        handlePageImageFiles(files);
      }
    });
    editor.addEventListener("dragover", (e) => {
      if (Array.from(e.dataTransfer?.types || []).includes("Files")) e.preventDefault();
    });
    editor.addEventListener("drop", (e) => {
      const files = Array.from(e.dataTransfer?.files || []).filter((f) =>
        String(f.type || "").toLowerCase().startsWith("image/")
      );
      if (files.length) {
        e.preventDefault();
        movePageCaretToPoint(editor, e.clientX, e.clientY);
        handlePageImageFiles(files);
      }
    });
  }

  const titleEl = document.getElementById("pageTitle");
  if (titleEl) {
    titleEl.addEventListener("input", () => {
      queuePageTitleSave();
      queuePageFindRefresh();
    });
    titleEl.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        editor.focus();
      }
    });
  }

  document.getElementById("pageImageInput")?.addEventListener("change", (e) => {
    const files = e.target.files;
    if (files && files.length) handlePageImageFiles(files);
    e.target.value = "";
  });
  document.getElementById("pageImageSmallerBtn")?.addEventListener("click", () => {
    const img = getActivePageImage(editor);
    if (img) applyPageImageWidth(img, getPageImageWidthPercent(img, editor) - PAGE_IMAGE_STEP_PERCENT);
  });
  document.getElementById("pageImageLargerBtn")?.addEventListener("click", () => {
    const img = getActivePageImage(editor);
    if (img) applyPageImageWidth(img, getPageImageWidthPercent(img, editor) + PAGE_IMAGE_STEP_PERCENT);
  });
  document.getElementById("pageImageResetBtn")?.addEventListener("click", () => {
    const img = getActivePageImage(editor);
    if (img) applyPageImageWidth(img, PAGE_IMAGE_DEFAULT_PERCENT);
  });
  document.getElementById("pageImageSizeRange")?.addEventListener("input", (e) => {
    const img = getActivePageImage(editor);
    if (img) applyPageImageWidth(img, e.target.value);
  });
  document.getElementById("pageRemoveImageBtn")?.addEventListener("click", removePageSelectedImage);

  document.getElementById("pageFindInput")?.addEventListener("input", handlePageFindInput);
  document.getElementById("pageFindInput")?.addEventListener("keydown", handlePageFindKeydown);
  document.getElementById("pageFindPrevBtn")?.addEventListener("click", () => stepPageFindMatch(-1));
  document.getElementById("pageFindNextBtn")?.addEventListener("click", () => stepPageFindMatch(1));

  document.getElementById("pageViewBackBtn")?.addEventListener("click", pageGoBack);
  document.getElementById("pagePublishPdfBtn")?.addEventListener("click", publishActivePagePdf);
  document.getElementById("pageViewCloseBtn")?.addEventListener("click", () => closePageView());
  const actionsMenu = document.getElementById("pageActionsMenu");
  document.addEventListener("click", (event) => {
    if (actionsMenu?.open && !actionsMenu.contains(event.target)) actionsMenu.open = false;
  });
  actionsMenu?.addEventListener("click", (event) => {
    if (event.target.closest("button")) actionsMenu.open = false;
  });
  const toolbar = view.querySelector(".page-view-topbar");
  if (toolbar && typeof ResizeObserver !== "undefined") {
    const header = document.querySelector(".app-header");
    const observer = new ResizeObserver(() => {
      view.style.setProperty("--notes-toolbar-height", `${toolbar.offsetHeight}px`);
      if (header) document.documentElement.style.setProperty("--header-height", `${header.offsetHeight}px`);
    });
    observer.observe(toolbar);
    if (header) observer.observe(header);
  }

  view.addEventListener("keydown", (e) => {
    if ((e.ctrlKey || e.metaKey) && String(e.key || "").toLowerCase() === "f") {
      e.preventDefault();
      focusPageFindInput();
      return;
    }
    if (e.key === "Escape") {
      if (actionsMenu?.open) {
        actionsMenu.open = false;
        actionsMenu.querySelector("summary")?.focus();
        e.preventDefault();
        return;
      }
      e.preventDefault();
      pageGoBack();
    }
  });
}

// ===================== Canvas pages (mind-map canvas) =====================
const PAGE_CANVAS_MIN_SCALE = 0.2;
const PAGE_CANVAS_MAX_SCALE = 2.5;
const PAGE_CANVAS_DRAG_THRESHOLD_PX = 3;
let pageCanvasInitialized = false;
let pageCanvasState = {
  selection: { nodes: [], edges: [] }, // id arrays, selection order preserved
  editingNodeId: null,
  pointer: null, // active gesture: { mode: "pan" | "marquee" | "node" | "resize" | "edge", ... }
  spaceDown: false,
};
let canvasContextMenu = null;
let canvasContextMenuHandlersReady = false;

function getPageCanvasData() {
  return isCanvasPage(pageEditorTarget) ? pageEditorTarget.canvas : null;
}
function getPageCanvasViewportEl() {
  return document.getElementById("pageCanvasViewport");
}
function getPageCanvasNodesEl() {
  return document.getElementById("pageCanvasNodes");
}
function getPageCanvasNodeEl(nodeId) {
  return getPageCanvasNodesEl()?.querySelector(
    `.page-canvas-node[data-node-id="${CSS.escape(String(nodeId))}"]`
  );
}
function getPageCanvasEdgeGroupEl(edgeId) {
  return document
    .getElementById("pageCanvasEdgePaths")
    ?.querySelector(`.page-canvas-edge-group[data-edge-id="${CSS.escape(String(edgeId))}"]`);
}
function getPageCanvasMarqueeEl() {
  return document.getElementById("pageCanvasMarquee");
}

function resetPageCanvasState() {
  pageCanvasState = {
    selection: { nodes: [], edges: [] },
    editingNodeId: null,
    pointer: null,
    spaceDown: false,
  };
  const draft = document.getElementById("pageCanvasEdgeDraft");
  if (draft) draft.hidden = true;
  const marquee = getPageCanvasMarqueeEl();
  if (marquee) marquee.hidden = true;
  hideCanvasContextMenu();
}

function queuePageCanvasSave() {
  if (!pageEditorTarget) return;
  pageEditorTarget.updatedAt = new Date().toISOString();
  pagePersistence.dirty();
}

function getCanvasWorldPoint(e) {
  const viewport = getPageCanvasViewportEl();
  const canvas = getPageCanvasData();
  if (!viewport || !canvas) return { x: 0, y: 0 };
  const rect = viewport.getBoundingClientRect();
  const view = canvas.view;
  return {
    x: (e.clientX - rect.left - view.x) / view.scale,
    y: (e.clientY - rect.top - view.y) / view.scale,
  };
}
function getCanvasViewportCenterWorldPoint() {
  const viewport = getPageCanvasViewportEl();
  const canvas = getPageCanvasData();
  if (!viewport || !canvas) return { x: 0, y: 0 };
  const rect = viewport.getBoundingClientRect();
  const view = canvas.view;
  return {
    x: (rect.width / 2 - view.x) / view.scale,
    y: (rect.height / 2 - view.y) / view.scale,
  };
}

function updateCanvasViewTransform() {
  const canvas = getPageCanvasData();
  const world = document.getElementById("pageCanvasWorld");
  if (!canvas || !world) return;
  const { x, y, scale } = canvas.view;
  world.style.transform = `translate(${x}px, ${y}px) scale(${scale})`;
  const label = document.getElementById("pageCanvasZoomLabel");
  if (label) label.textContent = `${Math.round(scale * 100)}%`;
}

function updateCanvasEmptyHint() {
  const canvas = getPageCanvasData();
  const hint = document.getElementById("pageCanvasEmptyHint");
  if (hint) hint.hidden = !canvas || canvas.nodes.length > 0;
}

function getCanvasNodeById(nodeId) {
  const canvas = getPageCanvasData();
  return canvas?.nodes.find((node) => node.id === nodeId) || null;
}

function getCanvasNodeRect(node) {
  const el = getPageCanvasNodeEl(node.id);
  return {
    x: node.x,
    y: node.y,
    w: el?.offsetWidth || node.w || 200,
    h: el?.offsetHeight || node.h || 60,
  };
}

function computeCanvasEdgePathBetween(rectA, rectB) {
  const ca = { x: rectA.x + rectA.w / 2, y: rectA.y + rectA.h / 2 };
  const cb = { x: rectB.x + rectB.w / 2, y: rectB.y + rectB.h / 2 };
  const dx = cb.x - ca.x;
  const dy = cb.y - ca.y;
  let p1;
  let p2;
  let c1;
  let c2;
  if (Math.abs(dx) >= Math.abs(dy)) {
    const sign = dx >= 0 ? 1 : -1;
    p1 = { x: sign > 0 ? rectA.x + rectA.w : rectA.x, y: ca.y };
    p2 = { x: sign > 0 ? rectB.x : rectB.x + rectB.w, y: cb.y };
    const bend = Math.max(40, Math.abs(p2.x - p1.x) / 2);
    c1 = { x: p1.x + sign * bend, y: p1.y };
    c2 = { x: p2.x - sign * bend, y: p2.y };
  } else {
    const sign = dy >= 0 ? 1 : -1;
    p1 = { x: ca.x, y: sign > 0 ? rectA.y + rectA.h : rectA.y };
    p2 = { x: cb.x, y: sign > 0 ? rectB.y : rectB.y + rectB.h };
    const bend = Math.max(40, Math.abs(p2.y - p1.y) / 2);
    c1 = { x: p1.x, y: p1.y + sign * bend };
    c2 = { x: p2.x, y: p2.y - sign * bend };
  }
  return `M ${p1.x} ${p1.y} C ${c1.x} ${c1.y}, ${c2.x} ${c2.y}, ${p2.x} ${p2.y}`;
}

function updateCanvasEdgePath(edge) {
  const from = getCanvasNodeById(edge.from);
  const to = getCanvasNodeById(edge.to);
  const group = getPageCanvasEdgeGroupEl(edge.id);
  if (!from || !to || !group) return;
  const d = computeCanvasEdgePathBetween(getCanvasNodeRect(from), getCanvasNodeRect(to));
  group.querySelectorAll("path").forEach((path) => path.setAttribute("d", d));
}

function updateCanvasEdgesForNode(nodeId) {
  const canvas = getPageCanvasData();
  if (!canvas) return;
  canvas.edges.forEach((edge) => {
    if (edge.from === nodeId || edge.to === nodeId) updateCanvasEdgePath(edge);
  });
}

function renderCanvasEdges() {
  const canvas = getPageCanvasData();
  const container = document.getElementById("pageCanvasEdgePaths");
  if (!canvas || !container) return;
  container.innerHTML = "";
  canvas.edges.forEach((edge) => {
    const group = document.createElementNS("http://www.w3.org/2000/svg", "g");
    group.classList.add("page-canvas-edge-group");
    group.dataset.edgeId = edge.id;
    if (isCanvasEdgeSelected(edge.id)) {
      group.classList.add("is-selected");
    }
    const hit = document.createElementNS("http://www.w3.org/2000/svg", "path");
    hit.classList.add("page-canvas-edge-hit");
    const visible = document.createElementNS("http://www.w3.org/2000/svg", "path");
    visible.classList.add("page-canvas-edge");
    visible.setAttribute("marker-end", "url(#pageCanvasArrowHead)");
    group.appendChild(hit);
    group.appendChild(visible);
    container.appendChild(group);
    updateCanvasEdgePath(edge);
  });
}

function hydrateCanvasImageNode(node, imgEl) {
  if (!node.assetPath || !window.pywebview?.api?.get_page_asset) return;
  window.pywebview.api
    .get_page_asset(node.assetPath)
    .then((res) => {
      if (res?.dataUrl) imgEl.src = res.dataUrl;
    })
    .catch(() => {});
}

function isCanvasNodeAutoWidth(node) {
  return node.type === "text" && node.autoW !== false;
}

function applyCanvasNodeWidth(node, el) {
  if (!el) return;
  if (isCanvasNodeAutoWidth(node)) {
    el.classList.add("is-auto-width");
    el.style.width = "";
  } else {
    el.classList.remove("is-auto-width");
    el.style.width = `${node.w}px`;
  }
}

function renderCanvasNode(node) {
  const el = document.createElement("div");
  el.className = "page-canvas-node";
  el.dataset.nodeId = node.id;
  el.style.left = `${node.x}px`;
  el.style.top = `${node.y}px`;
  applyCanvasNodeWidth(node, el);
  if (node.type === "image") {
    el.style.height = `${node.h}px`;
    const img = document.createElement("img");
    img.className = "page-canvas-node-img";
    img.alt = "";
    img.draggable = false;
    hydrateCanvasImageNode(node, img);
    el.appendChild(img);
  } else {
    const text = document.createElement("div");
    text.className = "page-canvas-node-text";
    text.spellcheck = true;
    text.textContent = node.text || "";
    el.appendChild(text);
  }
  const connector = document.createElement("div");
  connector.className = "page-canvas-node-connector";
  connector.title = "Drag to another item to connect";
  el.appendChild(connector);
  const handle = document.createElement("div");
  handle.className = "page-canvas-node-handle";
  handle.title = "Drag to resize";
  el.appendChild(handle);
  if (isCanvasNodeSelected(node.id)) {
    el.classList.add("is-selected");
  }
  return el;
}

function renderCanvasNodes() {
  const canvas = getPageCanvasData();
  const container = getPageCanvasNodesEl();
  if (!canvas || !container) return;
  container.innerHTML = "";
  canvas.nodes.forEach((node) => container.appendChild(renderCanvasNode(node)));
  updateCanvasEmptyHint();
}

function getCanvasSelection() {
  const selection = pageCanvasState.selection;
  if (!selection || !Array.isArray(selection.nodes) || !Array.isArray(selection.edges)) {
    pageCanvasState.selection = { nodes: [], edges: [] };
  }
  return pageCanvasState.selection;
}
function getSelectedCanvasNodeIds() {
  return getCanvasSelection().nodes;
}
function getSelectedCanvasNodes() {
  return getSelectedCanvasNodeIds()
    .map((id) => getCanvasNodeById(id))
    .filter(Boolean);
}
function getSelectedCanvasImageNodes() {
  return getSelectedCanvasNodes().filter((node) => node.type === "image" && node.assetPath);
}
function getSelectedCanvasTextNodes() {
  return getSelectedCanvasNodes().filter((node) => node.type === "text");
}
function isCanvasNodeSelected(nodeId) {
  return getCanvasSelection().nodes.includes(nodeId);
}
function isCanvasEdgeSelected(edgeId) {
  return getCanvasSelection().edges.includes(edgeId);
}
function hasCanvasSelection() {
  const selection = getCanvasSelection();
  return selection.nodes.length > 0 || selection.edges.length > 0;
}

function refreshCanvasSelectionClasses() {
  const selection = getCanvasSelection();
  getPageCanvasNodesEl()
    ?.querySelectorAll(".page-canvas-node")
    .forEach((el) => {
      el.classList.toggle("is-selected", selection.nodes.includes(el.dataset.nodeId));
    });
  document
    .getElementById("pageCanvasEdgePaths")
    ?.querySelectorAll(".page-canvas-edge-group")
    .forEach((el) => {
      el.classList.toggle("is-selected", selection.edges.includes(el.dataset.edgeId));
    });
}

function setCanvasSelection({ nodes = [], edges = [] } = {}) {
  pageCanvasState.selection = {
    nodes: Array.from(new Set(nodes.filter(Boolean))),
    edges: Array.from(new Set(edges.filter(Boolean))),
  };
  refreshCanvasSelectionClasses();
}
function setCanvasNodeSelection(nodeIds) {
  setCanvasSelection({ nodes: Array.isArray(nodeIds) ? nodeIds : [nodeIds] });
}
function clearCanvasSelection() {
  setCanvasSelection({});
}
function toggleCanvasNodeSelection(nodeId) {
  const selection = getCanvasSelection();
  const nodes = selection.nodes.includes(nodeId)
    ? selection.nodes.filter((id) => id !== nodeId)
    : [...selection.nodes, nodeId];
  setCanvasSelection({ nodes, edges: selection.edges });
}
function toggleCanvasEdgeSelection(edgeId) {
  const selection = getCanvasSelection();
  const edges = selection.edges.includes(edgeId)
    ? selection.edges.filter((id) => id !== edgeId)
    : [...selection.edges, edgeId];
  setCanvasSelection({ nodes: selection.nodes, edges });
}

function commitCanvasNodeEdit() {
  const nodeId = pageCanvasState.editingNodeId;
  if (!nodeId) return;
  pageCanvasState.editingNodeId = null;
  const node = getCanvasNodeById(nodeId);
  const el = getPageCanvasNodeEl(nodeId);
  const textEl = el?.querySelector(".page-canvas-node-text");
  if (el) el.classList.remove("is-editing");
  if (textEl) {
    textEl.contentEditable = "false";
    if (node) {
      const text = textEl.innerText.replace(/ /g, " ").replace(/\n+$/, "");
      if (text !== node.text) {
        node.text = text;
        queuePageCanvasSave();
      }
      textEl.textContent = node.text;
    }
  }
  // Keep node.w in sync with the auto-sized box so edge routing and Fit stay correct.
  if (node && el && isCanvasNodeAutoWidth(node)) {
    const measured = Math.round(el.offsetWidth);
    if (measured > 0) node.w = measured;
  }
  if (node) updateCanvasEdgesForNode(node.id);
}

function setCanvasTextEditable(textEl, editable) {
  if (!editable) {
    textEl.contentEditable = "false";
    return;
  }
  // plaintext-only makes Enter insert a real newline and keeps pasted text unformatted.
  try {
    textEl.contentEditable = "plaintext-only";
  } catch (_) {}
  if (textEl.contentEditable !== "plaintext-only") textEl.contentEditable = "true";
}

function enterCanvasNodeEdit(nodeId) {
  const node = getCanvasNodeById(nodeId);
  const el = getPageCanvasNodeEl(nodeId);
  const textEl = el?.querySelector(".page-canvas-node-text");
  if (!node || node.type !== "text" || !el || !textEl) return;
  if (pageCanvasState.editingNodeId === nodeId) return; // already editing: leave the caret alone
  if (pageCanvasState.editingNodeId) {
    commitCanvasNodeEdit();
  }
  pageCanvasState.editingNodeId = nodeId;
  setCanvasNodeSelection([nodeId]);
  el.classList.add("is-editing");
  setCanvasTextEditable(textEl, true);
  textEl.focus();
  const range = document.createRange();
  range.selectNodeContents(textEl);
  range.collapse(false);
  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(range);
}

function createCanvasTextNode(worldPt, { edit = true } = {}) {
  const canvas = getPageCanvasData();
  if (!canvas) return null;
  const node = {
    id: createId("cnode"),
    type: "text",
    x: Math.round(worldPt.x),
    y: Math.round(worldPt.y),
    w: 200,
    h: 0,
    text: "",
    autoW: true,
  };
  canvas.nodes.push(node);
  getPageCanvasNodesEl()?.appendChild(renderCanvasNode(node));
  updateCanvasEmptyHint();
  setCanvasNodeSelection([node.id]);
  queuePageCanvasSave();
  if (edit) enterCanvasNodeEdit(node.id);
  return node;
}

function deleteCanvasNode(nodeId) {
  deleteCanvasItems([nodeId], []);
}

function deleteCanvasEdge(edgeId) {
  deleteCanvasItems([], [edgeId]);
}

function deleteCanvasItems(nodeIds, edgeIds) {
  const canvas = getPageCanvasData();
  if (!canvas) return;
  const doomedNodes = new Set(nodeIds);
  const doomedEdges = new Set(edgeIds);
  if (!doomedNodes.size && !doomedEdges.size) return;
  if (pageCanvasState.editingNodeId && doomedNodes.has(pageCanvasState.editingNodeId)) {
    // Drop the pending edit rather than committing text onto a node we're deleting.
    const editingEl = getPageCanvasNodeEl(pageCanvasState.editingNodeId);
    editingEl?.classList.remove("is-editing");
    pageCanvasState.editingNodeId = null;
  } else {
    commitCanvasNodeEdit();
  }
  canvas.nodes = canvas.nodes.filter((node) => !doomedNodes.has(node.id));
  canvas.edges = canvas.edges.filter(
    (edge) => !doomedEdges.has(edge.id) && !doomedNodes.has(edge.from) && !doomedNodes.has(edge.to)
  );
  const selection = getCanvasSelection();
  pageCanvasState.selection = {
    nodes: selection.nodes.filter((id) => !doomedNodes.has(id)),
    edges: selection.edges.filter(
      (id) => !doomedEdges.has(id) && canvas.edges.some((edge) => edge.id === id)
    ),
  };
  renderCanvasNodes();
  renderCanvasEdges();
  queuePageCanvasSave();
}

function deleteCanvasSelection() {
  const selection = getCanvasSelection();
  deleteCanvasItems([...selection.nodes], [...selection.edges]);
}

function createCanvasEdge(fromId, toId) {
  const canvas = getPageCanvasData();
  if (!canvas || !fromId || !toId || fromId === toId) return;
  const exists = canvas.edges.some(
    (edge) =>
      (edge.from === fromId && edge.to === toId) ||
      (edge.from === toId && edge.to === fromId)
  );
  if (exists) return;
  canvas.edges.push({ id: createId("cedge"), from: fromId, to: toId });
  renderCanvasEdges();
  queuePageCanvasSave();
}

function applyCanvasZoom(nextScaleRaw, focusClientX, focusClientY) {
  const canvas = getPageCanvasData();
  const viewport = getPageCanvasViewportEl();
  if (!canvas || !viewport) return;
  const view = canvas.view;
  const nextScale = Math.min(
    PAGE_CANVAS_MAX_SCALE,
    Math.max(PAGE_CANVAS_MIN_SCALE, nextScaleRaw)
  );
  if (nextScale === view.scale) return;
  const rect = viewport.getBoundingClientRect();
  const fx = focusClientX - rect.left;
  const fy = focusClientY - rect.top;
  const worldX = (fx - view.x) / view.scale;
  const worldY = (fy - view.y) / view.scale;
  view.scale = nextScale;
  view.x = fx - worldX * nextScale;
  view.y = fy - worldY * nextScale;
  updateCanvasViewTransform();
  queuePageCanvasSave();
}

function fitCanvasView() {
  const canvas = getPageCanvasData();
  const viewport = getPageCanvasViewportEl();
  if (!canvas || !viewport) return;
  const view = canvas.view;
  if (!canvas.nodes.length) {
    view.x = 0;
    view.y = 0;
    view.scale = 1;
    updateCanvasViewTransform();
    queuePageCanvasSave();
    return;
  }
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  canvas.nodes.forEach((node) => {
    const rect = getCanvasNodeRect(node);
    minX = Math.min(minX, rect.x);
    minY = Math.min(minY, rect.y);
    maxX = Math.max(maxX, rect.x + rect.w);
    maxY = Math.max(maxY, rect.y + rect.h);
  });
  const pad = 60;
  const vw = viewport.clientWidth;
  const vh = viewport.clientHeight;
  const bw = Math.max(1, maxX - minX);
  const bh = Math.max(1, maxY - minY);
  const scale = Math.min(
    PAGE_CANVAS_MAX_SCALE,
    Math.max(PAGE_CANVAS_MIN_SCALE, Math.min((vw - pad * 2) / bw, (vh - pad * 2) / bh, 1.5))
  );
  view.scale = scale;
  view.x = (vw - bw * scale) / 2 - minX * scale;
  view.y = (vh - bh * scale) / 2 - minY * scale;
  updateCanvasViewTransform();
  queuePageCanvasSave();
}

async function insertCanvasImageFiles(files, worldPt) {
  const canvas = getPageCanvasData();
  if (!canvas || !window.pywebview?.api?.save_page_asset) return;
  const imageFiles = Array.from(files || []).filter((file) =>
    String(file.type || "").toLowerCase().startsWith("image/")
  );
  let offset = 0;
  const insertedIds = [];
  for (const file of imageFiles) {
    try {
      const dataUrl = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ""));
        reader.onerror = () => reject(reader.error);
        reader.readAsDataURL(file);
      });
      if (!dataUrl.startsWith("data:image/")) continue;
      const dims = await new Promise((resolve) => {
        const probe = new Image();
        probe.onload = () =>
          resolve({ w: probe.naturalWidth || 300, h: probe.naturalHeight || 200 });
        probe.onerror = () => resolve({ w: 300, h: 200 });
        probe.src = dataUrl;
      });
      const res = await window.pywebview.api.save_page_asset(
        pageEditorOwnerKey || "page",
        dataUrl,
        file.name || "image.png"
      );
      if (res?.status !== "success" || !res.assetPath) {
        toast(res?.message || "Could not save image");
        continue;
      }
      const scale = Math.min(1, 400 / dims.w);
      const node = {
        id: createId("cnode"),
        type: "image",
        x: Math.round(worldPt.x + offset),
        y: Math.round(worldPt.y + offset),
        w: Math.round(dims.w * scale),
        h: Math.round(dims.h * scale),
        assetPath: res.assetPath,
      };
      canvas.nodes.push(node);
      getPageCanvasNodesEl()?.appendChild(renderCanvasNode(node));
      insertedIds.push(node.id);
      offset += 24;
    } catch (e) {
      console.warn("Canvas image insert failed:", e);
    }
  }
  if (insertedIds.length) setCanvasNodeSelection(insertedIds);
  updateCanvasEmptyHint();
  queuePageCanvasSave();
}

function updateCanvasEdgeDraftPath(fromNode, worldPt) {
  const draft = document.getElementById("pageCanvasEdgeDraft");
  if (!draft) return;
  const rect = getCanvasNodeRect(fromNode);
  const target = { x: worldPt.x, y: worldPt.y, w: 0, h: 0 };
  draft.setAttribute("d", computeCanvasEdgePathBetween(rect, target));
  draft.hidden = false;
}

function findCanvasNodeElAtPoint(clientX, clientY) {
  const el = document.elementFromPoint(clientX, clientY);
  return el?.closest?.(".page-canvas-node") || null;
}

function isCanvasAdditiveEvent(e) {
  return !!(e.ctrlKey || e.metaKey || e.shiftKey);
}

function updateCanvasMarqueeOverlay(gesture, e) {
  const viewport = getPageCanvasViewportEl();
  const marquee = getPageCanvasMarqueeEl();
  if (!viewport || !marquee) return;
  const rect = viewport.getBoundingClientRect();
  const x1 = gesture.startX - rect.left;
  const y1 = gesture.startY - rect.top;
  const x2 = e.clientX - rect.left;
  const y2 = e.clientY - rect.top;
  marquee.style.left = `${Math.min(x1, x2)}px`;
  marquee.style.top = `${Math.min(y1, y2)}px`;
  marquee.style.width = `${Math.abs(x2 - x1)}px`;
  marquee.style.height = `${Math.abs(y2 - y1)}px`;
  marquee.hidden = false;
}

function applyCanvasMarqueeSelection(gesture, e) {
  const canvas = getPageCanvasData();
  if (!canvas) return;
  const current = getCanvasWorldPoint(e);
  const minX = Math.min(gesture.startWorld.x, current.x);
  const maxX = Math.max(gesture.startWorld.x, current.x);
  const minY = Math.min(gesture.startWorld.y, current.y);
  const maxY = Math.max(gesture.startWorld.y, current.y);
  const hits = canvas.nodes
    .filter((node) => {
      const rect = getCanvasNodeRect(node);
      // Intersection, not containment: brushing an item is enough to grab it.
      return (
        rect.x < maxX && rect.x + rect.w > minX && rect.y < maxY && rect.y + rect.h > minY
      );
    })
    .map((node) => node.id);
  setCanvasSelection({
    nodes: gesture.additive ? [...gesture.baseNodes, ...hits] : hits,
    edges: gesture.additive ? gesture.baseEdges : [],
  });
}

function endCanvasMarquee() {
  const marquee = getPageCanvasMarqueeEl();
  if (marquee) marquee.hidden = true;
}

function hideCanvasContextMenu() {
  if (!canvasContextMenu) return;
  canvasContextMenu.hidden = true;
}

function ensureCanvasContextMenu() {
  if (canvasContextMenu) return canvasContextMenu;

  const menu = el("div", {
    className: "canvas-context-menu",
    role: "menu",
  });
  menu.hidden = true;

  const panelScheduleItem = el("button", {
    className: "canvas-context-menu__item",
    type: "button",
    role: "menuitem",
    textContent: "Convert to Panel Schedule with AI",
    "data-canvas-menu-action": "panelSchedule",
  });
  menu.append(panelScheduleItem);

  menu.addEventListener("click", (event) => {
    const item = event.target.closest("button[data-canvas-menu-action]");
    if (!item || item.disabled) return;
    event.preventDefault();
    event.stopPropagation();
    hideCanvasContextMenu();
    void openCanvasPanelScheduleDialog();
  });

  document.body.appendChild(menu);
  canvasContextMenu = menu;

  if (!canvasContextMenuHandlersReady) {
    // pointerdown, not click: a right-click elsewhere never fires click, so a click
    // listener would leave the menu stranded on screen.
    document.addEventListener(
      "pointerdown",
      (event) => {
        if (
          canvasContextMenu &&
          !canvasContextMenu.hidden &&
          !canvasContextMenu.contains(event.target)
        ) {
          hideCanvasContextMenu();
        }
      },
      true
    );
    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape") hideCanvasContextMenu();
    });
    window.addEventListener("resize", hideCanvasContextMenu);
    document.addEventListener("scroll", hideCanvasContextMenu, true);
    canvasContextMenuHandlersReady = true;
  }

  return menu;
}

function showCanvasContextMenu(event) {
  event.preventDefault();
  event.stopPropagation();

  const menu = ensureCanvasContextMenu();
  const imageCount = getSelectedCanvasImageNodes().length;
  // Stays reachable with nothing selected while an analysis is running or its
  // findings are still waiting to be reviewed.
  const hasPendingWork =
    !!canvasPanelScheduleState.job || !!canvasPanelScheduleState.pendingResult;
  const item = menu.querySelector('button[data-canvas-menu-action="panelSchedule"]');
  if (item) {
    item.disabled = imageCount === 0 && !hasPendingWork;
    item.textContent = canvasPanelScheduleState.pendingResult
      ? "Review panel schedule findings"
      : canvasPanelScheduleState.job
        ? "Panel schedule analysis running..."
        : "Convert to Panel Schedule with AI";
    item.title = item.disabled ? "Select at least one image on the canvas." : "";
  }

  menu.hidden = false;
  menu.style.visibility = "hidden";
  menu.style.left = "0px";
  menu.style.top = "0px";

  const viewportPadding = 8;
  const rect = menu.getBoundingClientRect();
  const left = Math.min(
    Math.max(viewportPadding, event.clientX),
    Math.max(viewportPadding, window.innerWidth - rect.width - viewportPadding)
  );
  const top = Math.min(
    Math.max(viewportPadding, event.clientY),
    Math.max(viewportPadding, window.innerHeight - rect.height - viewportPadding)
  );
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
  menu.style.visibility = "";
  menu.querySelector("button[data-canvas-menu-action]:not([disabled])")?.focus();
}

function handleCanvasContextMenu(e) {
  const canvas = getPageCanvasData();
  if (!canvas) return;

  const nodeEl = e.target?.closest?.(".page-canvas-node");
  const nodeId = nodeEl?.dataset.nodeId || "";

  // Leave the native menu (spell-check, paste) alone inside the box being edited.
  if (
    nodeId &&
    pageCanvasState.editingNodeId === nodeId &&
    e.target?.closest?.(".page-canvas-node-text")
  ) {
    return;
  }
  if (pageCanvasState.editingNodeId && pageCanvasState.editingNodeId !== nodeId) {
    commitCanvasNodeEdit();
  }

  // Right-click selects the item under the cursor unless it is already selected.
  if (nodeId && !isCanvasNodeSelected(nodeId)) setCanvasNodeSelection([nodeId]);
  showCanvasContextMenu(e);
}

function handleCanvasPointerDown(e) {
  const viewport = getPageCanvasViewportEl();
  const canvas = getPageCanvasData();
  if (!viewport || !canvas || pageCanvasState.pointer) return;
  if (e.button !== 0 && e.button !== 1) return;

  const nodeEl = e.target?.closest?.(".page-canvas-node");
  const nodeId = nodeEl?.dataset.nodeId || null;
  const node = nodeId ? getCanvasNodeById(nodeId) : null;
  const panRequested = e.button === 1 || pageCanvasState.spaceDown;

  // Keep default behavior (caret/selection) while typing inside a text node.
  if (
    !panRequested &&
    node &&
    pageCanvasState.editingNodeId === node.id &&
    e.target.closest(".page-canvas-node-text")
  ) {
    return;
  }
  if (pageCanvasState.editingNodeId && pageCanvasState.editingNodeId !== nodeId) {
    commitCanvasNodeEdit();
  }

  const additive = isCanvasAdditiveEvent(e);
  const edgeGroup = e.target?.closest?.(".page-canvas-edge-group");
  if (!panRequested && edgeGroup) {
    const edgeId = edgeGroup.dataset.edgeId;
    if (additive) toggleCanvasEdgeSelection(edgeId);
    else setCanvasSelection({ edges: [edgeId] });
    viewport.focus();
    e.preventDefault();
    return;
  }

  e.preventDefault();
  viewport.focus();

  // Ctrl/Cmd/Shift+click on an item toggles it in the selection without starting a drag.
  if (!panRequested && node && additive) {
    toggleCanvasNodeSelection(node.id);
    return;
  }

  try {
    viewport.setPointerCapture(e.pointerId);
  } catch (_) {}

  if (!panRequested && node && e.target.closest(".page-canvas-node-connector")) {
    pageCanvasState.pointer = {
      mode: "edge",
      pointerId: e.pointerId,
      fromId: node.id,
      targetEl: null,
    };
    setCanvasNodeSelection([node.id]);
    updateCanvasEdgeDraftPath(node, getCanvasWorldPoint(e));
    return;
  }

  if (!panRequested && node && e.target.closest(".page-canvas-node-handle")) {
    pageCanvasState.pointer = {
      mode: "resize",
      pointerId: e.pointerId,
      nodeId: node.id,
      startX: e.clientX,
      startY: e.clientY,
      startW: getCanvasNodeRect(node).w,
      startH: node.h || getCanvasNodeRect(node).h,
      aspect: node.type === "image" && node.h > 0 ? node.w / node.h : 0,
      moved: false,
    };
    setCanvasNodeSelection([node.id]);
    return;
  }

  if (!panRequested && node) {
    // Dragging any selected item moves the whole selection; dragging an unselected
    // item selects just it first.
    const wasSelected = isCanvasNodeSelected(node.id);
    const wasSoleSelection = wasSelected && getSelectedCanvasNodeIds().length === 1;
    if (!wasSelected) setCanvasNodeSelection([node.id]);
    const dragging = getSelectedCanvasNodes();
    pageCanvasState.pointer = {
      mode: "node",
      pointerId: e.pointerId,
      clickedId: node.id,
      wasSoleSelection,
      nodes: dragging.map((item) => ({ id: item.id, origX: item.x, origY: item.y })),
      startX: e.clientX,
      startY: e.clientY,
      moved: false,
    };
    dragging.forEach((item) => getPageCanvasNodeEl(item.id)?.classList.add("is-dragging"));
    return;
  }

  if (panRequested) {
    pageCanvasState.pointer = {
      mode: "pan",
      pointerId: e.pointerId,
      startX: e.clientX,
      startY: e.clientY,
      origX: canvas.view.x,
      origY: canvas.view.y,
      moved: false,
    };
    viewport.classList.add("is-panning");
    return;
  }

  // Empty space: rubber-band select. (Panning lives on space-drag / middle-drag.)
  const selection = getCanvasSelection();
  pageCanvasState.pointer = {
    mode: "marquee",
    pointerId: e.pointerId,
    startX: e.clientX,
    startY: e.clientY,
    startWorld: getCanvasWorldPoint(e),
    additive,
    baseNodes: [...selection.nodes],
    baseEdges: [...selection.edges],
    moved: false,
  };
  if (!additive) clearCanvasSelection();
}

function handleCanvasPointerMove(e) {
  const gesture = pageCanvasState.pointer;
  const canvas = getPageCanvasData();
  if (!gesture || !canvas || e.pointerId !== gesture.pointerId) return;

  if (gesture.mode === "pan") {
    canvas.view.x = gesture.origX + (e.clientX - gesture.startX);
    canvas.view.y = gesture.origY + (e.clientY - gesture.startY);
    gesture.moved = true;
    updateCanvasViewTransform();
    return;
  }
  if (gesture.mode === "marquee") {
    if (
      !gesture.moved &&
      Math.abs(e.clientX - gesture.startX) < PAGE_CANVAS_DRAG_THRESHOLD_PX &&
      Math.abs(e.clientY - gesture.startY) < PAGE_CANVAS_DRAG_THRESHOLD_PX
    ) {
      return;
    }
    gesture.moved = true;
    updateCanvasMarqueeOverlay(gesture, e);
    applyCanvasMarqueeSelection(gesture, e);
    return;
  }
  if (gesture.mode === "node") {
    // Ignore jitter so a click that happens to wobble still counts as a click.
    const screenDx = e.clientX - gesture.startX;
    const screenDy = e.clientY - gesture.startY;
    if (!gesture.moved && Math.abs(screenDx) < PAGE_CANVAS_DRAG_THRESHOLD_PX &&
        Math.abs(screenDy) < PAGE_CANVAS_DRAG_THRESHOLD_PX) {
      return;
    }
    // Round the delta once so items in the group keep their exact relative spacing.
    const dx = Math.round(screenDx / canvas.view.scale);
    const dy = Math.round(screenDy / canvas.view.scale);
    gesture.moved = true;
    gesture.nodes.forEach((entry) => {
      const node = getCanvasNodeById(entry.id);
      const el = getPageCanvasNodeEl(entry.id);
      if (!node || !el) return;
      node.x = entry.origX + dx;
      node.y = entry.origY + dy;
      el.style.left = `${node.x}px`;
      el.style.top = `${node.y}px`;
      updateCanvasEdgesForNode(node.id);
    });
    return;
  }
  if (gesture.mode === "resize") {
    const node = getCanvasNodeById(gesture.nodeId);
    const el = getPageCanvasNodeEl(gesture.nodeId);
    if (!node || !el) return;
    const dw = (e.clientX - gesture.startX) / canvas.view.scale;
    node.w = Math.round(Math.max(60, gesture.startW + dw));
    if (node.type === "text") {
      // Dragging the handle pins an explicit width.
      node.autoW = false;
      el.classList.remove("is-auto-width");
    }
    el.style.width = `${node.w}px`;
    if (gesture.aspect > 0) {
      node.h = Math.round(node.w / gesture.aspect);
      el.style.height = `${node.h}px`;
    } else if (node.type === "image") {
      const dh = (e.clientY - gesture.startY) / canvas.view.scale;
      node.h = Math.round(Math.max(40, gesture.startH + dh));
      el.style.height = `${node.h}px`;
    }
    gesture.moved = true;
    updateCanvasEdgesForNode(node.id);
    return;
  }
  if (gesture.mode === "edge") {
    const fromNode = getCanvasNodeById(gesture.fromId);
    if (!fromNode) return;
    updateCanvasEdgeDraftPath(fromNode, getCanvasWorldPoint(e));
    const targetEl = findCanvasNodeElAtPoint(e.clientX, e.clientY);
    if (gesture.targetEl && gesture.targetEl !== targetEl) {
      gesture.targetEl.classList.remove("is-edge-target");
    }
    if (targetEl && targetEl.dataset.nodeId !== gesture.fromId) {
      targetEl.classList.add("is-edge-target");
      gesture.targetEl = targetEl;
    } else {
      gesture.targetEl = null;
    }
  }
}

function handleCanvasPointerUp(e) {
  const gesture = pageCanvasState.pointer;
  const viewport = getPageCanvasViewportEl();
  if (!gesture || e.pointerId !== gesture.pointerId) return;
  pageCanvasState.pointer = null;
  viewport?.classList.remove("is-panning");
  try {
    viewport?.releasePointerCapture(e.pointerId);
  } catch (_) {}

  if (gesture.mode === "pan") {
    if (gesture.moved) queuePageCanvasSave();
    return;
  }
  if (gesture.mode === "marquee") {
    endCanvasMarquee();
    return;
  }
  if (gesture.mode === "node") {
    gesture.nodes.forEach((entry) =>
      getPageCanvasNodeEl(entry.id)?.classList.remove("is-dragging")
    );
    if (gesture.moved) {
      queuePageCanvasSave();
      return;
    }
    // A click that didn't move: collapse a group to the clicked item, or — if that
    // item was already the only thing selected — start editing it.
    const clicked = getCanvasNodeById(gesture.clickedId);
    if (gesture.nodes.length > 1) {
      setCanvasNodeSelection([gesture.clickedId]);
    } else if (gesture.wasSoleSelection && clicked?.type === "text") {
      enterCanvasNodeEdit(gesture.clickedId);
    }
    return;
  }
  if (gesture.mode === "resize") {
    if (gesture.moved) queuePageCanvasSave();
    return;
  }
  if (gesture.mode === "edge") {
    const draft = document.getElementById("pageCanvasEdgeDraft");
    if (draft) draft.hidden = true;
    gesture.targetEl?.classList.remove("is-edge-target");
    const targetEl = findCanvasNodeElAtPoint(e.clientX, e.clientY);
    const targetId = targetEl?.dataset.nodeId;
    if (targetId && targetId !== gesture.fromId) {
      createCanvasEdge(gesture.fromId, targetId);
      setCanvasNodeSelection([targetId]);
    }
  }
}

function cancelCanvasGesture() {
  const gesture = pageCanvasState.pointer;
  const viewport = getPageCanvasViewportEl();
  if (!gesture) return false;
  pageCanvasState.pointer = null;
  viewport?.classList.remove("is-panning");
  if (gesture.mode === "edge") {
    const draft = document.getElementById("pageCanvasEdgeDraft");
    if (draft) draft.hidden = true;
    gesture.targetEl?.classList.remove("is-edge-target");
  }
  if (gesture.mode === "marquee") {
    endCanvasMarquee();
    setCanvasSelection({ nodes: gesture.baseNodes, edges: gesture.baseEdges });
  }
  if (gesture.mode === "node") {
    gesture.nodes.forEach((entry) =>
      getPageCanvasNodeEl(entry.id)?.classList.remove("is-dragging")
    );
  }
  return true;
}

function handleCanvasKeyDown(e) {
  const canvas = getPageCanvasData();
  if (!canvas) return;
  const editing = !!pageCanvasState.editingNodeId;

  if (e.key === " " && !editing) {
    pageCanvasState.spaceDown = true;
  }
  if (e.key === "Escape") {
    if (cancelCanvasGesture()) {
      e.preventDefault();
      e.stopPropagation();
      return;
    }
    if (editing) {
      e.preventDefault();
      e.stopPropagation();
      commitCanvasNodeEdit();
      getPageCanvasViewportEl()?.focus();
      return;
    }
    if (hasCanvasSelection()) {
      e.preventDefault();
      e.stopPropagation();
      clearCanvasSelection();
      return;
    }
    return; // bubble up: page view handles Escape as "go back"
  }
  if (editing) {
    // Enter inserts a newline in the box; never let it reach the page-level handlers.
    if (e.key === "Enter") e.stopPropagation();
    return;
  }
  if ((e.ctrlKey || e.metaKey) && (e.key === "a" || e.key === "A")) {
    e.preventDefault();
    e.stopPropagation();
    setCanvasNodeSelection(canvas.nodes.map((node) => node.id));
    return;
  }
  if (e.key === "Delete" || e.key === "Backspace") {
    if (!hasCanvasSelection()) return;
    e.preventDefault();
    e.stopPropagation();
    deleteCanvasSelection();
    return;
  }
  if (e.key === "Enter") {
    const selected = getSelectedCanvasNodes();
    if (selected.length === 1 && selected[0].type === "text") {
      e.preventDefault();
      enterCanvasNodeEdit(selected[0].id);
    }
  }
}

function handleCanvasDblClick(e) {
  const canvas = getPageCanvasData();
  if (!canvas) return;
  const nodeEl = e.target?.closest?.(".page-canvas-node");
  if (nodeEl) {
    const node = getCanvasNodeById(nodeEl.dataset.nodeId);
    if (!node) return;
    // Double-clicking the resize handle of a pinned text box returns it to auto-size.
    if (e.target.closest(".page-canvas-node-handle")) {
      if (node.type === "text" && node.autoW === false) {
        node.autoW = true;
        applyCanvasNodeWidth(node, nodeEl);
        const measured = Math.round(nodeEl.offsetWidth);
        if (measured > 0) node.w = measured;
        updateCanvasEdgesForNode(node.id);
        queuePageCanvasSave();
      }
      return;
    }
    if (node.type === "text") {
      enterCanvasNodeEdit(node.id);
    } else if (node.type === "image") {
      const img = nodeEl.querySelector("img.page-canvas-node-img");
      if (img?.src) {
        openImagePreviewDialog({
          dataUrl: img.src,
          filename: "Image",
          width: img.naturalWidth || 1,
          height: img.naturalHeight || 1,
        });
      }
    }
    return;
  }
  if (e.target?.closest?.(".page-canvas-edge-group")) return;
  createCanvasTextNode(getCanvasWorldPoint(e));
}

function handleCanvasWheel(e) {
  const canvas = getPageCanvasData();
  if (!canvas) return;
  e.preventDefault();
  const factor = Math.exp(-e.deltaY * 0.0016);
  applyCanvasZoom(canvas.view.scale * factor, e.clientX, e.clientY);
}

function ensurePageCanvasReady() {
  if (pageCanvasInitialized) return;
  const viewport = getPageCanvasViewportEl();
  if (!viewport) return;
  pageCanvasInitialized = true;

  viewport.addEventListener("pointerdown", handleCanvasPointerDown);
  viewport.addEventListener("pointermove", handleCanvasPointerMove);
  viewport.addEventListener("pointerup", handleCanvasPointerUp);
  viewport.addEventListener("pointercancel", () => cancelCanvasGesture());
  viewport.addEventListener("dblclick", handleCanvasDblClick);
  viewport.addEventListener("contextmenu", handleCanvasContextMenu);
  viewport.addEventListener("wheel", handleCanvasWheel, { passive: false });
  viewport.addEventListener("keydown", handleCanvasKeyDown);
  viewport.addEventListener("keyup", (e) => {
    if (e.key === " ") pageCanvasState.spaceDown = false;
  });

  // Commit text edits when focus leaves the node being edited.
  viewport.addEventListener("focusout", (e) => {
    if (!pageCanvasState.editingNodeId) return;
    const editingEl = getPageCanvasNodeEl(pageCanvasState.editingNodeId);
    if (editingEl && e.relatedTarget && editingEl.contains(e.relatedTarget)) return;
    commitCanvasNodeEdit();
  });
  viewport.addEventListener("input", (e) => {
    if (!pageCanvasState.editingNodeId) return;
    if (!e.target?.closest?.(".page-canvas-node-text")) return;
    updateCanvasEdgesForNode(pageCanvasState.editingNodeId);
  });

  viewport.addEventListener("paste", (e) => {
    const files = getPageClipboardImageFiles(e.clipboardData);
    if (files.length) {
      e.preventDefault();
      insertCanvasImageFiles(files, getCanvasViewportCenterWorldPoint());
    }
  });
  viewport.addEventListener("dragover", (e) => {
    if (Array.from(e.dataTransfer?.types || []).includes("Files")) {
      e.preventDefault();
      viewport.classList.add("is-drop-target");
    }
  });
  viewport.addEventListener("dragleave", () => {
    viewport.classList.remove("is-drop-target");
  });
  viewport.addEventListener("drop", (e) => {
    viewport.classList.remove("is-drop-target");
    const files = Array.from(e.dataTransfer?.files || []);
    if (files.length) {
      e.preventDefault();
      insertCanvasImageFiles(files, getCanvasWorldPoint(e));
    }
  });

  const titleInput = document.getElementById("pageCanvasTitle");
  titleInput?.addEventListener("input", () => {
    handleProjectPagesEditorTitleChange(titleInput.value);
  });
  titleInput?.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      viewport.focus();
    }
  });

  document.getElementById("pageCanvasAddTextBtn")?.addEventListener("click", () => {
    createCanvasTextNode(getCanvasViewportCenterWorldPoint());
  });
  document.getElementById("pageCanvasAddImageBtn")?.addEventListener("click", () => {
    document.getElementById("pageCanvasImageInput")?.click();
  });
  document.getElementById("pageCanvasImageInput")?.addEventListener("change", (e) => {
    const files = e.target.files;
    if (files?.length) insertCanvasImageFiles(files, getCanvasViewportCenterWorldPoint());
    e.target.value = "";
  });
  document.getElementById("pageCanvasZoomFitBtn")?.addEventListener("click", fitCanvasView);
}

function renderPageCanvasView() {
  ensurePageCanvasReady();
  if (!isCanvasPage(pageEditorTarget)) return;
  pageEditorTarget.canvas = normalizePageCanvas(pageEditorTarget.canvas);
  resetPageCanvasState();
  const { project, subpage, globalPage } = pageNav;
  setProjectPagesEditorDocument({
    documentKey: `canvas:${globalPage?.id || subpage?.id || project?.id || "x"}`,
    navigationOnly: true,
    kind: globalPage ? "global" : subpage ? "subpage" : "project",
    project, subpage, globalPage,
    title: (globalPage ? globalPage.title : subpage ? subpage.title : project?.name) || "",
  });
  const titleInput = document.getElementById("pageCanvasTitle");
  if (titleInput) {
    titleInput.value =
      (globalPage ? globalPage.title : subpage ? subpage.title : project?.name) || "";
  }
  renderCanvasNodes();
  renderCanvasEdges();
  updateCanvasViewTransform();
  setTimeout(() => getPageCanvasViewportEl()?.focus(), 0);
}

init();

function confirmCleanDrawingSelection(preview) {
  return new Promise(resolve => {
    const dialog = document.createElement("dialog");
    dialog.className = "clean-drawings-dialog";
    const form = document.createElement("form");
    form.method = "dialog";
    const heading = document.createElement("h2"); heading.textContent = "Clean Drawings"; form.append(heading);
    const note = document.createElement("p");
    note.textContent = "Select the border/titleblock XREF, not a site or plan background. Cleanup removes identifiable titleblock stamps/signatures from local copies and converts supported PDFs/images. Original and cleaned PDFs are compared; other differences are flagged for review.";
    form.append(note);
    function field(text, control) {
      const label = document.createElement("label"); label.append(document.createTextNode(text), control); form.append(label); return control;
    }
    const titleblock = field("Titleblock XREF", document.createElement("select"));
    titleblock.required = true;
    titleblock.add(new Option("Select the titleblock XREF…", ""));
    preview.titleblocks.forEach(path => titleblock.add(new Option(
      `${path}${path === preview.recommendedTitleblock ? " (recommended titleblock)" : preview.detectedTitleblocks?.includes(path) ? " (paper-space XREF; verify its purpose)" : ""}`, path)));
    if (preview.recommendedTitleblock) titleblock.value = preview.recommendedTitleblock;
    const pdf = field("Reference PDF and sheet size", document.createElement("select"));
    pdf.add(new Option("Enter dimensions manually", ""));
    preview.sizes.forEach((size, index) => pdf.add(new Option(`${size.pdf}, page ${size.page}: ${size.width} x ${size.height} in`, String(index))));
    const width = field("Width in CAD units", document.createElement("input"));
    const height = field("Height in CAD units", document.createElement("input"));
    const dimensions = document.createElement("div"); dimensions.className = "clean-drawings-size";
    dimensions.append(width.parentElement, height.parentElement); form.append(dimensions);
    [width, height].forEach(input => { input.type = "number"; input.min = "0.001"; input.max = "1000"; input.step = "any"; input.required = true; });
    pdf.addEventListener("change", () => {
      if (pdf.value !== "") { const size = preview.sizes[Number(pdf.value)]; width.value = size.width; height.value = size.height; }
    });
    if (preview.sizes.length) { pdf.value = "0"; pdf.dispatchEvent(new Event("change")); }
    const unitNote = document.createElement("p");
    unitNote.textContent = "PDF dimensions are inches. Confirm the CAD dimensions; for a 36 x 24 inch titleblock use 36 and 24."; form.append(unitNote);
    const files = document.createElement("fieldset");
    const legend = document.createElement("legend"); legend.textContent = "Electrical drawings"; files.append(legend);
    const checks = preview.drawings.map(path => {
      const label = document.createElement("label"); const check = document.createElement("input");
      check.type = "checkbox"; check.checked = true; check.value = path;
      label.append(check, document.createTextNode(path)); files.append(label); return check;
    });
    form.append(files);
    const error = document.createElement("p"); error.setAttribute("role", "alert"); form.append(error);
    const cancel = document.createElement("button"); cancel.type = "button"; cancel.className = "btn ghost"; cancel.textContent = "Cancel";
    cancel.addEventListener("click", () => dialog.close());
    const submit = document.createElement("button"); submit.type = "submit"; submit.className = "btn"; submit.textContent = "Clean selected drawings";
    form.append(cancel, submit);
    let selection = null;
    form.addEventListener("submit", event => {
      event.preventDefault(); const drawings = checks.filter(check => check.checked).map(check => check.value);
      if (!titleblock.value) { error.textContent = "Select the border/titleblock XREF."; return; }
      if (!drawings.length) { error.textContent = "Select at least one electrical drawing."; return; }
      selection = { titleblock: titleblock.value, drawings, width: Number(width.value), height: Number(height.value), pdfSource: pdf.value === "" ? null : preview.sizes[Number(pdf.value)] };
      dialog.close();
    });
    dialog.addEventListener("close", () => { dialog.remove(); resolve(selection); }, { once: true });
    dialog.append(form); document.body.append(dialog); dialog.showModal();
  });
}
